INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('booth','n.公用电话亭；货摊','/buːð/','/buːð/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('final','adj.最后的；决定性的','','','',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('receiver','n.收受者，收件人','','','',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('drought','n.旱灾，干旱','','','',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tin','n.锡；罐头','','','',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('left','adj.左边的','','','',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('resign','v.放弃','/ɹɪˈzaɪn/','/ɹɪˈzaɪn/','verb',["He resigned the crown to follow his heart.","After fighting for so long, she finally resigned to her death."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('farm','n.农场，农庄；饲养场','/fɑːɹm/','/fɑːɹm/','noun',["antenna farm","a render farm","to farm the taxes"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('miner','n.矿工','/ˈmaɪnə/','/ˈmaɪnə/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prosperity','n.繁荣；昌盛，兴旺','/pɹɒˈspɛɹ.ɪ.ti/','/pɹɑˈspɛɹ.ɪ.ti/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Britain','n.不列颠，英国','','','',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mix','v.使混合，混淆','/ˈmɪks/','/ˈmɪks/','verb',["Mix the eggs and milk with the flour until the consistency is smooth.","Don''t mix the meat recipes with the dairy recipes.","Yellow and blue paint mix to make green."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('average','n.平均数adj.平均的','/ˈævəɹɪd͡ʒ/','/ˈævəɹɪd͡ʒ/','noun',["The average of 10, 20 and 24 is (10 + 20 + 24)/3 = 18.","batting average","If you average 10, 20 and 24, you get 18."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pinch','v.捏，拧，掐掉','/pɪntʃ/','/pɪntʃ/','noun',["I gave the leather of the sofa a pinch, gauging the texture.","The children were scolded for pinching each other.","Someone has pinched my handkerchief!"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('whip','v.鞭笞；搅打n.鞭子','/wɪp/','/wɪp/','noun',["I had to use the whip to get the sheep''s attention.","I was going to vote against the bill, but the party whip came to see me and made it clear I needed to vote for it.","Did you want to add some whip to your coffee, ma''am?"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fond','adj.喜爱的；溺爱的','/fɒnd/','/fɑnd/','verb',["a fond farewell","I have fond grandparents who spoil me."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('expression','n.词句；表达；表情','/ɪkˈspɹɛʃ.ən/','/ɪkˈspɹɛʃ.ən/','noun',["The expression \"break a leg!\" should not be taken literally.","Her expression changed from joy to misery after realising her winning lottery ticket had expired.","expression from a gland"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('five','num.五，五个，第五','/fɑev/','/faɪv/','noun',["He wrote a five followed by four zeroes.","Can anyone here change a five?","All the fives are over there in the corner, next to the fours."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('agriculture','n.农业，农艺；农学','/ˈæɡɹɪˌkʌltʃə/','/ˈæɡɹɪˌkʌltʃɚ/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('anyhow','adv.无论如何','/ˈæn.i.haʊ/','/ˈæn.i.haʊ/','adverb',["Anyhow, he is dead now."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('transistor','n.晶体管','','','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('house','n.房屋，住宅；商号','/haʊs/','/hʌʊs/','noun',["This is my house and my family''s ancestral home.","On arriving at the zoo, we immediately headed for the monkey house.","After her swan-song, there wasn''t a dry eye in the house."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('knob','n.门把，拉手；旋纽','/nɒb/','/nɒb/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('religion','n.宗教信仰；宗教','/ɹɪˈlɪdʒən/','/ɹɪˈlɪdʒən/','noun',["My brother tends to value religion, but my sister not as much.","Eckankar is a new religion but Zoroastrianism is an old religion.","The monk entered religion when he was 20 years of age."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('factor','n.因素；系数；因子','/ˈfæktə/','/ˈfæktɚ/','noun',["The factor of the trading post bought the furs.","The economy was a factor in this year''s budget figures.","3 is a factor of 12, as are 2, 4 and 6."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inexpensive','adj.花费不多的，廉价的','','','adjective',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('finish','v.完成；结束n.结尾','/ˈfɪnɪʃ/','/ˈfɪnɪʃ/','noun',["The car''s finish was so shiny and new.","Be sure to finish your homework before you go to bed!","The furniture was finished in teak veneer."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('phenomenon','n.现象','/fɪˈnɒmənɒn/','/fɪˈnɒmənɒn/','noun',["An electromagnetic phenomenon.","A volcanic eruption is an impressive phenomenon."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('allow','v.允许，准许；任','/əˈlaʊ/','/əˈlaʊ/','verb',["to allow a servant his liberty;  to allow a free passage;  to allow one day for rest","to allow a right;  to allow a claim;  to allow the truth of a proposition","To allow a sum for leakage."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('keen','adj.热心的；激烈的','/kiːn/','/kin/','verb',["I’m keen on computers.","This boy has a keen appetite.","keen satire or sarcasm"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('presently','adv.一会儿；目前','/ˈpɹɛzəntli/','','adverb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('statistical','adj.统计的，统计学的','/stəˈtɪstɪkəl/','/stəˈtɪstɪkəl/','adjective',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vitamin','n.维生素，维他命','/ˈvɑet.ə.mən/','/ˈvaɪ.tə.mɪn/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('enemy','n.敌人；仇敌；敌兵','/ˈɛnəmi/','/ˈɛnəmi/','noun',["Crush the enemy!","Rally together against a common enemy."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('eight','num.八，八个','/eɪt/','/eɪt/','noun',["He works eight hours a day."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('design','v.设计n.设计；图样','/dɪˈzaɪn/','/dɪˈzaɪn/','noun',["To be hateful of the truth by design.","Danish furniture design is world-famous.","The king designed to mount an expedition to the New World."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cream','n.奶油，乳脂；奶油色','/kɹiːm/','/kɹiːm/','noun',["Take 100 ml of cream and 50 grams of sugar…","the cream of the crop;  the cream of a collection of books or pictures","You look really sunburnt; you should apply some cream."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('duty','n.责任；职责；税','/ˈdjuːti/','/duːti/','noun',["We don''t have a duty to keep you here.","I’m on duty from 6 pm to 6 am."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cousin','n.堂（或表）兄弟（姐妹）','/ˈkʌz.n̩/','/ˈkʌz.n̩/','noun',["I think my cousin is a good man."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lamb','n.羔羊，小羊；羔羊肉','/læm/','/læm/','noun',["The shepherd was up all night, lambing her young ewes."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('canteen','n.小卖部；临时餐室','/kænˈtiːn/','/kænˈtiːn/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clear','adj.清晰的v.清除','/klɪə(ɹ)/','/klɪɹ/','noun',["a room ten feet square in the clear","If you clear the table, I''ll wash up.","Please clear all this stuff off the table."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('whilst','conj.当…的时候','/hwaɪlst/','/hwaɪlst/','conjunction',["Drivers must switch off engines whilst on stand."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bake','v.烤，烘，焙；烧硬','/beɪk/','/beɪk/','noun',["I baked a delicious cherry pie.","The cake baked at 350°F.","The clay baked in the sun."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('airplane','n.飞机','/ˈɛəpleɪn/','/ˈɛəɹˌpleɪ̯n/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('coat','n.外套，上衣；皮毛','/kəʊt/','/koʊt/','noun',["When the dog shed its coat, it left hair all over the furniture and the carpet.","The frying pan was coated with a layer of non-stick material, making it easier to wash."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('intention','n.意图，意向，目的','/ɪnˈtɛnʃən/','/ɪnˈtɛnʃən/','noun',["It’s easy to promise anything when you have no intention of fulfilling any of it."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('interruption','n.障碍物；中断，打断','/ˌɪntəˈɹʌpʃən/','/ˌɪntəˈɹʌpʃən/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wreck','n.沉船，失事船v.破坏','/ˈɹɛk/','/ˈɹɛk/','noun',["He was an emotional wreck after the death of his wife.","He wrecked the car in a collision."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('affair','n.事务；事情，事件','/əˈfɛə/','/əˈfɛə(ɹ)/','noun',["a difficult affair to manage","an affair of honor, a duel;  an affair of love, an intrigue","He used a hook-shaped affair with a long handle to unlock the car."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mill','n.磨坊；制造厂','/mɪl/','/mɪl/','noun',["Pepper has a stronger flavor when it is ground straight from a mill.","My grandfather worked in a mill.","a cider mill; a cane mill"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cup','n.杯子；（一）杯；奖杯','/kʌp/','/kʌp/','noun',["Pour the tea into the cup.","I drank two cups of water but still felt thirsty.","The World Cup is awarded to the winner of a quadrennial football tournament."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chill','v.使变冷n.寒冷','/tʃɪl/','/tʃɪl/','noun',["There was a chill in the air.","Close the window or you''ll catch a chill.   I felt a chill when the wind picked up.","Despite the heat, he felt a chill as he entered the crime scene.   The actor''s eerie portrayal sent chills through the audience.   His menacing presence cast a chill over everyone."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('physicist','n.物理学家','/ˈfɪz.ɪ.sɪst/','/ˈfɪz.ɪ.sɪst/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('oppose','v.反对；反抗','/əˈpəʊz/','/əˈpoʊz/','verb',["There is still time to oppose this plan.","Many religious leaders oppose cloning humans.","They are opposed to any form of hierarchy."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hurry','v.赶紧；催促','/ˈhʌ.ɹi/','/ˈhʌ.ɹi/','noun',["Why are you in such a big hurry?","There is no hurry on that paperwork.","He''s hurrying because he''s late."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bad','adj.坏的，恶的；严重的','/bæd/','/beəd/','noun',["Abducting children is bad for mothers.","Do you think it is a bad idea to confront him directly?","It is bad manners to talk with your mouth full."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prohibit','v.禁止；阻止','/pɹəʊˈhɪbɪt/','/pɹoʊˈhɪbɪt/','verb',["The restaurant prohibits smoking on the patio."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pig','n.猪，小猪，野猪','/ˈpɪɡ/','/ˈpɪɡ/','noun',["The man kept a pen with two pigs that he fed from carrots to cabbage.","Some religions prohibit their adherents from eating pig.","You gluttonous pig! Now that you''ve eaten all the cupcakes, there will be none for the party!"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('grandfather','n.祖父；外祖父','/ˈɡɹæn(d)ˌfɑːðə(r)/','/ˈɡɹæn(d)ˌfɑðɚ/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gain','v.获得；增加n.增进','/ɡeɪn/','/ɡeɪn/','noun',["Looks like you''ve gained a new friend.","The sick man gains daily.","to gain a battle; to gain a case at law"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sideways','adv.斜着，斜向一边地','/ˈsaɪdweɪz/','/ˈsaɪdweɪz/','noun',["He gave the ball a sideways kick.","There was a stack of papers in front of each seat at the table, but each stack was sideways.","Once we get out of this sideways economy, our figures will more accurately reflect what we''re truly capable of."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('except','prep.除…之外','/ɪkˈsɛpt/','/ɛkˈsɛpt/','verb',["to except to a witness or his testimony","There was nothing in the cupboard except a tin of beans.","I never made fun of her except teasingly."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('weave','v.织，编','/wiːv/','/wiːv/','noun',["That rug has a very tight weave.","This loom weaves yarn into sweaters.","Spiders weave beautiful but deadly webs."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('consist','v.由…组成；在于','/kənˈsɪst/','/kənˈsɪst/','verb',["The greeting package consists of some brochures, a pen, and a notepad."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('heir','n.后嗣，继承人','/ɛəɹ/','/ɛəɹ/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('continual','adj.不断的；连续的','/kənˈtɪnjuəl/','/kənˈtɪnjuəl/','adjective',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('image','n.图像；映像；形象；印象','/ˈɪmɪd͡ʒ/','/ˈɪmɪd͡ʒ/','noun',["The Bible forbids the worship of graven images.","Most game console emulators do not come with any ROM images for copyright reasons.","The number 6 is the image of 3 under f that is defined as f(x) = 2x."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('insult','v.侮辱，凌辱n.侮辱，凌辱','/ɪnˈsʌlt/','/ɪnˈsʌlt/','noun',["The way the orchestra performed tonight was an insult to my ears."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unexpected','adj.想不到的，意外的','/ʌnɪkˈspɛktɪd/','/ʌnɪkˈspɛktɪd/','adjective',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('art','n.艺术，美术；技术','/ɑːt/','/ɑɹt/','noun',["There is a debate as to whether graffiti is art or vandalism.","She''s mastered the art of programming.","He''s at university to study art."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reward','n.报答；报酬v.报答','/ɹəˈwɔːd/','/ɹiˈwɔɹd/','noun',["For catching the thief, you''ll get a nice reward.","The rewards for bringing in badly wanted criminals are printed on ''dead or alive'' posters","Is this the reward I get for telling the truth: to be put in jail?"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('simplicity','n.简单，简易；朴素','/sɪmˈplɪsɪti/','/sɪmˈplɪsɪti/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('interview','n.接见；会见；面谈','/ˈɪntəvjuː/','/ˈɪntɚvjuː/','noun',["The reporter gave the witness an interview.","It was a dreadful interview; I have no hope of getting the job.","He interviewed the witness."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('buy','v.买，购买','/baɪ/','/baɪ/','noun',["At only $30, the second-hand kitchen table was a great buy.","I''m going to buy my father something nice for his birthday.","I''ve bought material comfort by foregoing my dreams."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('opposite','adj.对面的n.对立物','/ˈɒpəsɪt/','/ˈɑp(ə)sɪt/','noun',["\"Up\" is the opposite of \"down\".","She saw him walking on the opposite side of the road.","They were moving in opposite directions."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('girl','n.女孩子，姑娘；女儿','/ɡɵːl/','/ɡɝl/','noun',["Your girl turned up on our doorstep.","Don''t be such a girl!"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chess','n.棋；国际象棋','/t͡ʃɛs/','/t͡ʃɛs/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('quote','v.引用，引证；报价','/kwəʊt/','/kwəʊt/','noun',["After going over the hefty quotes, the board decided it was cheaper to have the project executed by its own staff.","The writer quoted the president.","The writer quoted the president''s speech."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('exhibit','v.陈列，展览；显示','/ɛɡ-/','/ɛɡ-/','noun',["The museum''s new exhibit is drawing quite a crowd.","Exhibit A is this photograph of the corpse.","He wanted to exhibit his baseball cards."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('resistant','adj.抵抗的；反抗的','','','noun',["The infection is resistant to antibiotics."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('kite','n.风筝','','','',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stroke','n.中风；打，击；鸣声','/stɹəʊk/','/stɹoʊk/','noun',["She gave the cat a stroke.","a stroke on the chin","the stroke of a bird''s wing in flying, or of an oar in rowing"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('move','v.移动；感动n.动','/muːv/','/muːv/','noun',["A slight move of the tiller, and the boat will go off course.","He made another move towards becoming a naturalized citizen.","She always gets spontaneous applause for that one move."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('beneficial','adj.有利的，有益的','/ˌbɛnəˈfɪʃəl/','/ˌbɛnəˈfɪʃəl/','noun',["Recycling and reusing garbage can be beneficial to the environment."]);
