INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prepare','v.准备，预备','/pɹɪˈpɛə/','/pɹəˈpɛəɹ/','noun',["We prepared the spacecraft for takeoff.","We prepared a fish for dinner.","We prepared for a bumpy ride."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('millimetre','n.毫米','','','noun',[]);
