INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('interfere','v.干涉，干预；妨碍','/ˌɪntəˈfɪə/','/ˌɪntɚˈfɪɹ/','verb',["I always try not to interfere with other people’s personal affairs.","Correlated waves interfere to produce interesting patterns, while uncorrelated waves overlap without interfering.","The investigation found the boys had been interfered with."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('glue','n.胶，胶水v.胶合','/ɡluː/','/ɡluː/','noun',["I need to glue the chair-leg back into place.","His eyes were glued to the screen."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('imaginary','adj.想象中的，假想的','/ɪˈmædʒɪn(ə)ɹi/','/ɪˈmædʒɪˌnɛɹi/','noun',["Santa Claus is imaginary."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('contemporary','adj.当代的；同时代的','/kənˈtɛm.p(ə).ɹi/','/kənˈtɛm.pəˌɹɛɹ.i/','noun',["Cervantes was a contemporary of Shakespeare."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('at','prep.在…里；在…时','','','verb',["Cars 2 is the most influential film of all time. Don''t @ me.","Caesar was at Rome;  at the corner of Fourth Street and Vine;  at Jim’s house","at six o’clock;  at closing time;  at night."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crow','n.鸦，乌鸦v.啼','/kɹəʊ/','/kɹoʊ/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('depend','v.依靠，依赖；相信','/dɪˈpɛnd/','/dɪˈpɛnd/','verb',["We would like to go skiing, but it depends on the amount of snow.","we depend on the mailman to come at the usual time.","a cause depending in court"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('item','n.一项，一件，一条','[ˈaɪ̯ɾm̩]','[ˈaɪ̯ɾm̩]','noun',["Tweezers are great for manipulating small items.","In response to the first item, we deny all wrongdoing.","The exam has 100 items, each of which includes a correct response and three distractors."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('entire','adj.全部的，整个的','/ənˈtaɪə/','/ənˈtaɪɚ/','noun',["We had the entire building to ourselves for the evening."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('charge','v.索价；控告n.费用','/t͡ʃɑːd͡ʒ/','/t͡ʃɑɹd͡ʒ/','noun',["There will be a charge of five dollars.","Pickett did not die leading his famous charge.","That''s a slanderous charge of abuse of trust."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('behavior','n.行为，举止，态度','[bɪˈheɪvjə]','[bɪˈheɪvjə]','noun',["He was on his best behavior when her family visited."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('provided','conj.以…为条件','/pɹəˈvaɪdɪd/','','verb',["It is difficult to provide for my family working on minimum wage.","Provide against disaster.","I''ll lend you the money, provided that you pay it back by Monday."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thus','adv.如此，这样；因而','/ˈðʌs/','/ˈðʌs/','adverb',["If you throw the ball thus, as I’m showing you, you’ll have better luck hitting the target.","I have all the tools I need; thus, I will be able to fix the car without having to call a mechanic."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('agreement','n.协定，协议；同意','/əˈɡɹiːmənt/','/əˈɡɹiːmənt/','noun',["to enter an agreement;  the UK and US negotiators nearing agreement;  he nodded his agreement.","The results of my experiment are in agreement with those of Michelson and with the law of General Relativity."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('device','n.器械，装置','/dəˈvaɪs/','/dəˈvaɪs/','noun',["There are a number of household devices in a kitchen such as a dishwasher, a garbage disposal, or an electric can opener."]);
