INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('commit','vt.犯，干；使承诺；把…托付给；调拨…供使用，拨出','/kəˈmɪt/','/kəˈmɪt/','noun',["Tony should be committed to a nuthouse!","to commit a series of heinous crimes","to commit oneself to a certain action"]);
