INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('patch','n.补丁；斑，与周围不同的部分；一小块地vt.补，修补','/pætʃ/','/pætʃ/','noun',["His sleeves had patches on the elbows where different fabric had been sewn on to replace material that had worn away.","I can''t afford to replace the roof, which is what it really needs. I''ll have the roofer apply a patch.","\"This patch should hold until you reach the city,\" the mechanic said as he patted the car''s hood."]);
