INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('breakdown','n.垮，衰竭；损坏，故障；倒塌','/ˈbɹeɪkdaʊn/','/ˈbɹeɪkdaʊn/','noun',["We saw a breakdown by the side of the road.","After so much stress, he suffered a breakdown and simply gave up.","Looking at the breakdown of the budget, I see a few items we could cut."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('paste','n.糊，糨糊vt.粘，贴','/peɪst/','/peɪst/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('overtake','vt.追上，超过；突然降临于，意外地碰上','/ˈəʊvə(ɹ).teɪk/','/oʊvɚˈteɪk/','verb',["The car was so slow we were overtaken by a bus.","Our plans were overtaken by events."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('jeans','n.工装裤，牛仔裤','/d͡ʒiːnz/','/d͡ʒiːnz/','noun',["She wore a tattered jean jacket.","Traditionally most jeans are dyed dark blue."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('overnight','adv.整夜，通宵；一夜间，突然adj.一整夜的；一夜间的，突然的','','','noun',["Have you looked at the overnights yet?","We can overnight you the documents for signature.","The overnight ferry docked at 10AM."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('behave','v.表现，举止；运转，作出反应','/bəˈheɪv/','/bəˈheɪv/','verb',["You need to behave yourself, young lady.","He behaves like a child whenever she''s around.","His mother threatened to spank him if he didn''t behave."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stretch','v.伸展，延续；伸长，拉长；倾注全力；紧张n.一段时间，一段路程，连绵的一片；伸展，延伸','/stɹɛtʃ/','/stɹɛtʃ/','noun',["I was right in the middle of a stretch when the phone rang.","That rubber band has quite a bit of stretch.","It''s a bit of a stretch to call Boris Karloff a comedian."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('undo','vt.解开，打开；取消，撤销','/ʌnˈduː/','/ʌnˈduː/','noun',["How many undos does this program support?","Fortunately, we can undo most of the damage to the system by the war.","Could you undo my buckle for me?"]);
