INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('identify','vi.一致vt.认出，鉴定；把…等同于','/aɪˈdɛn.tɪ.faɪ/','/aɪˈdɛn.tɪ.faɪ/','verb',["The Associated Press will not identify the suspect of the crime because he is a juvenile."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('embrace','n.拥抱，怀抱vt.拥抱；包括；包围','/ɛmˈbɹeɪs/','/əm-/','noun',["I wholeheartedly embrace the new legislation.","Natural philosophy embraces many sciences."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nitrogen','n.氮','/ˈnaɪ.tɹə.dʒən/','/ˈnaɪ.tɹə.dʒən/','noun',["The two nitrogens are located next to one another on the ring."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pour','v.灌，倒；倾泻','/pɔː/','/pɔɹ/','noun',["The bartender''s inexpert pour left me with a pint of beer that was half foam.","pour water from a jug","the rain poured down."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('label','n.标签；标记，符号vt.贴标签于；把…称为','/ˈleɪbəl/','/ˈleɪbəl/','noun',["Although the label priced this poster at three pounds, I got it for two.","Ever since he started going to the rock club, he''s been given the label \"waster\".","The label signed the band after hearing a demo tape."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('improvement','n.改进，改善；改进处','/ɪmˈpɹuːvmənt/','/ɪmˈpɹuːvmənt/','noun',["the new edition is an improvement on the old."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('slippery','adj.滑的；狡猾的','/ˈslɪpəɹi/','/ˈslɪpəɹi/','adjective',["Oily substances render things slippery.","a slippery person"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scissors','n.剪刀','/ˈsɪzəz/','/ˈsɪzɚz/','noun',["The erroneous testimony was scissored from the record.","The runner scissored over the hurdles.","Scissors are used to cut the flowers."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('significance','n.意义，含义；重要性，重大','/sɪɡˈnɪfɪkəns/','/sɪɡˈnɪfɪkəns/','noun',["As a juror your opinion is of great significance for the outcome of the trial.","the significance of a gesture"]);
