INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('career','n.生涯，职业，经历','/kəˈɹɪə/','/kəˈɹɪɹ/','noun',["Washington''s career as a soldier","The car careered down the road, missed the curve, and went through a hedge."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('occupation','n.占领，占据；职业；从事的活动，消遣','/ɒkjəˈpeɪʃən/','/ɑkjəˈpeɪʃən/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tendency','n.趋向，趋势，倾向','/ˈtɛndənsi/','/ˈtɛndənsi/','noun',["Denim has a tendency to fade."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('release','vt.释放，排放；解除，解脱；放开，松开；发布；发行','/ɹɪˈliːs/','/ɹɪˈliːs/','noun',["The video store advertised that it had all the latest releases.","They marked the occasion with a release of butterflies.","He released his grasp on the lever."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('charter','adj.包租的，租用的n.宪章，共同纲领；特许状，许可证；包租vt.包，租','/ˈt͡ʃɑːtə/','/ˈt͡ʃɑːtə/','noun',["2005 November 30, Stephen Foley \"The market where ''caveat emptor'' has become a charter for fraud\" The Independent, London"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('slim','adj.苗条的；薄的；少的v.减轻体重，变苗条','/slɪm/','/slɪm/','noun',["I only smoke slims.","I''m afraid your chances are quite slim.","A slimly-shod lad;"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('arithmetic','n.算术，四则运算','','','noun',["arithmetic geometry","arithmetic progression"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rib','n.肋骨','/ɹɪb/','/ɹɪb/','noun',["He always gets ribbed for his outrageous shirts."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('faulty','adj.有错误的，有缺点的','/ˈfɔːlti/','/ˈfɔːlti/','adjective',["I don''t think you can infer that from the premise. It''s a faulty argument."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('liberate','vt.解放，释放','/ˈlɪbəɹeɪt/','/ˈlɪbəɹeɪt/','verb',["We didn''t need IDs. We just liberated these beers from the back of the shop."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rid','vt.使摆脱，解除…的负担，从…中清除','/ˈɹɪd/','/ˈɹɪd/','verb',["We''re trying to rid the world of poverty.","I’m glad to be rid of that stupid nickname."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('variation','n.变化，变动；变异；变奏','/ˌvɛəɹɪˈeɪʃn̩/','/ˌvæɹiˈeɪʃn̩/','noun',["All of his soups are variations on a single recipe."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('moral','adj.道德的，有道德的n.品行；道德规范；寓意','/ˈmɒɹəl/','/ˈmɑɹəl/','noun',["a candidate with strong morals","moral judgments;  a moral poem","a moral obligation"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('defect','v.变节，叛变n.缺点，缺陷，欠缺','','','noun',["a defect in the ear or eye; a defect in timber or iron; a defect of memory or judgment"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reinforce','vt.增强，加强，增援','/ˌɹiːɪnˈfɔː(ɹ)s/','/ˌɹiːɪnˈfɔː(ɹ)s/','verb',["He reinforced the handle with a metal rod and a bit of tape.","The right homework will reinforce and complement the lesson!","Advertising for fast food can reinforce unhealthy dietary tendencies."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('explode','vi.爆炸；激增；发怒vt.使爆炸','/ɪkˈspləʊd/','/ɪkˈsploʊd/','verb',["The assassin exploded the car by means of a car bomb.","They sought to explode the myth.","Explode the assembly drawing so that all the fasteners are visible."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('casual','adj.偶然的；非正式的；临时的，不定期的；漠不关心的，冷淡的','/ˈkɛʒɘl/','/ˈkɛʒɘl/','noun',["The devs dumbed the game down so the casuals could enjoy it.","They only had casual meetings.","The purchase of donuts was just a casual expense."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('decline','v.下降，减少；衰退，衰落；谢绝，拒绝n.下降，减少；衰退','/dɪˈklaɪn/','/dɪˈklaɪn/','noun',["The dollar has declined rapidly since 2001.","My health declined in winter.","a line that declines from straightness"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('property','n.财产，所有物；房产；物业；性质，性能','/ˈpɹɒp.ət.i/','/ˈpɹɑp.ɚt.i/','noun',["Important types of property include real property (land), personal property (other physical possessions), and intellectual property (rights over artistic creations, inventions, etc.).","There is a large house on the property.","He works in property as a housing consultant."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('succeeding','adj.以后的，随后的','/səkˈsiːdɪŋ/','/səkˈsiːdɪŋ/','verb',["Autumn succeeds summer.","The persecution of any righteous practice has never succeeded in the face of history; in fact, it can expedite the collapse of the persecutory regime.","So, if the issue of the elder son succeed before the younger, I am king."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('brave','adj.勇敢的；华丽的','/bɹeɪv/','/bɹeɪv/','noun',["After braving tricks on the high-dive, he braved a jump off the first diving platform."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('similar','adj.相似的，类似的','/ˈsɪmələ/','/ˈsɪməlɚ/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('viewpoint','n.观点，看法，见解','/ˈvjuː.pɔɪnt/','/ˈvjuː.pɔɪnt/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('anyhow','adv.无论如何，不管怎么说；随随便便地，杂乱无章地','/ˈæn.i.haʊ/','/ˈæn.i.haʊ/','adverb',["Anyhow, he is dead now."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('specify','vt.指定；详细说明','/ˈspɛsɪfaɪ/','/ˈspɛsɪfaɪ/','verb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('whistle','v.吹口哨，鸣笛声；呼啸而过n.口哨；呼啸而过','/wɪsl̩/','/wɪsl̩/','noun',["the whistle of the wind in the trees","Never whistle at a funeral.","The stream train whistled as it passed by."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('handle','n.柄，把手vt.拿，触；操作，处理','/ˈhæn.dl/','/ˈhæn.dl/','noun',["The daily handle of a Las Vegas casino is typically millions of dollars.","The successful businessman was knighted and acquired a handle to his name.","This article describes how to find the module name from the window handle."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('forth','adv.向前；向外，往外','/fɔːθ/','/fɔɹθ/','adverb',["The plants in spring put forth leaves."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tough','adj.困难的，难对付的；坚强的，能吃苦耐劳的；健壮的；坚硬的，严格的；老的，硬的；粗暴的，充满暴力的','/tʌf/','/tʌf/','noun',["They were doing fine until they encountered a bunch of toughs from the opposition.","The tent, made of tough canvas, held up to many abuses.","To soften a tough cut of meat, the recipe suggested simmering it for hours."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crossing','n.人行横道，交叉口；横渡','/ˈkɹɑsɪŋ/','/ˈkɹɔsɪŋ/','verb',["They managed to cross a sheep with a goat."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('script','n.剧本，广播稿；书写用的字母；笔迹，手迹','/skɹɪpt/','/skɹɪpt/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('submerge','v.淹没，潜入水中','/sʌbˈmɜːdʒ/','/sʌbˈmɜːdʒ/','verb',["The submarine submerged in the water.","In films many people are murdered by being submerged in swimming pools.","Because of the death of his father, he is submerged in sorrow."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('system','n.系统；制度，体制；方法，做法；身体','/ˈsɪstəm/','/ˈsɪstəm/','noun',["There are eight planets in the solar system.","Followers should have a system to follow that works in their interests, not against them."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('compose','vt.组成，构成；创作，为…谱曲；使平静，使镇静','/kəmˈpəʊz/','/kəmˈpoʊz/','verb',["The editor composed a historical journal from many individual letters.","A church is composed of its members.","It''s difficult to compose without absolute silence."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spot','n.点，斑点；地点，处所；少量vt.认出，发现；玷污','/spɒt/','/spɑt/','noun',["The leopard is noted for the spots of color in its fur.","I have tried everything, and I can’t get this spot out.","I think she''s got chicken pox; she''s covered in spots."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('roller','n.滚筒，滚轴','/ˈɹəʊlə/','/ˈɹəʊlə/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('partial','adj.部分的；不公平的；偏爱的，偏袒的','/ˈpɑːʃəl/','/ˈpɑːʃəl/','noun',["So far, I have only pieced together a partial account of the incident.","It''s easy to prove partial correctness, but it''s not obvious that it is also totally correct.","The referee is blatantly partial!"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('aid','n.帮助；救护；助手；辅助手段','/eɪd/','','noun',["He came to my aid when I was foundering.","Slimming aids include dietary supplements and appetite suppressants.","The incompetent general''s brilliant aid often made priceless suggestions."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tone','n.腔调，语气；音调；风格，气度；色调，明暗','/təʊn/','/toʊn/','noun',["Her rousing speech gave an upbeat tone to the rest of the evening.","Children often read with a tone.","This picture has tone."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('confident','adj.确信的，肯定的；自信的','/ˈkɒn.fɪ.dənt/','/ˈkɑn.fɪ.dənt/','noun',["I''m pretty confident that she''s not lying, she''s acting normally."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('retain','vt.保留，保持','/ɹɪˈteɪn/','/ɹɪˈteɪn/','verb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('swell','vi.膨胀，隆起；增长，增强，增多，扩大n.波浪起伏；鼓起，隆起；增强','/swɛl/','/swɛl/','verb',["Rains and dissolving snow swell the rivers in spring.","The organ music swelled.","to be swelled with pride or haughtiness"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('skilled','adj.有技能的；熟练的；需要技能的','/skɪld/','/skɪld/','adjective',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('local','adj.地方性的；本地的；局部的；狭隘的','/ˈləʊkl̩/','/ˈloʊkl̩/','noun',["It''s easy to tell the locals from the tourists.","I''m in the TWU, too. Local 6.","The expresses skipped my station, so I had to take a local."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('remind','vt.提醒，使想起','/ɹəˈmaɪnd/','/ɹəˈmaɪnd/','verb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crude','adj.简陋的，天然的；粗鲁的，粗俗的','/kɹʉd/','/kɹuːd/','noun',["crude oil","a crude shelter","a crude truth"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('manufacturer','n.制造商；制造厂','/ˌmænjuˈfæktʃɚ(ɹ)ɚ/','/ˌmænjuˈfæktʃɚ(ɹ)ɚ/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crew','n.全体船员；一队工作人员','','','verb',["He’s been crowing all day about winning the game of cards."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('valid','adj.有效的；正当的；有根据的，有理的','/ˈvælɪd/','/ˈvælɪd/','adjective',["I will believe him as soon as he offers a valid answer.","A valid format for the date is MM/DD/YY.","An argument is valid if and only if the set consisting of both (1) all of its premises and (2) the contradictory of its conclusion is inconsistent."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('withstand','vt.抵挡，反抗','/wɪðˈstænd/','/wɪðˈstænd/','verb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('defeat','n&vt.战胜，挫败','/dɪˈfiːt/','/dɪˈfiːt/','verb',["Wellington defeated Napoleon at Waterloo."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vacuum','v.用吸尘器清扫n.真空；真空吸尘器','/ˈvæ.kjuː.əm/','/ˈvæ.kjuː.əm/','noun',["a vacuum of 26 inches of mercury, or 13 pounds per square inch"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('encourage','vt.鼓励，怂恿；促进，助长，激发','/ɪnˈkʌɹɪdʒ/','/ɪnˈkɝɹɪdʒ/','verb',["I encouraged him during his race.","We encourage the use of bicycles in the town centre.","The royal family has always encouraged the arts in word and deed"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bubble','vi.冒泡；沸腾n.泡','/ˈbʌb.əl/','/ˈbʌb.əl/','noun',["bubbles in window glass, or in a lens","dot-com bubble","Are you having a bubble?!"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('era','n.时代，年代，纪元','/ˈɪə̯ɹ.ə/','/ˈɛɹ.ə/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('yield','v.出产；让出，放弃；屈服，顺从；倒塌，垮掉n.产量','/jiːld/','/jiːld/','verb',["Yield the right of way to pedestrians.","They refuse to yield to the enemy.","Historically, that security yields a high return."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('electronic','adj.电子的n.电子学；电子设备','/ɪˌlɛkˈtɹɒn.ɪk/','/ɪˌlɛkˈtɹɑn.ɪk/','adjective',["electronic music"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vacation','n.假期，休假','/veɪˈkeɪʃ(ə)n/','/veɪˈkeɪʃən/','noun',["The Conservative Party’s vacation of the centre ground gave an opportunity to its opponents.","This year, we’re vacationing in Mexico."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('outcome','n.结果','/ˈaʊtkʌm/','/ˈaʊtkʌm/','noun',["A quality automobile is the outcome of the work of skilled engineers and thousands of workers.","Three is a possible outcome of tossing a six-sided die.","The outcomes of this course are outlined in your syllabus."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('elegant','adj.优美的，文雅的，讲究的；简练的，简洁的','/ˈɛl.ə.ɡənt/','/ˈɛl.ə.ɡənt/','adjective',["an elegant solution"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tender','adj.嫩的；脆弱的；疼痛的，一触即痛的；温柔的vt.提出n.投标','/ˈtɛn.də(ɹ)/','/ˈtɛn.də/','noun',["tender plants; tender flesh; tender fruit","Suzanne was such a tender mother to her children.","tender expressions; tender expostulations; a tender strain"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('curriculum','n.课程，全部课程','/kəˈɹɪk.jə.ləm/','/kəˈɹɪkjələm/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('meantime','n.其间，同时','/ˈmiːntaɪm/','/ˈmiːntaɪm/','noun',["I''ll get started tomorrow but, in the meantime, let''s see if we can get a few more opinions."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('powerful','adj.强大的，有力的，有权的；强壮的，强健的','/ˈpaʊəfl/','/ˈpaʊɚfəl/','adjective',["Not very many (of them) had been damaged.","He was the very best runner there."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('slip','v.滑跤，滑落，溜；下降，跌落；悄悄放进n.疏漏，差错','/slɪp/','/slɪp/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('species','n.种，类','/ˈspiːsiːz/','/ˈspiːsiːz/','noun',["the male species"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('anchor','v.抛锚，停泊；把…系住，使固定；担任主持人；固定，扎根n.锚；给人安全感的物','/ˈæŋ.kə/','/ˈæŋ.kɚ/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('preceding','adj.在前的，在先的，前面的','/pɹiːˈsiːdɪŋ/','/pɹiːˈsiːdɪŋ/','verb',["Cultural genocide precedes physical genocide.","On the preceding Monday Shobana had gone on vacation."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cite','vt.引用，引证；传唤，传讯；表彰，嘉奖','/saɪt/','/saɪt/','verb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('logic','n.逻辑，推理，逻辑学','/ˈlɒdʒɪk/','/ˈlɑdʒɪk/','noun',["It''s hard to work out his system of logic.","Fred is designing the logic for the new controller."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('acquaintance','n.认识，了解；熟人','/əˈkweɪntəns/','/ʌˈkweɪn.təns/','noun',["I know of the man; but have no acquaintance with him."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('royal','adj.王室的，皇家的','/ˈɹɔɪəl/','/ˈɹɔɪəl/','noun',["royal mast;  royal sail","a royal pain in the neck"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('internship','n.实习生身份；实习医师期','/ˈɪntɝnʃɪp/','/ˈɪntɝnʃɪp/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shed','vt.脱落，脱去；流出，流下；发出，散发n.棚，小屋，货棚','/ʃɛd/','/ʃɛd/','verb',["A metal comb shed her golden hair.","When we found the snake, it was in the process of shedding its skin.","A tarpaulin sheds water."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('eyesight','n.视力，目力','/ˈaɪˌsaɪt/','/ˈaɪˌsaɪt/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('precision','n.精确，精密','/pɹɪˈsɪ.ʒ(ə)n/','/pɹɪˈsɪ.ʒ(ə)n/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('glove','n.手套','/ɡlʌv/','/ɡlʌv/','noun',["I wore gloves to keep my hands warm.","Frederico had a great glove, but he couldn''t hit a curveball, so he never broke into the pros.","to throw down the glove, i.e. to offer a challenge; to take up the glove, to accept it"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('screen','n.屏幕，银幕；屏风；帘，纱窗vt.掩蔽，遮蔽；放映，播放；审查，甄别','/skɹiːn/','/skɹiːn/','noun',["a fire screen","a drug screen, a genetic screen","Mary screened the beans to remove the clumps of gravel."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('naked','adj.裸体的；无遮蔽的','/ˈnɛkɪd/','/ˈnɛkɪd/','adjective',["She was as naked as the day she was born.","The naked facts lay there on the table, enclosed within the files.","I entered her naked and came in her too."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trial','n.试，试验；审判；讨厌的人','/ˈtɹaɪəl/','/ˈtɹaɪəl/','noun',["They will perform the trials for the new equipment next week.","That boy was a trial to his parents.","soccer trials"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('correspond','vi.相符合，相当；通信','/ˌkɒɹəˈspɒnd/','/ˌkɑɹəˈspɑnd/','verb',["I''ve been corresponding with my German pen pal for three years."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spur','n.刺激物vt.刺激，鞭策，激励','/spɜː/','/spɝ/','noun',["to spur boots"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('perception','n.感知，觉察；认识，观念，看法','/pəˈsɛpʃ(ə)n/','/pɚˈsɛpʃ(ə)n/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rear','adj.后部的，背后的n.后部，背面；后方vt.抚养，饲养；种植','/ɹɪə/','/ɹiɹ/','verb',["The family has been rearing cattle for 200 years.","The horse was shocked, and thus reared.","The monster slowly reared its head."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('amongst','prep.在…之中','/əˈmʌŋst/','/əˈmʌŋst/','preposition',["Janek feels very at ease amongst his friends, but gets incredibly nervous when meeting new people."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('undertake','vt.从事；承担；同意；保证','/ʌndəˈteɪk/','','verb',["He undertook to exercise more in future.","I hate people who try and undertake on the motorway."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('insect','n.昆虫，虫','/ˈɪnsɛkt/','/ˈɪnsɛkt/','noun',["Our shed has several insect infestions, including ants, yellowjackets, and wasps.","The swamp is swarming with every sort of insect.","The manager’s assistant was the worst sort of insect."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bureau','n.局，司，处，社，所','/ˈbjʊɹ.oʊ/','/ˈbjʊɹ.oʊ/','noun',["a news bureau; a travel bureau; a service bureau; an employment bureau; the Citizens Advice Bureau"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('moist','adj.湿润的，潮湿的','/mɔɪst/','/mɔɪst/','verb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cable','n.缆，索，电缆；电报','/keɪ.bl/','/keɪ.bl/','noun',["I tried to watch the movie last night but my cable was out."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('qualify','v.胜任，具有资格，合格；限定','/ˈkwɒl.ɪ.faɪ/','/ˈkwɑl.ɪ.faɪ/','noun',["to qualify seven balls you need at least fourteen catches"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('intense','adj.强烈的；紧张的；认真的；热情的','/ɪnˈtɛns/','/ɪnˈtɛns/','adjective',["intense study;  intense thought","The artist was a small, intense man with piercing blue eyes."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pregnant','adj.怀孕的，妊娠的','/ˈpɹɛɡnənt/','/ˈpɹɛɡnənt/','noun',["I went to the doctor and, guess what, I''m pregnant!","a pregnant pause"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('border','n.边，边缘，边界vt.给…加上边，围；邻接；与…接壤','/ˈbɔːdə/','/ˈbɔɹdɚ/','noun',["the borders of the garden","There''s a nice frilly border around the picture frame.","The border between Canada and USA is the longest in the world."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('estate','n.土地，住宅区，地产；财产，遗产；庄园，种植园','/ɪsˈteɪt/','/ɪsˈteɪt/','noun',["an estate diamond; estate jewelry"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('applicable','adj.能应用的；合适的，适当的','/əˈplɪkəbəl/','/əˈplɪkəbəl/','adjective',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('admission','n.允许进入；承认；入场费，入场券','/ædˈmɪʃ.ən/','/ædˈmɪʃ.ən/','noun',["I request admission for two adults","There is no way he has seen that show, the admission is more than he makes in a week."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('brass','n.黄铜，黄铜器，铜管乐器','/bɹɑːs/','/bɹæs/','noun',["The brass are not going to like this.","You''ve got a lot of brass telling me to do that!"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('expense','n.花费，消费；费用，开支；业务费用','/ɪkˈspɛns/','/ɪkˈspɛns/','noun',["Buying the car was a big expense, but will be worth it in the long run.","Jones reached the final at the expense of Smith, who couldn''t beat him.","It should be acceptable to expense a business lunch with a client."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rumour','n.谣传，谣言','/ˈɹuːmə(ɹ)/','/ˈɹuːmə(ɹ)/','noun',["There''s a rumor going round that he''s going to get married.","They say he used to be a thief, but that''s just rumor.","John is rumored to be next in line for a promotion."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('contemporary','adj.当代的；同时代的n.同代人，当代人','/kənˈtɛm.p(ə).ɹi/','/kənˈtɛm.pəˌɹɛɹ.i/','noun',["Cervantes was a contemporary of Shakespeare."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gear','n.齿轮，传动装置，排挡；用具，设备；衣服vt.使适应，使适合','/ɡɪə(ɹ)/','/ɡɪə(ɹ)/','noun',["They have geared the hotel mainly at tourists."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('boundary','n.分界线，边界','/ˈbaʊndɹi/','/ˈbaʊndəɹi/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rob','vt.抢劫，盗窃','/ɹɒb/','/ɹɑb/','verb',["He robbed three banks before he was caught.","The best way to rob a bank is to own one.","Working all day robs me of any energy to go out in the evening."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('elderly','adj.较老的，年长的n.到了晚年的人，老年人','/ˈɛldəli/','/ˈɛldɚli/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('financial','adj.财政的，金融的','/faɪˈnænʃəl/','/faɪˈnænʃəl/','adjective',["For financial reasons, we''re not going to be able to continue to fund this program.","Jerry is a financial member of the club."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rod','n.杆，棒','/ɹɒd/','/ɹɑd/','noun',["When I hooked a snake and not a fish, I got so scared I dropped my rod in the water.","The judge imposed on the thief a sentence of fifteen strokes with the rod.","I notched a rod and used it to measure the length of rope to cut."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dumb','adj.哑的；无言的；说不出话的','/dʌm/','/dʌm/','adjective',["His younger brother was born dumb, and communicated with sign language.","dumb show","You are so dumb! You don''t even know how to make toast!"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('respective','adj.各自的，各个的，分别的','/ɹɪˈspɛktɪv/','/ɹɪˈspɛktɪv/','adjective',["They returned to their respective places of abode.","the respective connections of society"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('media','n.新闻媒介，传播媒介','/ˈmiːdɪə/','/ˈmiːdɪə/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('favour','n.好感；赞同；恩惠vt.赞同；喜爱，偏爱；有利于','/ˈfeɪ.və/','/ˈfeɪ.vɚ/','noun',["He did me a favor when he took the time to drive me home.","She enjoyed the queen''s favor.","A marriage favour is a bunch or knot of white ribbons or white flowers worn at a wedding."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pollute','vt.弄脏，污染；腐蚀','/pəˈljuːt/','/pəˈljuːt/','verb',["The factory polluted the river when it cleaned its tanks.","The lights from the stadium polluted the night sky, and we couldn''t see the stars."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('harden','v.变硬；变得坚强','/ˈhɑːdn̩/','/ˈhɑːdn̩/','verb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('eve','n.前夜，前夕，前一刻','/iːv/','/iːv/','noun',["the eve of a scientific discovery"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pronoun','n.代词','/ˈpɹəʊnaʊn/','/ˈpɹoʊ.naʊn/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('define','vt.给…下定义，限定','/dɪˈfaɪn/','/dɪˈfaɪn/','noun',["the defining power of an optical instrument","I define myself as a techno-anarchist.","The textbook defined speed as velocity divided by time."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dictate','v.口授；命令，规定，要求n.命令，指挥','/ˈdɪkˌteɪt/','/ˈdɪkˌteɪt/','noun',["I must obey the dictates of my conscience.","She is dictating a letter to a stenographer."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('construction','n.建造；建筑物；结构','/kənˈstɹʌkʃən/','/kənˈstɹʌkʃən/','noun',["Construction is underway on the new bridge.","The engineer marvelled at his construction.","He had worked in construction all his life."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('predict','vt.预言，预告，预测','/pɹɪˈdɪkt/','/pɹɪˈdɪkt/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dump','vt.倾卸，倾倒；倾销n.垃圾场','/dʌmp/','/dʌmp/','noun',["A toxic waste dump.","The new XML dump is coming soon.","Don''t feel bad about moving away from this dump."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('render','vt.使得，致使；给予，提供；翻译','/ˈɹɛn.də/','/ˈɹɛn.dɚ/','noun',["A low-resolution render might look blocky.","The shot rendered her immobile.","The pianist rendered the Beethoven sonata beautifully."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('universal','adj.普遍的；通用的；全世界的','/ˌjuːnɪˈvɜːsl̩/','/ˌjunɪˈvɝsl̩/','noun',["She achieved universal fame.","universal wrench"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chemist','n.化学家，药剂师','/ˈkɛmɪst/','/ˈkɛmɪst/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('frontier','n.边境，边疆；新领域','/fɹʌnˈtɪə/','/fɹʌnˈtɪɹ/','noun',["the frontier of civilization"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('abroad','adv.到国外；在传播，在流传','/əˈbɹɔːd/','/əˈbɹɔd/','noun',["A tree spreads its branches abroad."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('radical','adv.根本的，基本的；激进的，激进派的n.激进分子','/ˈɹædɪkəl/','/ˈɹædɪkəl/','noun',["His beliefs are radical.","The spread of the cancer required radical surgery, and the entire organ was removed.","a radical quantity; a radical sign"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('relieve','vt.使轻松，使宽慰，缓解；使得到调剂；接替','/ɹɪˈliːv/','/ɹɪˈliːv/','verb',["I was greatly relieved by the jury''s verdict.","This shall not relieve either Party of any obligations."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('drawer','n.抽屉','/dɹɔː(ɹ)/','/dɹɔɹ/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('requirement','n.要求；必要条件；需要，需要的东西','/ɹɪˈkwʌɪəm(ə)nt/','/ɹɪˈkwʌɪəm(ə)nt/','noun',["There was a requirement of the government on citizens for paying taxes."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('transport','vt.运输n.运输，运输工具','','','noun',["The transport of goods is not included in the price given on the website.","The local transport received a big boost as part of the mayor''s infrastructural plans.","to transport goods; to transport troops"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('employment','n.工作；雇用；使用','/ɛmˈplɔɪmənt/','/ɛmˈplɔɪmənt/','noun',["The personnel director handled the whole employment procedure"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('specific','adj.特有的；具体的，明确的n.详情，细节','/spəˈsɪf.ɪk/','/spəˈsɪf.ɪk/','noun',["a highly specific test, specific and nonspecific symptoms","Quinine is a specific medicine in cases of malaria."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('application','n.申请，申请书；施用，涂抹；应用，实施；实用性','/aplɪˈkeɪʃ(ə)n/','/ˌæpləˈkeɪʃən/','noun',["The application of this cream should reduce the swelling.","I make the remark, and leave you to make the application.","This iPhone application can connect to most social networks."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('engage','vt.使从事；聘用；吸引；占用；使订婚','/ɛnˈɡeɪdʒ/','/ɛnˈɡeɪdʒ/','verb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('acre','n.英亩','/ˈeɪ.kə/','/ˈeɪ.kɚ/','noun',["I like my new house - there’s acres of space!"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('whisper','v.低声地讲n.低语，耳语','/ˈ(h)wɪspə/','/ˈ(h)wɪspɚ/','noun',["There are whispers of rebellion all around.","The soup had just a whisper of basil."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('appetite','n.食欲，胃口；欲望','/ˈæp.ə.taɪt/','/ˈæp.ə.taɪt/','noun',["appetite for reading"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('semester','n.学期','/sɪˈmɛstə/','/sɪˈmɛstə/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('strategy','n.战略，策略','/ˈstɹætədʒi/','/ˈstɹætədʒi/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dull','adj.乏味的，单调的；晦暗的，阴沉的；低沉的；笨的；钝的','/dəl/','/dʌl/','verb',["Years of misuse have dulled the tools.","He drinks to dull the pain.","A razor will dull with use."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('collapse','v.倒坍；塌下n.突然失败；突然瓦解','/kəˈlæps/','/kəˈlæps/','noun',["She suffered a terrible collapse after slipping on the wet floor.","Pyramid schemes tend to generate profits for a while and then collapse.","Hurry up and collapse the tent so we can get moving."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clumsy','adj.笨拙的，愚笨的；粗陋的；不得体的','/ˈklʌmzi/','/ˈklʌmzi/','noun',["He''s very clumsy. I wouldn''t trust him with carrying the dishes.","It is a clumsy solution, but it might work for now."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('territory','n.领土，版图；领域','/ˈtɛɹɪt(ə)ɹi/','/ˈtɛɹɪt(ə)ɹi/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('concession','n.让步，妥协；特许，特许权；承认，认可','/kənˈsɛʃən/','/kənˈsɛʃən/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accurate','adj.准确的，正确无误的','/ˈæk.jə.ɹɪt/','/ˈæk.jə.ɹɪt/','adjective',["accurate knowledge","My horoscopes I read last week were surprisingly accurate."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('maintain','vt.维持；维修，保养；主张；赡养','/meɪnˈteɪn/','/meɪnˈteɪn/','verb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shift','v.移动，转移；改变，转变n.转换，转变；轮班','/ʃɪft/','/ʃɪft/','noun',["Just last week she bought a new shift at the market.","We''ll work three shifts a day till the job''s done.","There was a shift in the political atmosphere."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('echo','v.重复，模仿；发出回声n.回声；反响，共鸣','/ˈɛkəʊ/','/ˈɛkoʊ/','noun',["Sid echoed his father''s point of view."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('erect','adj.竖直的，垂直的vt.建造；使竖立','/ɪˈɹɛkt/','/ɪˈɹɛkt/','adjective',["The penis should be fully erect before commencing copulation.","OK, baby, I''m erect now. Let''s get it on!"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bargain','vi.讨价还价n.特价商品；协议，交易','/-ɡɪn/','/ˈbɑːɹɡən/','noun',["At that price, it''s not just a bargain, it''s a steal.","They had to bargain for a few minutes to get a decent price for the rug."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('professional','adj.职业的，专业的，专门的n.自由职业者，专业人员','/pɹəˈfɛʃənəl/','/pɹəˈfɛʃənəl/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('elective','adj.选举的，有选举权的；可任意选择的n.选修课程','/ɪˈlɛktɪv/','/ɪˈlɛktɪv/','noun',["My insurance wouldn''t pay for the operation because it was elective surgery."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accusation','n.谴责；【律】指控','/ˌæk.jə.ˈzeɪ.ʃən/','/ˌæk.jə.ˈzeɪ.ʃən/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('protein','n.蛋白质','/ˈpɹəʊti.ɪn/','/ˈpɹoʊtiːn/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('annual','adj.每年的，一年一次的n.年报，年鉴；一年生的植物','/ˈæn.ju.əl/','/ˈæn.ju.əl/','noun',["I read the magazine, but I usually don''t purchase the annuals.","I can''t wait to plant my annuals in the spring.","an annual general meeting;  an annual publication"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('exclusive','adj.奢华的，高级的；独有的，独享的；排斥的，排他的；不包括…的，不把…计算在内的n.独家新闻','/ɪkˈsklu.sɪv/','/ɪkˈsklu.sɪv/','noun',["The editor agreed to keep a lid on a potentially disastrous political scoop in exchange for an exclusive of a happier nature.","Exclusive clubs tend to serve exclusive brands of food and drinks, in the same exorbitant price range, such as the ''finest'' French châteaux.","The teacher''s pet commands the teacher''s exclusive attention."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('jar','v.感到不快；震动，摇动n.罐子，坛子，广口瓶','/dʒɐː/','/dʒɑɹ/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('poverty','n.贫穷，贫困','/ˈpɒvəti/','/ˈpɑːvɚti/','noun',["poverty of soil"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('resort','vi.求助，凭借，诉诸n.求助，凭借，诉诸；求助的对象，采用的手段；常去之地，胜地','/ɹɨˈzɔ(ɹ)t/','/ɹɨˈzɔ(ɹ)t/','noun',["to have resort to violence"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('goodness','int.天哪n.善良，美德，好意','/ˈɡʊdnəs/','/ˈɡʊdnəs/','noun',["Thank goodness that the war is over!"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lightning','n.闪电，电光','/ˈlaɪt.nɪŋ/','/ˈlaɪt.nɪŋ/','noun',["Although we did not see the lightning, we did hear the thunder.","That tree was hit by lightning."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('jaw','n.颌，颚','/d͡ʒɔː/','/d͡ʒɑ/','noun',["His jaw dropped in amazement.","the jaws of a pass; the jaws of darkness; the jaws of death.","the jaw of a railway-car pedestal."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('margin','n.页边空白；差数，差额；余地；边缘','/ˈmɑːdʒɪn/','/ˈmɑːɹdʒ(ə)n/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('remain','vi.剩下，余留；保持；仍然是n.残余；残骸；遗迹','/ɹɪˈmeɪn/','/ɹɪˈmeɪn/','noun',["There was no food in the house, so I had to remain hungry.","The light remained red for two full minutes."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('amaze','vt.使惊奇，使惊愕','/əˈmeɪz/','','noun',["He was amazed when he found that the girl was a robot."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('refine','vt.精炼，精制，提纯；使优美，使完善','/ɹɪˈfaɪn/','/ɹɪˈfaɪn/','verb',["to refine gold","a refined style","to refine someone''s language"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mount','v.登上；发起；安放；增加，加剧n.山，峰','/maʊnt/','/maʊnt/','noun',["the mount of Jupiter"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('demand','vt.要求，需要；查问','/dɪˈmɑːnd/','/dəˈmænd/','noun',["Prices usually go up when demand exceeds supply.","Modern society is responding to women''s demands for equality.","His job makes many demands on his time."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mystery','n.神秘；神秘的人','/ˈmɪstəɹi/','/ˈmɪstəɹi/','noun',["The truth behind the events remains a mystery.","That man is a mystery.","the Eleusinian mysteries"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('atomic','adj.原子的，原子能的，原子武器的','/əˈtɔm.ɪk/','/əˈtɑː.mɪk/','noun',["A stream of atomic hydrogen is emitted.","We built a small atomic bomb in the garage.","The hairs on a bedbug are almost atomic."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deposit','vt.使沉淀；存放，储蓄n.定金，押金；存款；矿藏','/dɪˈpɒzɪt/','/dɨˈpɑzɪt/','noun',["a deposit of seaweed on the shore","They put a deposit on the apartment.","A crocodile deposits her eggs in the sand."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('centimetre','n.公分，厘米','/ˈsɛn.tɪ.miː.tə/','/ˈsɛn.tɪ.miː.tə/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('telescope','n.望远镜','/ˈtɛlɪskəʊp/','/ˈtɛləˌskoʊp/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rotten','adj.腐烂的；令人不愉快的；糟糕的','/ˈɹɒtn̩/','/ˈɹɒtn̩/','adjective',["If you leave a bin unattended for a few weeks, the rubbish inside will turn rotten.","His mouth stank and his teeth were rotten.","That man is a rotten father."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('skillful','adj.灵巧的，娴熟的','/ˈskɪl.fəl/','/ˈskɪl.fəl/','adjective',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flash','vi.闪，闪烁；飞驰n.闪光；闪光灯','/flæʃ/','/flæʃ/','noun',["I just got my first commando flash.","He flashed the light at the water, trying to see what made the noise.","The light flashed on and off."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accuse','vt.指责，归咎于','/əˈkjuːz/','/əˈkjuz/','noun',["For the U.S. President to be impeached, he must be accused of a high crime or misdemeanor."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('housing','n.房屋，住宅；住房建筑，住房供给；外壳，外罩','/ˈhaʊzɪŋ/','/ˈhaʊzɪŋ/','verb',["The car is housed in the garage.","to house the upper spars"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('devil','n.魔鬼，恶魔；家伙，人','/ˈdɛvəl/','/ˈdɛvəl/','noun',["The devil in me wants to let him suffer.","Those two kids are devils in a toy store.","That math problem was a devil."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('guarantee','n.保证；保证书；担保物vt.保证，担保','/ˌɡæɹənˈtiː/','/ˌɡæɹənˈtiː/','noun',["Can you give me a guarantee that he will be fit for the match?","The cooker comes with a five-year guarantee.","The long sunny days guarantee a good crop."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('recommend','vt.推荐，举荐；劝告，建议；使成为可取；使受欢迎','/ɹɛkəˈmɛnd/','/ɹɛkəˈmɛnd/','verb',["The board recommends Philips, given his ample experience in similar positions.","A city that has much to recommend it.","The therapist recommends resting the mind and exercising the body."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('acquire','vt.取得，获得，学到','/əˈkwaɪə/','/əˈkwaɪəɹ/','verb',["He acquired a title."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fertile','adj.肥沃的；多产的；丰富的','/ˈfɝːtaɪl/','/ˈfɝːtaɪl/','adjective',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('automobile','n.汽车，机动车','/ˈɔː.tə.məˌbiːl/','/ˈɔ.tə.moʊˌbil/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('notion','n.概念，观念；意图，想法，念头','/ˈnəʊʃən/','/ˈnoʊʃən/','noun',["Yankee notions","I have a notion to do it."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('diversity','n.多样性；差异；不同点','/daɪˈvɜː(ɹ)sɪti/','/daɪˈvɜː(ɹ)sɪti/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('helicopter','n.直升机','/ˈheliˌkɔptə(ɹ)/','/ˈheliˌkɔptə(ɹ)/','noun',["We flew over the city in a helicopter.","helicoptering his jacket, helicoptering his arms"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tractor','n.拖拉机，牵引车','/ˈtɹæktə/','/ˈtɹæktɚ/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('patience','n.忍耐，耐心','/ˈpeɪʃəns/','/ˈpeɪʃəns/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('grace','n.优美，优雅；风度，魅力；宽限，缓期vt.使优美','/ɡɹeɪs/','/ɡɹeɪs/','noun',["The Princess brought grace to an otherwise dull and boring party.","It has become less common to say grace before having dinner.","The dancer moved with grace and strength."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('advertisement','n.广告，公告，登广告；广告活动，宣传','/ədˈvɜːtɪsmənt/','/ədˈvɝtɪzmənt/','noun',["Companies try to sell their products using advertisements in form of placards, television spots and print publications.","The city council placed an advertisement in the local newspaper to inform its residents of the forthcoming roadworks.","The good manners and intelligence of the students are an advertisement for the school."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ripe','adj.熟的；时机成熟的','/ɹaɪp/','/ɹaɪp/','noun',["ripe apples","ripe cheese"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('attribute','vt.把…归因于n.属性','','','noun',["His finest attribute is his kindness.","In the clause \"My jacket is more expensive than yours\", \"My\" is the attribute of \"jacket\".","A file with the read-only attribute set cannot be overwritten."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mechanism','n.机械装置；机制，机理；办法，途径','/ˈmɛkənɪzm/','/ˈmɛkənɪzm/','noun',["political machine"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('detection','n.察觉，发觉；侦查，探测','/dəˈtɛkʃən/','/dəˈtɛkʃən/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('triumph','vi.成功n.凯旋，胜利','/ˈtɹaɪ.ʌmf/','/ˈtɹaɪ.əmf/','noun',["the triumph of knowledge","Scorsese''s latest film is a triumph."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vice','n.罪恶；恶习，缺点；虎钳','/vaɪs/','/vaɪs/','noun',["Gluttony is a vice, not a virtue."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('horror','n.恐怖；憎恶；令人恐怖的事物','/ˈhɔɹɚ/','/ˈhɑɹɚ/','noun',["I saw many horrors during the war.","The neighbour''s kids are a pack of little horrors!"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('poison','n.毒，毒药vt.毒害','/ˈpɔɪz(ə)n/','/ˈpɔɪz(ə)n/','noun',["We used a poison to kill the weeds.","Gossip is a malicious poison.","— I''ll have a glass of whisky."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thoughtful','adj.沉思的；体贴的','/ˈθɔːtfəl/','/ˈθɔtfəl/','adjective',["Most thoughtful people eventually solve the puzzle.","Preparing dinner is a thoughtful gesture for a new mother."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gram','n.克','/ɡɹæm/','/ɡɹæm/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('empower','vt.授权于；使能够','','','verb',["John found that starting up his own business empowered him greatly in social situations."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('riot','vi.聚众闹事n.暴乱，骚乱；极度丰富vt.把浪费在放荡的生活上','/ˈɹaɪ.ət/','/ˈɹaɪ.ət/','noun',["In summer this flower garden is a riot of colour.","The nuclear protesters rioted outside the military base."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('arouse','vt.引起；唤起，唤醒','/əˈɹaʊz/','/əˈɹaʊz/','verb',["The new building proposals in the village are arousing unneeded discomfort.","I can''t keep my eyes off the dancer; she arouses me greatly.","1996, Beruga (line translated by Dan Owsen), Terranigma. Nintendo of America."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nest','v.筑巢n.巢，窝，穴','/nɛst/','/nɛst/','noun',["That nightclub is a nest of strange people!","I am aspiring to leave the nest.","I was forced to change trumps when I found the ace, jack, and nine of diamonds in the nest."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tour','n&vi.旅行，游历','/tɔː(ɹ)/','/tɔː(ɹ)/','noun',["On our last holiday to Spain we took a tour of the wine-growing regions.","On the company''s website, you can take a virtual tour of the headquarters.","Metallica''s tour of Europe"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('calm','adj.静的，平静的v.平静，镇静','/kam/','/kɑlm/','noun',["to calm a crying baby"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('boring','adj.令人厌烦的，乏味的，无聊的','/ˈbɔːɹɪŋ/','/ˈbɔːɹɪŋ/','verb',["An insect bores into a tree.","to bore a steam cylinder or a gun barrel; to bore a hole","to bore one''s way through a crowd"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('classic','adj.最优秀的，典型的，标准的；传统式样的，典雅的n.文学名著，经典作品，杰作；优秀的典范；古典文学，古典语文研究','/ˈklæ.sɪk/','/ˈklæ.sɪk/','noun',["Users who dislike the new visual layout can return to classic mode."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ownership','n.所有，所有制','','','noun',["The successful candidate will take ownership of all internal design projects."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('metric','adj.公制的，米制的','/ˈmɛt.ɹɪk/','/ˈmɛt.ɹɪk/','noun',["How to measure marketing? Use these key metrics for measuring marketing effectiveness.","Customer satisfaction was metricked by the marketing department."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('absolute','adj.十足的，地道的；绝对的，完全的；不受任何限制的','/ˈæb.səˌljuːt/','/ˈæb.səˌlut/','noun',["moral absolutes","1658, Samuel Hoard, God['']s Love to Mankind, Manifested, by disprooving his absolute decree for their damnation","absolute purity, absolute liberty"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ash','n.灰，灰末；骨灰','/æʃ/','/æʃ/','noun',["Ash from a fireplace can restore minerals to your garden''s soil.","The urn containing his ashes was eventually removed to a closet."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('describe','vt.形容；描写；画出','/dəˈskɹaɪb/','/dəˈskɹaɪb/','verb',["The feeling is difficult to describe, but not unpleasant.","to describe a circle by the compasses;   a torch waved about the head in such a way as to describe a circle","The function describes a very complex surface."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('suck','v.吸，吮，啜；吸收','/sʌk/','/sʌk/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('grab','v.抓取，攫取；赶紧做；抓住；抓，夺n.抓，夺','/ɡɹæb/','/ɡɹæb/','noun',["I grabbed her hand to pull her back from the cliff edge.","The suspect suddenly broke free and grabbed at the policeman''s gun.","How does that idea grab you?"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rub','vt.擦，摩擦','/ɹʌb/','/ɹʌb/','noun',["Give that lamp a good rub and see if any genies come out","a heat rub intended for muscular strains","I rubbed my hands together for warmth."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('presently','adv.不久，一会儿；现在，目前','/ˈpɹɛzəntli/','','adverb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wealthy','adj.富有的，富裕的','/ˈwɛl.θi/','/ˈwɛl.θi/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rug','n.地毯','/ɹʌɡ/','/ɹʌɡ/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('jazz','n.爵士音乐，爵士舞曲','/d͡ʒæz/','/d͡ʒæz/','noun',["What is all this jazz lying around?","I''m just going down to the shops and jazz.","That show was the jazz!"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dusk','n.薄暮，黄昏；幽暗','/dʌsk/','','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('administration','n.管理；管理部门，行政机关；实行，执行','/ədˌmɪnəˈstɹeɪʃən/','/ədˌmɪnəˈstɹeɪʃən/','noun',["Successive US administrations have had similar Middle East policies.","oral administration of insulin","The company went into voluntary administration last week."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('occasional','adj.偶尔的，间或发生的','/əˈkeɪʒ(ə)nəl/','/əˈkeɪʒ(ə)nəl/','noun',["He took an occasional glass of wine.","Elgar''s music was not created to be occasional music for high-school graduations.","What your living room needs are some occasional chairs."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('boast','vi.自夸；自豪vt.自夸，吹嘘；以拥有…而自豪n.自吹自擂，自夸的话','/bəʊst/','/boʊst/','noun',["It was his regular boast that he could eat two full English breakfasts in one sitting.","His family boasted a famous name."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('operator','n.操作人员；话务员，报务员','/ˈɒpəˌɹeɪtə/','/ˈɒpəˌɹeɪtə/','noun',["In the sentence \"What did Bill say he wants to buy?\", \"what\" is an operator, binding a phonetically empty variable."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('debate','n&v.争论，辩论','/dɪˈbeɪt/','','noun',["After a four-hour debate, the committee voted to table the motion.","The debate over the age of the universe is thousands of years old.","There has been considerable debate concerning exactly how to format these articles."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spacecraft','n.航天器，宇宙飞船','','','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('furniture','n.家具','/ˈfɜːnɪtʃə/','/ˈfɝnɪtʃɚ/','noun',["A chair is furniture. Sofas are also furniture."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('segment','n.部分，片段；瓣','','','noun',["a segment of rope","a segment of an orange;   a segment of a compound or divided leaf","The news showed a segment on global warming."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stripe','n.条纹','/st(ʃ)ɹʌɪp/','/st(ʃ)ɹʌɪp/','noun',["zebra stripes","persons of the same political stripe"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('jet','vi.乘喷气式飞机n.喷气式飞机；喷嘴；喷射','/dʒɛt/','/dʒɛt/','noun',["Farmers may either dip or jet sheep with chemicals.","jet airplane"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('helpful','adj.给予帮助的；有用的','/ˈhɛlp.fəl/','/ˈhɛlp.fəl/','adjective',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('statistic','n.统计数值，统计资料；统计学','','','noun',["By dying from an overdose, he became just another statistic."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('attractive','adj.有吸引力的，引起注意的','/əˈtɹæktɪv/','/əˈtɹæktɪv/','adjective',["That''s a very attractive offer.","He is an attractive fellow with a trim figure."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('superb','adj.极好的；高质量的','/sjuːˈpɜːb/','/suˈpɝb/','adjective',["This champagne is superb.","a superb edifice;  a superb colonnade"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mold','n.霉，霉菌；模型，铸模；性格vt.用模子制作，塑造；使形成，影响…的形成','/mɔʊld/','/moʊld/','noun',["the oval mold of her face","a leader in the mold of her predecessors","His method of scientific investigation broke the mold and led to a new discovery."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('engineering','n.工程，工程学','/ˌen.dʒɪˈnɪə.ɹɪŋ/','/ˌen.dʒɪˈnɪə.ɹɪŋ/','verb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('significant','adj.相当数量的；重要的，意义重大的，意味深长的','/sɪɡˈnɪ.fɪ.kənt/','/sɪɡˈnɪ.fɪ.kənt/','noun',["a significant word or sound; a significant look","That was a significant step in the right direction."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bold','adj.勇敢的；鲁莽的；粗体的，黑体的；醒目的','/bəʊld/','/boʊld/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bleed','vi.出血，流血；泌脂vt.勒索…的钱','/ˈbliːd/','/ˈbliːd/','noun',["If her nose bleeds, try to use ice.","The company was bleeding talent.","Ink traps counteract bleeding."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('delicious','adj.美味的；芬芳的，怡人的；有趣的','/dɪˈlɪʃəs/','/diˈlɪʃəs/','adjective',["The irony is delicious!"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('catalogue','n.目录v.为…编目录，把…列入目录中','/ˈkætəlɑɡ/','/ˈkætəlɔɡ/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('whatever','adv.[用于否定句中以加强语气]任何；无论什么','/wɒtˈɛvə/','/wʌtˈɛvɚ/','adjective',["There is no point whatever in going on with this discussion.","Whatever he does, he will still lose the game.","I’ll do whatever I can."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('decrease','v.减少n.减少','','','noun',["One research team has recorded Baishui’s decrease at about 27 meters per year over the last 10 years."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('volunteer','v.自愿提供；自愿，志愿n.志愿者；志愿兵','/vɒl.ənˈtɪə/','/vɑl.ənˈtɪɹ/','noun',["to volunteer for doing the dishes","to volunteer an explanation","My sister volunteered me to do the dishes."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('museum','n.博物馆','/mjuːˈziːəm/','/mjuˈzi.əm/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ignorance','n.无知，愚昧','/ˈɪɡnəɹəns/','/ˈɪɡnəɹəns/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('senate','n.参议院，上院','/ˈsɛnət/','/ˈsɛnət/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trumpet','n.喇叭，小号vt.大声宣告，鼓吹','/ˈtɹʌmpɪt/','/ˈtɹʌmpɪt/','noun',["The royal herald sounded a trumpet to announce their arrival.","The trumpets were assigned to stand at the rear of the orchestra pit.","The large bull gave a basso trumpet as he charged the hunters."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bolt','n.螺栓，插销vt.闩门','/bɒlt/','/boʊlt/','noun',["The problem''s solution struck him like a bolt from the blue.","24 March 1774 - Newspaper: Stamford Mercury - \"Mr. Cole, Basket-maker...has lost near 300 boults of rods\" https//www.britishnewspaperarchive.co.uk/viewer/bl/0000254/17740324/001/0001","The horse made a bolt."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('string','vi.连成一串；排成一行前进n.线，细绳；一串，一行vt.缚，扎，挂；串起，穿；使排成一列；伸展，拉直','/stɹɪŋ/','/stɹɪŋ/','noun',["There were stalls for fourteen horses in the squire''s stables.","a bowstring","a string of sausages"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('import','vt.输入，进口n.输入，进口；进口商品；意义，重要性','/ˈɪm.pɔːt/','/ˈɪm.pɔːt/','noun',["It was a matter of great import.","How can I import files from older versions of this application?"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('occupy','vt.占领，占，占有','/ˈɒkjʊpaɪ/','/ˈɒkjʊpaɪ/','verb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('submit','vi.屈从，听从，服从vt.呈送，提交；主张，建议；使服从，使降服','/səbˈmɪt/','/səbˈmɪt/','verb',["They will not submit to the destruction of their rights.","I submit these plans for your approval."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mood','n.心情，情绪；语气','/muːd/','/muːd/','noun',["I''ve been in a bad mood since I dumped my boyfriend.","He''s in a mood with me today.","I''m not in the mood for running today."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('boom','vi.激增，繁荣，迅速发展；发出隆隆声n.激增，繁荣，迅速发展；隆隆声，嗡嗡声','/buːm/','/buːm/','noun',["The boom of the surf.","You should prepare for the coming boom in the tech industry.","I can hear the organ slowly booming from the chapel."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('absence','n.缺席，不在；缺席的时间，外出期；缺乏，不存在','/ˈæb.s(ə)n̩s/','/æbˈsɒns/','noun',["Absence makes the heart grow fonder.","He had an absence of enthusiasm.","absence of mind"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('attract','vt.吸引，引起…注意','/əˈtɹækt/','/əˈtɹækt/','verb',["A magnet attracts iron filings.","Advertising is designed to attract customers.","to attract admirers;   His big smile and brown eyes instantly attracted me."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('edition','n.版，版本，版次','/əˈdɪʃən/','/əˈdɪʃən/','noun',["The first edition was soon sold.","The 2014 edition of the Tour de France started in Leeds, Yorkshire."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('simplicity','n.简单，简易；朴素','/sɪmˈplɪsɪti/','/sɪmˈplɪsɪti/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cautious','adj.十分小心的，谨慎的','/ˈkɔːʃəs/','/ˈkɔːʃəs/','adjective',["He took a few cautious steps toward the cave."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disappear','vi.不见，失踪，消失','/dɪsəˈpiːɹ/','/dɪsəˈpɪɹ/','verb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('summit','n.最高点，峰顶；最高级会议','/ˈsʌmɪt/','/ˈsʌmɪt/','noun',["In summer, it is possible to hike to the summit of Mount Shasta.","They met for an international summit on environmental issues."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('recession','n.衰退，衰退期','/ɹɪˈsɛʃn̩/','/ɹɪˈsɛʃn̩/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conclusion','n.结论，推论；结尾；缔结，议定','/kənˈkluːʒən/','/kənˈkluːʒən/','noun',["The board has come to the conclusion that the proposed takeover would not be in the interest of our shareholders."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('typist','n.打字员','/ˈtaɪpɪst/','/ˈtaɪpɪst/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('durable','adj.耐久的，耐用的','/ˈd(j)ʊəɹəbəl/','/ˈd(j)ʊəɹəbəl/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('negative','adj.否定的，消极的；负的；阴性的n.负片，底片；负数','/ˈnɛ(e)ɡəˌɾɪv/','/-ɾɪv/','noun',["Customers didn’t like it: feedback was mostly negative.","I don’t like to hang around him very much because he can be so negative about his petty problems.","The nitro group is negative."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('impose','vi.利用，占便宜；欺骗vt.把…强加于；征','/ɪmˈpəʊz/','/ɪmˈpoʊz/','verb',["Congress imposed new tariffs.","I don''t wish to impose upon you.","Social relations impose courtesy"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ally','v.结盟，联合n.同盟国，同盟者；支持者','','','noun',["the two countries were allies in WWI","Gruiformes — cranes and allies"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('statement','n.陈述，声明；结算单，报表','/ˈsteɪtm(ə)nt/','/ˈsteɪtmənt/','noun',["a bank statement"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hence','adv.因此，所以；今后','/ˈhɛns/','/ˈhɛns/','adverb',["Get thee hence, Satan!","After a long battle, my poor daughter was taken hence.","A year hence it will be forgotten."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('memorial','adj.纪念的，悼念的n.纪念碑，纪念堂，纪念仪式','/məˈmoʊɹi.əl/','/məˈmoʊɹi.əl/','noun',["a memorial building","a memorial possession"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('factor','n.因素；因子；系数','/ˈfæktə/','/ˈfæktɚ/','noun',["The factor of the trading post bought the furs.","The economy was a factor in this year''s budget figures.","3 is a factor of 12, as are 2, 4 and 6."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('boot','n.靴子，长筒靴；行李箱；解雇','/buːt/','/but/','noun',["I booted the ball toward my teammate.","We need to boot those troublemakers as soon as possible","Sorry, I didn’t mean to boot all over your couch."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pinch','vt.捏，拧n.撮，微量','/pɪntʃ/','/pɪntʃ/','noun',["I gave the leather of the sofa a pinch, gauging the texture.","The children were scolded for pinching each other.","Someone has pinched my handkerchief!"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('delivery','n.投递，交付；分娩；讲话方式；投递的邮件','/dɪˈlɪv(ə)ɹi/','/dɪˈlɪv(ə)ɹi/','noun',["The delivery was completed by four.","Your delivery is on the table.","The delivery was painful."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rack','n.挂架，搁架vt.使痛苦，折磨；尽力使用','/ɹæk/','/ɹæk/','noun',["I bought a rack of lamb at the butcher''s yesterday.","abseil rack","I used almost a full rack on the second pitch."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('election','n.选举；选择权；当选','/ɪˈlɛkʃ(ə)n/','/əˈlɛkʃ(ə)n/','noun',["How did you vote in (UK also: at) the last election?","The election of John Smith was due to his broad appeal.","W-4 election"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conquer','vt.征服，战胜；破除，克服','/ˈkɒŋkə/','/ˈkɑŋkɚ/','verb',["In 1453, the Ottoman Empire conquered Istanbul.","Today I conquered my fear of flying by finally boarding a plane.","to conquer freedom;   to conquer a peace"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('learned','adj.有学问的；学术上的','/ˈlɜːnɪd/','/ˈlɜːnɪd/','adjective',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('substance','n.物质；实质；大意，要旨；根据，理由','/ˈsʌbstəns/','/ˈsʌbstəns/','noun',["Some textile fabrics have little substance.","a man of substance","substance abuse"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('frown','n&vi.皱眉，蹙额','/fɹaʊn/','/fɹaʊn/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bond','v.黏合，结合n.联结，联系；公债；契约，合同','/bɒnd/','/bɑnd/','noun',["Investors face a quandary. Cash offers a return of virtually zero in many developed countries; government-bond yields may have risen in recent weeks but they are still unattractive. Equities have suffered two big bear markets since 2000 and are wobbling again. It is hardly surprising that pension funds, insurers and endowments are searching for new sources of return.","The prisoner was brought before the tribunal in iron bonds.","They had grown up as friends and neighbors, and not even vastly differing political views could break the bond of their friendship."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('target','n.目标vt.把…作为目标；瞄准','/tɑːɡɪt/','/ˈtɑɹɡɪt/','noun',["Take careful aim at the target.","They have a target to finish the project by November.","He made a good target."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wax','n.蜡，蜂蜡vt.给…上蜡','/wæks/','/wæks/','noun',["What role does the wax in your earhole fulfill?"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('grind','v.磨，磨快','/ˈɡɹaɪnd/','/ˈɡɹaɪnd/','noun',["This bag contains espresso grind.","This homework is a grind.","grind a lens; grind an axe"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('urban','adj.城市的，都市的；住在都市的','/ˈɜːbən/','/ˈɜːbən/','adjective',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('furthermore','adv.而且，此外','/ˈfɜː(ɹ).ðə(ɹ).mɔː(ɹ)/','','adverb',["He skillfully took charge of the event, and furthermore, he stayed late after it to clean up."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('guidance','n.引导，指导，领导','/ˈɡaɪdəns/','/ˈɡaɪdəns/','noun',["divine guidance"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('risk','n.危险，风险；引起危险的事物vt.冒…的危险，使遭受危险','/ɹɪsk/','/ɹɪsk/','noun',["2006, Trever Ramsey on BBC News website, Exercise ''cuts skin cancer risk'' read at http//news.bbc.co.uk/1/hi/health/4764535.stm on 14 May 2006"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flame','n.火焰，光辉；热情','/fleɪm/','/fleɪm/','noun',["The cello has a two-piece back with a beautiful narrow flame.","I flamed him for spamming in my favourite newsgroup."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('container','n.容器；集装箱','/kənˈteɪnə/','/kənˈteɪnə/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('leader','n.领袖，领导人，首领','/ˈlidɚ/','/ˈlidɚ/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('delicate','adj.纤细的，易碎的；微妙的；精美的','/ˈdɛlɪkət/','/ˈdɛlɪkət/','noun',["Don''t put that in with your jeans: it''s a delicate!","The negotiations were very delicate.","Her face was delicate."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('discard','vt.丢弃，抛弃，遗弃','/ˈdɪskɑːd/','/ˈdɪskɑːd/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fancy','adj.昂贵的；别致的n.想象力，设想；爱好vt.喜欢；想象，猜想','/ˈfæn.si/','/ˈfæn.si/','noun',["I had a fancy to learn to play the flute.","He took a fancy to her.","Trainspotting is the fancy of a special lot."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rebel','vi.反叛，造反；反对，不服从n.反叛分子，反对者','/ˈɹɛbəl/','/ˈɹɛbəl/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bounce','v.弹起，反弹；颠簸n.弹，反弹','/baʊns/','/baʊns/','noun',["Them pro-ballers got bounce!","The tennis ball bounced off the wall before coming to rest in the ditch.","He bounces nervously on his chair."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('usage','n.使用；对待；惯用法','/ˈjuːsɪd͡ʒ/','/ˈjuːsɪd͡ʒ/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tissue','n.组织；薄绢，薄纸，手巾纸','/ˈtɪsjuː/','/ˈtɪʃu/','noun',["a tissue of forgeries, or of lies"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('experimental','adj.实验的，试验的','/ɨkspɛɹəˈmɛntəl/','/ɨkspɛɹəˈmɛntəl/','noun',["Chemistry is an experimental science.","an experimental engine","experimental knowledge"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('loosen','vt.解开；放松，松弛','/ˈluːsn̩/','','verb',["After the Thanksgiving meal, Bill loosened his belt.","I noticed that my seatbelt had gradually loosened during the journey."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rent','v.租借，租用；出租，出借n.租金；出租','/ɹɛnt/','/ɹɛnt/','noun',["A New York city taxicab license earns more than $10,000 a year in rent.","I rented a house from my friend''s parents for a year.","We rented our house to our son''s friend for a year."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nearby','adv.在附近adj.附近的','','','adjective',["He stopped at a nearby store for some groceries.","I''m glad my friends live nearby where I can visit them."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('carpenter','n.木工，木匠','/ˈkɑː.pən.tə/','/ˈkɑː.pən.tə/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cart','n.运货马车','/kɑːt/','/kɑɹt/','noun',["The grocer delivered his goods by cart.","I''ve been carting these things around all day."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('modest','adj.谦虚的；适中的；羞怯的','/ˈmɑdəst/','/ˈmɑdəst/','adjective',["He earns a modest amount of money.","modest thoughts or language"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cast','vt.投，扔，抛；浇铸n.演员表，全体演员；石膏绷带；铸型，铸件；投，抛','/kæst/','/kæst/','noun',["The area near the stream was covered with little bubbly worm casts.","He’s in the cast of Oliver.","The men got into position for the cast, two at the ladle, two with long rods, all with heavy clothing."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('anxious','adj.忧虑的，令人焦急的；渴望的','/ˈaŋ(k)ʃəs/','/ˈæŋ(k).ʃəs/','adjective',["I could tell she was anxious as she was biting her nails.","There was an anxious wait before the results were revealed.","All the voters were anxious to hear the election result."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hatred','n.憎恶，憎恨，仇恨','/ˈheɪtɹɪd/','/ˈheɪtɹɪd/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crush','vt.压碎，碾碎；摧毁，压垮','/kɹʌʃ/','/kɹʌʃ/','noun',["a crush at a reception","I''ve had a huge crush on her since we met many years ago.","to crush grapes"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('largely','adv.大部分，大量地','[ˈlaːdʒ.li]','[ˈlɑɹdʒ.li]','adverb',["They were largely successful in their efforts."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('slice','n.薄片，切片；部分vt.切，削','/slaɪs/','/slaɪs/','noun',["Jim was munching on a slice of toast.","I bought a ham and cheese slice at the service station.","Slice the cheese thinly."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('frost','v.结霜n.冰冻，严寒；霜','/fɹɑst/','/fɹɔst/','noun',["I think the boss''s decision frosted him a bit."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('electron','n.电子','/ɪˈlɛktɹɒn/','/ɪˈlɛktɹɑn/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('incline','v.倾斜；弯；倾向于n.斜坡','','','noun',["To reach the building, we had to climb a steep incline.","He had to incline his body against the gusts to avoid being blown down in the storm.","Over the centuries the wind made the walls of the farmhouse incline."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('truly','adv.真正地；忠实地','/ˈtɹuːli/','','adverb',["That is truly all I know.","You are truly silly."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cash','n.现金，现款vt.把…兑现','/kæʃ/','/kæʃ/','noun',["After you bounced those checks last time, they want to be paid in cash."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('counsel','n.律师，法律顾问；忠告，劝告vt.劝告，提议','/ˈkaʊn.səl/','/ˈkaʊn.səl/','noun',["Psychiatrists, psychologists, social workers and other mental health professionals counsel clients.","I would counsel prudence in this matter."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('item','n.条，条款，一条','[ˈaɪ̯ɾm̩]','[ˈaɪ̯ɾm̩]','noun',["Tweezers are great for manipulating small items.","In response to the first item, we deny all wrongdoing.","The exam has 100 items, each of which includes a correct response and three distractors."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gene','n.基因','/dʒiːn/','/dʒiːn/','noun',["A change in a gene is reflected in the protein or RNA molecule that it codes for."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('liver','n.肝','/ˈlɪvə/','/ˈlɪvɚ/','noun',["Steve Jobs is a famous liver transplant recipient.","I''d like some goose liver pate."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('suicide','n&v.自杀','','','',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('violet','adj.紫色的n.紫罗兰','/ˈvaɪlət/','/ˈvaɪlət/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hollow','adj.空的，空洞的；沉闷的；虚伪的','/ˈhɒl.əʊ/','/hɑlɚ/','noun',["He built himself a cabin in a hollow high up in the Rockies.","the hollow of the hand or of a tree","a hollow in the pit of one''s stomach"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trunk','n.树干；大衣箱，皮箱；汽车后备箱；象鼻','/tɹʌŋk/','/tɹʌŋk/','noun',["the trunk of a vein or of an artery, as distinct from the branches"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('saving','n.节省，节约；储蓄金，存款','/ˈseɪvɪŋ/','/ˈseɪvɪŋ/','verb',["The shift of the supplier gave us a saving of 10 percent.","I invested all my savings in gold.","a saving cook"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rely','vi.依靠，依赖；信赖，指望','/ɹɪˈlaɪ/','/ɹɪˈlaɪ/','verb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hospitalize','vt.就医','','','verb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('slide','v.滑；悄悄地移动n.滑动；滑道，滑面；幻灯片','/slaɪd/','/slaɪd/','noun',["The long, red slide was great fun for the kids.","The slide closed the highway.","a slide on the ice"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('utilize','vt.利用','/ˈjuːtɨlaɪz/','/ˈjuːtɨlaɪz/','verb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sticky','adj.黏性的，胶黏的；湿热的','/ˈstɪki/','/ˈstɪki/','noun',["Her desk is covered with yellow stickies.","Is this tape sticky enough to stay on that surface?","This is a sticky situation. We could be in this for weeks if we''re not careful."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prevail','vi.流行，盛行','/pɹɪˈveɪl/','/pɹɪˈveɪl/','verb',["Red colour prevails in the Canadian flag.","In his day and age, such practices prevailed all over Europe.","I prevailed on him to wait."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('waist','n.腰，腰部','/weɪst/','/weɪst/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('excessive','adj.过多的，极度的','/ɪkˈsɛsɪv/','/ɪkˈsɛsɪv/','adjective',["Putting a wide vibrato on a single 16th triplet note at 160 beats per minute seems rather excessive."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flesh','n.肉，肌肉，肉体','/flɛʃ/','/flɛʃ/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('jungle','n.丛林，密林，莽丛；乱七八糟的一堆','/ˈdʒʌŋ.ɡ(ə)l/','/ˈdʒʌŋ.ɡ(ə)l/','noun',["It’s a jungle out there."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('portion','n.一部分，一份vt.分配，把…分给','/ˈpoəɹʃən/','/ˈpɔɹʃən/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('settle','v.安排，安放；调停；支付，核算；安家；飞落，停留；安定','/ˈsɛtəl/','/ˈsɛtəl/','verb',["to settle her estate","the weather settled;  wait until the crowd settles before speaking","the Saxons who settled in Britain"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pattern','n.型，式样，模型vt.仿制，使照…样子','/ˈpat(ə)n/','/ˈpat(ə)n/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('harsh','adj.严厉的；粗糙的','/hɑːʃ/','/hɑːʃ/','verb',["Quit harshing me already, I said that I was sorry!","Dude, you''re harshing my buzz."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('connexion','n.connection的英式拼法','/kəˈnɛkʃən/','/kəˈnɛkʃən/','noun',["My headache has no connection with me going out last night.","As we were the only people in the room to laugh at the joke, I felt a connection between us.","I was talking to him, but there was lightning and we lost the connection."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vehicle','n.车辆，机动车；传播媒介，工具，手段','/ˈvɪː(ə).kəl/','/ˈvi.ə.kəl/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scrape','v.刮，擦n.刮，擦；刮擦声','/skɹeɪp/','/skɹeɪp/','noun',["He fell on the sidewalk and got a scrape on his knee.","He got in a scrape with the school bully.","I''m in a bit of a scrape — I''ve no money to buy my wife a birthday present."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hardship','n.艰难，困苦','/ˈhɑːdˌʃɪp/','/ˈhɑːdˌʃɪp/','noun',["He has survived periods of financial hardship before."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('confuse','vt.使困惑，把…弄糊涂；混淆，把…混同；混乱，搞乱','/kənˈfjuːz/','/kənˈfjuːz/','verb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cushion','n.垫子，坐垫，靠垫','/ˈkʊʃən/','/ˈkʊʃən/','noun',["to cushion a sofa","to cushion a blow"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scold','v.责骂，训斥','/skəʊld/','/skoʊld/','verb',["to scald the hand","Scald the milk until little bubbles form."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('glorious','adj.光荣的；壮丽的；令人愉快的','/ˈɡlɔː.ɹi.əs/','/ˈɡlɔɹ.i.əs/','adjective',["glorious deeds"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('civilize','vt.使文明，使开化，教育','','','verb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('physician','n.内科医生','/fɪˈzɪʃən/','/fɪˈzɪʃən/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('architecture','n.建筑学；建筑式样，建筑风格','/ˈɑː.kɪ.ˌtɛk.tʃə/','/ˈɑɹkɪtɛktʃɚ/','noun',["Architecture is the visual public expression of a culture’s achievements, values, and outlook. ― Max Roscoe, \"How Your City Is Killing You With Ugliness\"","The Intel architectures have more software written for them.","The architecture of the company''s billing system is designed to support its business goals."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stress','n.压力；强调；重要性；应力；重音vt.强调，着重；重读','/stɹɛs/','/stɹɛs/','noun',["Go easy on him, he''s been under a lot of stress lately.","Some people put the stress on the first syllable of “controversy”; others put it on the second.","“Emphasis” is stressed on the first syllable, but “emphatic” is stressed on the second."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('grip','v.握紧，抓牢；吸引住n.紧握','/ɡɹɪp/','/ɡɹɪp/','verb',["After a few slips, the tires gripped the pavement.","He grips me.","Let’s grip (get a coffee, hang, take a break, see a movie, etc.)"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('explore','vt.探险，探索；仔细查阅，探究','/ɪkˈsplɔː/','/ɪkˈsplɔɹ/','noun',["The committee has been exploring alternative solutions to the problem at hand.","It was around that time that the expedition began exploring the Arctic Circle.","It is normal for a boy of this age to be exploring his sexuality."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('display','vt.陈列，展览，显示','/dɪsˈpleɪ/','/dɪsˈpleɪ/','noun',["The trapeze artist put on an amazing acrobatic display.","Pupils are expected to produce a wall display about a country of their choice."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('electricity','n.电','/ɪˌlɛkˈtɹɪsɪti/','/iˌlɛkˈtɹɪsɪti/','noun',["Opening night for the new production had an electricity unlike other openings."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('climate','n.气候；风土，地带；风气，气氛','/ˈklaɪmɪt/','/ˈklaɪmɪt/','noun',["Industries that require a lot of fossil fuels are unlikely to be popular in the current political climate."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conductor','n.售票员，列车长；指挥；导体','/kənˈdʌktɚ/','/kənˈdʌktɚ/','noun',["train conductor; tram conductor"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bore','vt.使厌烦；钻，挖n.令人讨厌的人','/bɔː/','/bɔɹ/','noun',["the bore of a cannon","An insect bores into a tree.","to bore a steam cylinder or a gun barrel; to bore a hole"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crust','n.面包皮，硬外皮；外壳，地壳','/kɹʌst/','/kɹʌst/','noun',["You''ve got a lot of crust standing there saying that.","to earn one''s crust"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disorder','n.混乱，杂乱，骚乱','/dɪsˈɔːdə(ɹ)/','/dɪsˈɔːɹdɚ/','noun',["After playing the children left the room in disorder.","The army tried to prevent disorder when claims the elections had been rigged grew stronger.","Bulimia is an eating disorder."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('criticize','vt.批评；评论；非难','/ˈkɹɪtɪsaɪz/','/ˈkɹɪtɪsaɪz/','verb',["They criticized him for endangering people''s lives."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('organization','n.组织，团体，机构','/ˌɔɹɡənaɪˈzeɪʃən/','/ˌɔɹɡənɪˈzeɪʃən/','noun',["This painting shows little organization at first glance, but little by little the structure becomes clear.","The organization of the book is as follows.","In response to the crisis, the nations in the region formed an organization.   If you want to be part of this organization, you have to follow its rules."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rage','vi.狂吹；汹涌；激烈进行；发怒，发火n.狂怒，盛怒；风靡一时的事物，时尚','/ɹeɪdʒ/','/ɹeɪdʒ/','noun',["Miniskirts were all the rage back then."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('width','n.宽阔，广阔；宽度','/ˈwɪdθ/','/ˈwɪdθ/','noun',["Manchester United like to play with width."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dairy','adj.乳制品的n.牛奶场；乳制品','/ˈdɛəɹi/','/ˈdɛəɹi/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('board','vi.搭伙；膳宿n.板，牌子；木板，纸板；委员会，董事会；伙食vt.上','/bɔːd/','/bɔːd/','noun',["Each player starts the game with four counters on the board.","We have to wait to hear back from the board.","Room and board"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('economic','adj.经济的，经济学的n.经济学；经济状况','/ˌiːkəˈnɒmɪk/','/ˌiːkəˈnɒmɪk/','adjective',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stuff','n.材料，东西vt.装，填，塞；让…吃饱','/stʌf/','/stʌf/','noun',["What is all that stuff on your bedroom floor?  He didn''t want his pockets to bulge so he was walking around with all his stuff in his hands.","I had to do some stuff.","Can I have some of that stuff on my ice-cream sundae?"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('arrest','vt.逮捕，拘留；停止，阻止；吸引n.逮捕，拘留，扣留','/əˈɹɛst/','/əˈɹɛst/','noun',["The police have arrested a suspect in the murder inquiry."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('widow','n.寡妇','/ˈwɪ.dəʊ/','/ˈwɪ.doʊ/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('distinction','n.差别，不同，区分','/dɪˈstɪŋkʃən/','/dɪˈstɪŋkʃən/','noun',["There is a distinction to be made between resting and slacking.","She had the distinction of meeting the Queen."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mature','adj.成熟的；成年人的；深思熟虑的；到期的，应支付的vt.使成熟','/məˈtjʊə/','/məˈtjʊə/','adjective',["She is quite mature for her age.","a mature plan","The headmaster decided to expel the boy after a mature consideration."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('navy','n.海军','/ˈneɪvi/','/ˈneɪvi/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fee','n.费；酬金，赏金','/fiː/','/fiː/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('section','n.部分，章节；部门，科；截面，剖面','/ˈsɛkʃən/','/ˈsɛkʃən/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('influence','n.影响，作用；影响力，势力；产生影响力的人vt.影响','/ˈɪn.flu.əns/','/ˈɪn.flu.əns/','noun',["I have absolutely no influence over him.","I''m not able to exercise influence over him.","He has been a great influence on the voters during the elections."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('whip','vt.鞭笞；猛地移动；搅打成糊状n.鞭子','/wɪp/','/wɪp/','noun',["I had to use the whip to get the sheep''s attention.","I was going to vote against the bill, but the party whip came to see me and made it clear I needed to vote for it.","Did you want to add some whip to your coffee, ma''am?"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('protocol','n.礼仪，礼节；草案，议定书','/ˈpɹəʊtəˌkɒl/','/ˈpɹəʊtəˌkɒl/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('whale','n.鲸','/weɪl/','/weɪl/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('provoke','vt.对…挑衅，激怒；激起，引起','/pɹəˈvəʊk/','/pɹəˈvoʊk/','verb',["Don''t provoke the dog; it may try to bite you."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('threaten','v.威胁，恐吓；预示快要来临，是…的征兆；构成威胁；可能发生','/ˈθɹɛt.n̩/','/ˈθɹɛt.n̩/','verb',["He threatened me with a knife.","The rocks threatened the ship''s survival.","The black clouds threatened heavy rain."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('talent','n.天才，才能；人才','/ˈtalənt/','/ˈtælənt/','noun',["He has a real talent for drawing.","The director searched their talent pool to fill the new opening.","Not much talent in this bar tonight—let''s hit the clubs."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('percentage','n.百分比，百分率','/pəˈsɛntɪd͡ʒ/','/pɚˈsɛntɪd͡ʒ/','noun',["A high percentage of secondary school leavers take a gap year.","She gets a percentage for every vacuum cleaner sold.","There was no percentage in staying at home."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('negotiate','v.洽谈，协商；顺利通过，成功越过；协商，谈判','/nəˈɡəʊ.ʃi.eɪt/','/nəˈɡoʊ.ʃi.eɪt/','verb',["The client and server computers must first negotiate a network protocol to be used.","Although the car was quite rickety, he could negotiate the curves very well."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('strain','v.扭伤，拉伤；尽力；拉紧n.拉紧；过劳；极度紧张；张力；扭伤，拉伤；旋律；品种，家系；气质，个性特点','/stɹeɪ̯n/','/stɹeɪ̯n/','noun',["There is a strain of madness in her family.","They say this year''s flu virus is a particularly virulent strain."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hunt','v.打猎；搜寻；驱逐','/hʌnt/','/hʌnt/','noun',["Her uncle will go out and hunt for deer, now that it is open season.","The little girl was hunting for shells on the beach.","He was hunted from the parish."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('violin','n.小提琴','/ˌvɑe.ɘˈlɘn/','/ˌvaɪəˈlɪn/','noun',["The first violin often plays the lead melody lines in a string quartet."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('remonstrate','v.抗议','/ˈɹɛ.mən.stɹeɪt/','/ˈɹɛ.mən.stɹeɪt/','verb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('package','n.包裹，包装；一揽子交易vt.把…打包；包装','/ˈpækɪdʒ/','/ˈpækɪdʒ/','noun',["Did you test the software package to ensure completeness?","For third and short, they''re going to bring in their jumbo package."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('visible','adj.可见的，看得见的，有形的','/ˈvɪzəb(ə)l/','/ˈvɪzəb(ə)l/','adjective',["When the sun rises, the world becomes visible."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crisis','n.危机，存亡之际；关键阶段','/ˈkɹaɪsɪs/','/ˈkɹaɪsɪs/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rail','vi.责骂，抱怨n.栏杆，横杆；铁轨，轨道；铁路','/ɹeɪl/','/ɹeɪl/','noun',["We travelled to the seaside by rail.","We''re experimenting with ads in the right-hand rail."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('survival','n.幸存；幸存者，残存物','/sɚˈvaɪvəl/','/sɚˈvaɪvəl/','noun',["His survival in the open ocean was a miracle; he had fully expected to die.","His survival kit had all the things he needed in the wilderness."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('germ','n.微生物，细菌；幼芽','/d͡ʒɜːm/','/d͡ʒɝm/','noun',["the germ of civil liberty"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inner','adj.内部的；内心的','/ˈɪnə/','/ˈɪnɚ/','noun',["inner door;  inner room;  inner sanctum;  inner surface","the inner suburbs","inner ear"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('market','n.市场；股市；行情，销路','/ˈmɑːkɪt/','/ˈmɑɹkɪt/','noun',["The privilege to hold a weekly market was invaluable for any feudal era burgh.","Stop by the market on your way home and pick up some milk","We believe that the market for the new widget is the older homeowner."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('keen','adj.热心的；激烈的；敏锐的，敏捷的','/kiːn/','/kin/','verb',["I’m keen on computers.","This boy has a keen appetite.","keen satire or sarcasm"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('glimpse','vi.看一眼，一瞥vt.瞥见n.一瞥，一看','/ɡlɪmps/','/ɡlɪmps/','noun',["I only got a glimpse of the car, so I can tell you the colour but not the registration number.","I have only begun to glimpse the magnitude of the problem."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('detective','n.侦探，私人侦探','/dɪˈtɛktɪv/','/dɪˈtɛktɪv/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('transfer','v.搬，转移；调动，转学；转让，过户；乘车，转乘','/tɹænzˈfɜː/','/ˈtɹænsfɝ/','noun',["to transfer the laws of one country to another; to transfer suspicion","to transfer drawings or engravings to a lithographic stone","The title to land is transferred by deed."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('footstep','n.脚步，脚步声，足迹','/ˈfʊtstɛp/','/ˈfʊtstɛp/','noun',["The child watched as his footsteps in the sand were washed away by the waves.","To walk the footsteps of greatness requires that you start at the bottom of a long stair.","The footsteps of the students echoed in the empty hall."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('veteran','n.老兵，老手','[ˈvɛ.t̬ə.ɹən]','[ˈvɛ.t̬ə.ɹən]','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('indifferent','adj.冷漠的，不积极的；一般的，平平的','/ɪnˈdɪf.ə.ɹənt/','/ɪnˈdɪf.ə.ɹənt/','noun',["He was indifferent to the proposal, since it didn’t affect him, either way.","She responded with an indifferent shrug.","The long distance and the indifferent roads made the journey impossible."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('outside','adj.外部的prep.在…的外面；向…的外面；除…以外n.外部，外表','','','noun',["He''s repainting the outside of his house.","Her outside was stern, but inside was a heart of gold.","Viewed from the outside, the building seemed unremarkable."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nerve','n.神经；勇敢，胆量','/nɛɾv/','/nɜɪv/','noun',["The nerves can be seen through the skin.","Some plants have ornamental value because of their contrasting nerves.","He hasn''t the nerve to tell her he likes her. What a wimp!"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('affection','n.感情；爱，爱慕','/əˈfɛkʃən/','/əˈfɛkʃən/','noun',["I have a lot of affection for my little sister."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('eagle','n.鹰','/ˈiːɡəl/','/ˈiːɡəl/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cruise','vi.航游，巡航；缓慢巡行n.航游，游弋','/kɹuːz/','/kɹuːz/','noun',["Germany cruised to a World Cup victory over the short-handed Australians."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('elementary','adj.基本的，初级的','/(ˌ)ɛlɪ̈ˈmɛnt(ə)ɹɪ/','/(ˌ)ɛlɪ̈ˈmɛnt(ə)ɹɪ/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('topic','n.题目，论题，话题','/ˈtɒpɪk/','/ˈtɑpɪk/','noun',["A society where a topic cannot be discussed, does not have free speech."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('solemn','adj.庄严的，隆重的；严肃的','/ˈsɒləm/','/ˈsɑləm/','adjective',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('perceive','vt.感知，感觉，察觉；认识到，意识到；理解','/pəˈsiːv/','/pɚˈsiv/','verb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('omit','vt.省略；遗漏','/oʊˈmɪt/','/oʊˈmɪt/','verb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('embarrass','vt.使窘迫，使为难','/ɪmˈbæ.ɹəs/','/ɪmˈbæ.ɹəs/','verb',["The crowd''s laughter and jeers embarrassed him.","The motion was advanced in order to embarrass the progress of the bill.","A man or his business is embarrassed when he cannot meet his pecuniary engagements."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('option','n.选择，选择权，选择自由；选择的事物或人，选课','/ˈɒpʃən/','/ˈɑpʃən/','noun',["The new novel was optioned by the film studio, but they''ll probably never decide to make a movie from it."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('erroneous','adj.错误的，不正确的','/ɛɹˈəʊ.nɪ.əs/','/ɛɹˈəʊ.nɪ.əs/','adjective',["His answer to the sum was erroneous.","His conclusion was erroneous, since it was based on a false assumption.","Her choice at the line-up proved to be erroneous, as she had only seen the mugger for an instant."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('raid','n&vt.袭击；突入查抄，突入搜捕；劫掠','/ɹeɪd/','/ɹeɪd/','noun',["a police raid of a narcotics factory","The police raided the gambling den.","I raided the fridge for snacks."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('politics','n.政治，政治学；政纲，政见','/ˈpɒl.ɪ.tɪks/','/ˈpɑl.ɪˌtɪks/','verb',["He made a career out of politics.","Their politics are clear from the bumper stickers on their cars.","We''re trying to talk about comic books, don''t mention politics."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('acute','adj.严重的；急性的；灵敏的，敏锐的；精明的','/əˈkjuːt/','/əˈkjut/','noun',["The word ‘cafe’ often has an acute over the ‘e’.","He acutes his rising inflection too much.","It was an acute event."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('limitation','n.限制，限度；局限','/lɪmɪˈteɪʃən/','/lɪmɪˈteɪʃən/','noun',["Getting into his wheelchair after his amputation, it felt like a limitation you could roll in.","The lawyer obtained impunity by dragging his obviously guilty client''s case beyond the ten-year limitation."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sponsor','n.发起者vt.发起；资助，赞助；支持','/ˈspɒn.sə/','/ˈspɒn.sə/','noun',["He was my sponsor when I applied to join the club.","And now a word from our sponsor."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('kindergarten','n.幼儿园','/ˈkɪndəɹˌɡɑːɹd(ə)n/','/ˈkɪndəɹˌɡɑːɹd(ə)n/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unexpected','adj.想不到的，意外的','/ʌnɪkˈspɛktɪd/','/ʌnɪkˈspɛktɪd/','adjective',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crucial','adj.至关重要的，决定性的','/ˈkɹuː.ʃəl/','/ˈkɹuː.ʃəl/','adjective',["A secure supply of crude oil is crucial for any modern nation, let alone a superpower.","Delbert Wilkins is the most crucial pirate radio DJ in Brixton."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('contribute','v.捐献，捐款；投稿','/kənˈt(ʃ)ɹɪb.juːt/','/kənˈt(ʃ)ɹɪb.jut/','verb',["to contribute articles to a journal"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('faith','n.信任；信心；信仰，信条；忠诚','/feɪθ/','/feɪθ/','noun',["I have faith in the goodness of my fellow man.","I have faith in the healing power of crystals.","The Christian faith."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('generator','n.发电机；发生器','','','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('insert','vt.插入，嵌入；登载','/ɪnˈsɜːt/','/ɪnˈsɜːt/','noun',["This software can print compact disc inserts if you have the right size of paper.","a threaded insert","In order to withdraw money from a cash machine, you have to insert your debit card."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('remark','vt.说；评论说n.话语；谈论，评论','/ɹɪˈmɑːk/','/ɹɪˈmɑɹk/','noun',["a biting remark","He remarked that it was getting late."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('forbid','vt.禁止，不许，阻止','/fəˈbɪd/','/fɚˈbɪd/','verb',["Smoking in the restaurant is forbidden.","An impassable river forbids the approach of the army.","What part of \"no\" do you forbid to understand?"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('microscope','n.显微镜','/ˈmaɪkɹəˌskəʊp/','/ˈmaɪkɹəˌskəʊp/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('necessarily','adv.必要地；必然','/ˌnɛsəˈsɛɹəli/','/ˌnɛsəˈsɛɹəli/','adverb',["It is not necessarily true that children get their morals from their parents."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('highlight','vt.强调，突出，使显著n.最精彩的部分；最重要的事件','/ˈhaɪ.ˌlaɪt/','/ˈhaɪ.ˌlaɪt/','noun',["Meeting my future wife was the highlight of my trip to Spain."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('candidate','n.候选人；投考者，申请求职者','/ˈkæn.dɪdət/','/ˈkæn.dɪ.deɪt/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('billion','num.十亿','/ˈbɪljən/','/ˈbɪljən/','noun',["There were billions of people at the concert."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('parallel','adj.平行的；类似的；并列的，并联的n.可相比拟的事物；相似处；平行线，平行面；纬线vt.与…平行；与…相似，与…相当，比得上','/ˈpæɹəˌlɛl/','/ˈpæɹəˌlɛl/','noun',["The 31st parallel passes through the center of my town.","Johnson''s parallel between Dryden and Pope","The horizontal lines on my notebook paper are parallel."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reject','vt.拒绝；拒纳，退回n.次品','','','noun',["She even rejected my improved offer.","I''ve been rejected three times this week."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('patient','adj.忍耐的，有耐心的n.病人','/ˈpeɪʃənt/','/ˈpeɪʃənt/','noun',["The subject of a passive verb is usually a patient.","Be patient: your friends will arrive in a few hours.","patient endeavour"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cashier','n.出纳','/kəˈʃɪə/','/kəˈʃɪə/','verb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sheer','adv.垂直地，陡峭地vi.急转向，偏离adj.完全的，十足的；陡峭的，垂直的；极薄的，透明的','/ˈʃɪə/','/ʃɪɹ/','noun',["Use sheers to maximize natural light.","Her light, sheer dress caught everyone’s attention.","I think it is sheer genius to invent such a thing."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('miracle','n.奇迹，令人惊奇的人','/ˈmiɹəkəl/','/ˈmiɹəkəl/','noun',["An example of a miracle associated with Muhammad is the splitting of the moon."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('profit','vi.受益n.益处；利润，收益vt.有益于，有利于','/ˈpɹɒfɪt/','/ˈpɹɑfɪt/','noun',["Reading such an enlightening book on the subject was of much profit to his studies."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('original','adj.最初的；新颖的；原版的n.原件，原作','/əˈɹɪdʒnəl/','/əˈɹɪdʒnəl/','noun',["This manuscript is the original.","You’re a real original.","the original state of mankind;  the original laws of a country;  the original inventor of a process"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wit','n.风趣；妙语；智力，才智，智能','/wɪt/','/wɪt/','noun',["He''s gone completely out of his wits.","Where she has gone to is beyond the wit of man to say.","My father had a quick wit and a steady hand."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('handful','n.一把，少数，一小撮','/ˈhæn(d)fəl/','/ˈhæn(d)fəl/','noun',["Those twins are a real handful to look after."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('assignment','n.任务，指定的作业；分配，指派','','','noun',["This flow chart represents the assignment of tasks in our committee.","We should not condone the assignment of asylum seekers to that of people smugglers.","The assignment the department gave him proved to be quite challenging."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nylon','n.尼龙','/ˈnaɪlɒn/','/ˈnaɪlɒn/','noun',["I tore a hole in my nylons while walking home through the woods."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('yawn','vi.打呵欠n.呵欠','/jɔːn/','/jɔːn/','noun',["The slideshow we sat through was such a yawn. I was glad when it finished.","I could see my students yawning, so I knew the lesson was boring them.","Death yawned before us, and I hit the brakes."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('electric','adj.电的，电动的','/əˈlɛktɹɪk/','/əˈlɛktɹɪk/','noun',["We had to sit in the dark because the electric was cut off."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('terminal','adj.晚期的，不治的；末端的，终点的，极限的n.终点；终端；接线端','/ˈtɚmɪnəl/','/ˈtɚmɪnəl/','noun',["terminal cancer","a student''s terminal fees"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('kingdom','n.王国；领域；界','/ˈkɪŋdəm/','/ˈkɪŋdəm/','noun',["the kingdom of the dead"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('differ','vi.不同，相异；发生分歧','/ˈdɪfə/','/ˈdɪfɚ/','verb',["These shoes only differ from those ones in having slightly longer laces.","The numbers 3 and 21 differ by 18."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('various','adj.各种各样的，不同的','/ˈvɛə.ɹi.əs/','/ˈvæɹ.i.əs/','adjective',["The reasons are various.","a various reading of a Biblical text"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('latter','adj.后者的；后一半的','/ˈlæt̬.əɹ/','/ˈlæt̬.əɹ/','adjective',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('depression','n.抑郁，沮丧；不景气，萧条；洼地，凹陷','/dɪˈpɹɛʃən/','/dəˈpɹɛʃ(ə)n/','noun',["I used to suffer from depression, but now I''m mostly content with my life.","The Great Depression was the worst financial event in US history.","Depression of the lever starts the machine."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reduction','n.减少，缩小；下降，降低','/ɹiˈdɑk.ʃən/','/ɹiˈdɑk.ʃən/','noun',["A 5% reduction in robberies"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('extent','n.广度；范围；程度','/ɪksˈtɛnt/','/ɪksˈtɛnt/','noun',["The extent of his knowledge of the language is a few scattered words."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('equivalent','adj.相等的，等量的n.相等物，等价物','/ɪˈkwɪvələnt/','/ɪˈkwɪvələnt/','noun',["To burn calories, a thirty-minute jog is equivalent to a couple of hamburgers.","A square may be equivalent to a triangle."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gaol','vt.监禁n.监狱','/dʒeɪl/','/dʒeɪl/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conversely','adv.相反','/kənˈvɜːsli/','/kənˈvɜːsli/','adverb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sauce','n.调味汁，作料','/sɔːs/','/sɑs/','noun',["apple sauce; mint sauce","[meat] pie and [tomato] sauce","Maybe you should lay off the sauce."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ban','vt.取缔，查禁；禁止n.禁止，禁令','/bæn/','/bæn/','noun',["Bans is common and ordinary amongst the Feudists, and signifies a proclamation, or any public notice.","France was at such a Pinch..that they call''d their Ban and Arriere Ban, the assembling whereof had been long discussed, and in a manner antiquated.","Bare feet are banned in this establishment."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fascinate','vi.有吸引力，迷人vt.迷住，强烈吸引','/ˈfæsɪneɪt/','/ˈfæsɪneɪt/','verb',["The flickering TV fascinated the cat.","We were fascinated by the potter''s skill.","Her gait fascinates all men."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('suffer','v.遭受，忍受，容许；受痛苦，受损','/ˈsʌfə/','/ˈsʌfɚ/','verb',["Is anyone here afraid of suffering hardship?","At least he didn''t suffer when he died in the car crash.","If you keep partying like this, your school-work will suffer."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('diplomatic','adj.外交的，从事外交的；策略的，有手腕的','/ˌdɪpləˈmætɪk/','/ˌdɪpləˈmætɪk/','noun',["Albania immediately severed diplomatic relations with Zimbabwe.","Thoughtful corrections can be diplomatic as well as instructional.","Whereas a diplomatic edition uses as its base text a single, \"best\" manuscript, to which other textual evidence is collated and organized into an apparatus, a critical text of the LXX/OG [= Septuagint or Old Greek] may be described as a collection of the oldest recoverable texts, carefully restored book by book (or section by section), aiming at achieving the closest approximation to the original translations (from Hebrew or Aramaic) or compositions (in Greek), systematically reconstructed from the widest array of relevant textual data (including controlled conjecture).  The International Organization for Septuagint and Cognate Studies, Critical Editions of Septuagint/Old Greek Texts."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bat','n.蝙蝠；球棒，球拍','/bæt/','/bæt/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('neighbourhood','n.四邻；附近；接近','','','noun',["Our neighborhood was our only reason to exchange hollow greetings.","He lives in my neighborhood.","The fire alarmed the neighborhood."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('draft','n.草稿；汇票；征兵；通风vt.起草；征募','/dɹæft/','/dɹæft/','noun',["She took a deep draft from the bottle of water.","His first drafts were better than most authors'' final products.","He left the country to avoid the draft."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('complex','adj.由许多部分组成的，复合的；复杂的，难懂的','','','noun',["Jim has a real complex about working for a woman boss."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rank','v.给…评定等级；列入，占特定等级n.军衔，职衔；地位，社会阶层；排，行列','/ɹæŋk/','/ɹæŋk/','adjective',["rank nonsense","rank grass","rank land"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('assumption','n.假定，臆断；担任，承担','/əˈsʌmp.ʃən/','/əˈsʌmp.ʃən/','noun',["His assumption of secretarial duties was timely.","Their assumption of his guilt disqualified them from jury duty."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pension','n.养老金，抚恤金vt.发给…养老金','/ˈpɛnʃ(ə)n/','/ˈpɛnʃ(ə)n/','noun',["Many old people depend on their pension to pay the bills.","A pension had somewhat less to offer than a hotel; it was always smaller, and never elegant; it sometimes offered breakfast, and sometimes not (John Irving)."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('giant','adj.巨大的n.巨人，巨物；才智超群的人','/ˈdʒaɪ.ənt/','/ˈdʒaɪ.ənt/','noun',["The retail giant is set to acquire two more struggling high-street chains."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fluid','adj.流动的n.流体，液体','/ˈfluːɪd/','/ˈfluːɪd/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bay','n.湾；分隔间','/beɪ/','/beɪ/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('outlet','n.出口，出路；发泄途径','/ˈaʊtlɛt/','/ˈaʊtlɛt/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('neglect','v.疏于照料；疏忽n.疏忽','/nɪˈɡlɛkt/','/nɪˈɡlɛkt/','noun',["to neglect duty or business;  to neglect to pay debts","to neglect strangers"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('addition','n.加，加法；附加物','/æˈdɪʃən/','/æˈdɪʃən/','noun',["The addition of five more items to the agenda will make the meeting unbearably long."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gang','vi.聚集，结成一伙n.一帮，一伙','/ɡæŋ/','/ɡæŋ/','verb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shrink','v.起皱；收缩；退缩，畏缩','/ˈʃɹɪŋk/','/ˈʃɹɪŋk/','noun',["My shrink said that he was an enabler, bad for me.","The dryer shrank my sweater.","This garment will shrink when wet."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ancestor','n.祖宗，祖先；原型；先驱','/ˈæn.sɛs.tə/','/ˈæn.sɛs.tɚ/','noun',["This fossil animal is regarded as the ancestor of the horse."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('textile','adj.纺织的n.纺织品；纺织业','/ˈtɛks.taɪl/','/ˈtɛks.taɪl/','noun',["A textile beach"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('former','adj.在前的n.前者','/ˈfɔːmə/','/ˈfɔɹmɚ/','adjective',["A former president;  the former East Germany","I drive two vehicles, a Chevy Camaro and an AMC Gremlin. I won the former on a game show."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('panic','v.恐慌，惊慌失措n.恐慌，惊慌，慌乱','/ˈpænɪk/','','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('extend','v.延长，扩大；提供，给予；伸展，达到','/ɛkˈstɛnd/','/ɛkˈstɛnd/','verb',["The desert extended for miles in all directions.","to extend credit to a valued customer","The classes Person and Dog extend the class Animal."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fold','v.折叠，合拢n.褶，折叠的部分','/fəʊld/','/foʊld/','noun',["After two reraises in quick succession, John realised his best option was probably a fold.","If you fold the sheets, they''ll fit more easily in the drawer.","Cardboard doesn''t fold very easily."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('plastic','adj.塑料的；可塑的n.塑料，塑料制品；信用卡','/ˈplæstɪk/','/ˈplæstɪk/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('globe','n.地球，世界；地球仪；球体','/ɡloːb/','/ɡloːb/','noun',["the globe of the eye; the globe of a lamp"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chemical','adj.化学的n.化学制品','/ˈkɛmɪkəl/','/ˈkɛmɪkəl/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('interpretation','n.解释；口译；艺术处理','/ɪntəpɹəˈteɪʃən/','/ɪntəpɹəˈteɪʃən/','noun',["the interpretation of a dream, or of an enigma.","Commentators give various interpretations of the same passage of Scripture."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ax','n.斧子','/æks/','/æks/','noun',["His girlfriend/boss/schoolmaster gave him the axe.","A financial dealer has an axe in a stock that his buyers don''t know about, giving him an advantage in making the most profit.","He got axed in the last round of firings."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('intermediate','adj.中间的；中级的','/ɪntə(ɹ)ˈmidi.ət/','/ɪntə(ɹ)ˈmidi.ət/','noun',["Central banks need to regulate the entities that intermediate monetary transactions."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('folk','n.人们；家属，亲属；大伙儿，各位','/fəʊk/','/foʊk/','noun',["Young folk, old folk, everybody come, / To our little Sunday School and have a lot of fun.","folk psychology; folk linguistics"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('consideration','n.考虑，思考，要考虑的事；体贴，关心','/kənˌsɪdəˈɹeɪʃən/','/kənˌsɪdəˈɹeɪʃən/','noun',["After much consideration, I have decided to stay.","Will you noisy children show some consideration and stop your infernal screaming? I''m trying to study!","Sure I''ll move my car, but only for a consideration."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('competitive','adj.竞争的，比赛的；好竞争的，求胜心切的；有竞争力的','/kəmˈpɛtɪtɪv/','/kəmˈpɛtɪtɪv/','adjective',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('enquiry','n.询问','/ɛnˈkwaɪ.ɹi/','/ɛnˈkwaɪ.ɹi/','noun',["scientific enquiry"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('applause','n.鼓掌，掌声','/əˈplɔːz/','/əˈplɔz/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('frank','adj.坦白的，直率的','/fɹæŋk/','/fɹæŋk/','noun',["May I be frank with you?","The research probes whether treating pre-diabetes with metformin can prevent progression to frank diabetes."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('abuse','vt.滥用；虐待，伤害；辱骂，毁谤n.滥用；虐待，伤害；辱骂，毁谤','/əˈbjuːs/','/əˈbjus/','noun',["All abuse, whether physical, verbal, psychological or sexual, is bad."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prove','v.证实，证明；结果是','/pɹuːv/','/pɹuːv/','verb',["I will prove that my method is more effective than yours.","It proved to be a cold day.","Have an exit strategy should your calculations prove incorrect."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scheme','v.密谋，策划n.计划，方案；阴谋','/skiːm/','/skiːm/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('affect','vt.影响；感动','/əˈfɛkt/','/əˈfɛkt/','verb',["The experience affected me deeply.","He was deeply affected by the tragic ending of the play.","Hepatitis affects the liver."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deaf','adj.聋的；不愿听的','/diːf/','/diːf/','noun',["Those people are deaf to reason.","a deaf nut; deaf corn"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('admire','vt.钦佩，羡慕；赞赏，称赞，夸奖','/ədˈmaɪə/','/ədˈmaɪɹ/','verb',["He had always admired the work ethos and family values of his friend."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('consequently','adv.因此，因而，所以','/ˈkɒnsɪˌkwɛntli/','/ˈkɑːnsəˌkwɛntli/','adverb',["He didn''t wake up early. Consequently, he was late to work."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('virus','n.病毒；病毒性疾病，病毒病','/ˈvaɪɹəs/','/ˈvaɪɹəs/','noun',["He caught a virus and had to stay home from school."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('drain','v.排去，放水n.耗竭；排水沟，排水管','/dɹeɪn/','/dɹeɪn/','noun',["The drain in the kitchen sink is clogged.","That rental property is a drain on our finances.","The clogged sink drained slowly."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('isolate','vt.使隔离，使孤立','','','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sailor','n.水手，海员','/ˈseɪlə/','/ˈseɪlɚ/','noun',["He''s a talented sailor and has spent many years at sea."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('amuse','vt.逗…乐，给…娱乐','/əˈmjuːz/','/əˈmjuːz/','verb',["I watch these movies because they amuse me.","His jokes rarely fail to amuse."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inward','adv.向内adj.里面的；内心的','/ˈɪnwəd/','','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('responsibility','n.责任，责任心；职责，义务','/ɹɪˌspɑnsəˈbɪlɪɾi/','/ɹɪˌspɑnsəˈbɪlɪɾi/','noun',["Responsibility is a heavy burden.","Why didn''t you clean the house? That was your responsibility!"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('enquire','v.询问','/ɪŋˈkwaɪə/','/ɪŋˈkwaɪə/','verb',["He enquired about the availability of rental bicycles in the town."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('civil','adj.公民的；文职的；民用的；民事的，民法的；文明的','/ˈsɪv.əl/','/ˈsɪv.əl/','adjective',["She went into civil service because she wanted to help the people.","It was very civil of him to stop the argument.","a civil case"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('popularity','n.普及，流行；声望','/ˌpɒp.jəˈlæɹ.ɪ.ti/','/ˌpɒp.jəˈlæɹ.ɪ.ti/','noun',["Politicians are rarely known for their popularity."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('subsequent','adj.随后的，后来的','/ˈsʌbsəkwənt/','/ˈsʌbsəkwənt/','adjective',["Growth was dampened by a softening of the global economy in 2001, but picked up in the subsequent years due to strong growth in China."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('indicate','vt.标示，表示，表明','/ˈɪndɪkeɪt/','/ˈɪndɪkeɪt/','verb',["The guard blew his whistle to indicate imminent departure.","Great prostration of strength indicates the use of stimulants."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scarcely','adv.几乎不，简直不；决不；刚刚，才','/ˈskɛəsli/','/ˈskɛɹsli/','adverb',["One could scarcely find any trout in the stream without the stocking program.","One could scarcely expect the man to know how to fly a helicopter."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('panel','n.专门小组；面，板；控制板，仪表盘','/ˈpænəl/','/ˈpænəl/','noun',["Behind the picture was a panel on the wall.","Today’s panel includes John Smith.","The last panel of a comic strip usually contains a punchline."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('outstanding','adj.突出的，杰出的；未解决的；未偿付的','','','verb',["outstanding contracts"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('charge','v.索价；控告；充电，充满；向前冲n.费用；管理；控告，指责；电荷，充电','/t͡ʃɑːd͡ʒ/','/t͡ʃɑɹd͡ʒ/','noun',["There will be a charge of five dollars.","Pickett did not die leading his famous charge.","That''s a slanderous charge of abuse of trust."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sew','v.缝制，缝纫','/səʊ/','/soʊ/','verb',["Balls were first made of grass or leaves held together by strings, and later of pieces of animal skin sewn together and stuffed with feathers or hay.","to sew money into a bag"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('oval','adj.椭圆形的n.椭圆形','/ˈəʊvəl/','/ˈəʊvəl/','noun',["oval conceptions"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('column','n.柱，支柱，圆柱；纵队；栏，专栏','/ˈkɑljəm/','/ˈkɑljəm/','noun',["It was too hard to read the text across the whole page, so I split it into two columns.","Each column inch costs $300 a week; this ad is four columns by three inches, so will run $3600 a week.","His initial foray into print media was as the author of a weekly column in his elementary-school newspaper."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('procedure','n.程序，手续，步骤','/pɹəˈsiːdʒə/','/pɹəˈsidʒɚ/','noun',["Ensure that you follow procedure when accessing customers'' personal information."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sample','n.样品，试样，样本vt.从…抽样；品尝，体验','/sæːm.pəl/','/sæːm.pəl/','noun',["a blood sample"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('integrate','v.成为一体，合并','/ˈɪntəɡɹeɪt/','/ˈɪntəɡɹeɪt/','verb',["They were keen to integrate their new skills into the performance.","The refugees were well integrated into the community."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('survivor','n.生还者；残存物','/sɚˈvaɪvɚ/','/sɚˈvaɪvɚ/','noun',["From this moment on, I choose to live not as a victim, but as a survivor.","She was from a large family and had many friends, so the funeral was crowded with mourning survivors."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('applicant','n.申请人','/ˈæp.lə.kɪnt/','/ˈæp.lə.kɪnt/','noun',["Our job advertisement attracted seven applicants."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tropical','adj.热带的；炎热的','','','noun',["tropical fruit"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('partner','vi.做…的搭档n.伙伴，合伙人，搭档，配偶','/ˈpɐːtnə/','/ˈpɑɹtnɚ/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('plunge','n&v.纵身投入，猛冲；猛跌','/plʌndʒ/','/plʌndʒ/','noun',["A plunge into the sea","to plunge the body into water","to plunge a dagger into the breast;   to plunge a nation into war"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('diagnose','vt.诊断','/daɪəɡˈnəʊz/','/daɪəɡˈnəʊz/','verb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('somewhat','adv.有点儿pron.一点儿','/ˈsʌmwɒt/','/ˈsʌmwʌt/','noun',["The crowd was somewhat larger than expected, perhaps due to the good weather."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('earnest','adj.认真的，诚恳的','/ˈɜːnɪst/','/ˈɝnɪst/','noun',["earnest prayers","earnest attention.","an earnest disposition"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spider','n.蜘蛛','[ˈspʌɪ̯ɾə(ɹ)]','/ˈspaɪ̯dɚ/','noun',["2002, Katharine Gasparini, Cranberry and vanilla ice cream spider, recipe in Cool Food, page 339.","The online dictionary is regularly spidered by search engines."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('interview','n&vt.接见，会见；面谈，面试；采访','/ˈɪntəvjuː/','/ˈɪntɚvjuː/','noun',["The reporter gave the witness an interview.","It was a dreadful interview; I have no hope of getting the job.","He interviewed the witness."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('essential','adj.必要的；本质的n.要素；必需品','/ɪˈsɛn.ʃəl/','/ɪˈsɛn.ʃəl/','noun',["Don’t mind him being grumpy. That’s the essential Fred."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clarify','vt.澄清，阐明','/ˈklæɹɪfaɪ/','/ˈklæɹɪfaɪ/','verb',["Leave the wine for 24 hours and it will clarify."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('furnace','n.炉子，熔炉，鼓风炉','/ˈfɜːnɪs/','/ˈfɝnɪs/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ditch','n.沟，沟渠，渠道','/dɪtʃ/','/dɪtʃ/','noun',["Digging ditches has long been considered one of the most demanding forms of manual labor.","Once the sun came out we ditched our rain-gear and started a campfire.","When the second engine failed, the pilot was forced to ditch; their last location was just south of the Azores."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deck','n.甲板，舱面；层面','/dɛk/','/dɛk/','noun',["to swab the deck","We hit the deck as bullets began to fly.","Wow, did you see her deck that guy who pinched her?"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scare','v.吓，使害怕；受惊吓，感到害怕n.惊恐，恐慌','/skɛə/','/skɛɚ/','noun',["Johnny had a bad scare last night.","a food-poisoning scare"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thunder','vi.打雷，轰隆响；大声喊，吼n.雷，雷声；擂鼓般的响声，轰隆声','/ˈθʌndə/','/ˈθʌndɚ/','noun',["Thunder is preceded by lightning.","Off in the distance, he heard the thunder of hoofbeats, signalling a stampede.","Shortly after I announced my pregnancy, he stole my thunder with his news of landing his dream job."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('observe','vt.注意到，观察；评说；遵守','/əbˈzɝv/','/əbˈzɝv/','verb',["From this vantage point we can observe the behavior of the animals in their natural habitat.","Please observe all posted speed limits.","The senator observed that the bill would be detrimental to his constituents."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('humorous','adj.幽默的，诙谐的','/ˈhjuːməɹəs/','/ˈhjuːməɹəs/','adjective',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('furnish','vt.供应，提供；装备','/ˈfɜːnɪʃ/','/ˈfɝnɪʃ/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bet','vt.打赌；敢说，确信n.打赌；赌金，赌注','/ˈbɛt/','/ˈbɛt/','noun',["Dylan owes Fletcher $30 from an unsuccessful bet.","It’s a safe bet that it will rain tomorrow.","Fancy going for a drink after work?\nYou bet I do!"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('contact','n.接触；联系，交往vt.与…接触，与…取得联系','','','noun',["I haven''t been in contact with her for years.","Touch the contact to ground and read the number again.","The salesperson had a whole binder full of contacts for potential clients."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rare','adj.稀有的，冷僻的；珍奇的；出类拔萃的；稀薄的；煎得嫩的','[ɹɜɹ]','/ɹɛəɹ/','noun',["Black pearls are very rare and therefore very valuable."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('discharge','v.释放，排出；卸货n.释放，放电','','','noun',["to discharge a prisoner","to discharge a cargo","A pipe discharges water."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('exclude','vt.把…排除在外','/ɪksˈkluːd/','/ɪksˈkluːd/','verb',["to exclude young animals from the womb or from eggs","Count from 1 to 30, but exclude the prime numbers."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scary','adj.引起惊慌的','/ˈskɛəɹi/','/ˈskɛəɹi/','adjective',["She was hiding behind her pillow during the scary parts of the film.","Linda changed her hair, and it’s scary how much she looks like her mother."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('criticism','n.批评，批判；评论，评论文章','/ˈkɹɪtɪsɪzəm/','/ˈkɹɪtɪsɪzəm/','noun',["The politician received a lot of public criticism for his controversial stance on the issue."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('utmost','adj.最远的n.极限','/ˈʌt.məʊ̯st/','/ˈʌt.moʊ̯st/','noun',["the utmost limits of the land;  the utmost extent of human knowledge","the utmost assiduity;  the utmost harmony;  the utmost misery or happiness"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('image','n.像；形象；映像；形象的描述','/ˈɪmɪd͡ʒ/','/ˈɪmɪd͡ʒ/','noun',["The Bible forbids the worship of graven images.","Most game console emulators do not come with any ROM images for copyright reasons.","The number 6 is the image of 3 under f that is defined as f(x) = 2x."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('consultancy','n.咨询公司','','','noun',["For a PR campaign like never before, one needs a consultancy of unprecedented scope and power.","I''ve been doing IT consultancy for three years."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ribbon','n.缎带，丝带；色带','/ˈɹɪbən/','/ˈɹɪbən/','noun',["a steel or magnesium ribbon"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('garbage','n.垃圾，废物；废话；无用的资料','/ˈɡɑːbɪd͡ʒ/','/ɡɑ(ɹ)ˈbɑːʒ/','noun',["Garbage is collected on Tuesdays; rubbish on Fridays","The garbage truck collects all residential municipal waste.","He threw the newspaper into the garbage."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('complain','vi.抱怨，诉苦；控告，投诉','/kəmˈpleɪn/','/kəmˈpleɪn/','verb',["Joe was always complaining about the noise made by his neighbours.","They''ve complained about me to the police again.","the complaining bed-springs"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mainland','n.大陆','/ˈmeɪ̪nlənd/','/ˈmeɪ̪nlənd/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('homogeneous','adj.同种类的，同性质的，有相同特征的','/ˌhɒ.mə(ʊ)ˈdʒiː.nɪəs/','/ˌhɒ.mə(ʊ)ˈdʒiː.nɪəs/','adjective',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('anxiety','n.焦虑，忧虑；渴望，热望','/ˌæŋ(ɡ)ˈzaɪ.ə.ti/','/ˌæŋ(ɡ)ˈzaɪ.ə.ti/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('temptation','n.诱惑，引诱','/tɛmpˈteɪʃən/','/tɛmpˈteɪʃən/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adjust','vt.调整，调节，校正','/əˈdʒʌst/','/əˈdʒʌst/','verb',["Morimoto''s recipes are adjusted to suit the American palate.","He adjusted his initial conclusion to reflect the new data.","Most immigrants adjust quickly to a new community.   She waited for her eyes to adjust to the darkness."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('popularize','vt.普及','','','verb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('burst','vi.爆裂，爆炸；挤满；突然打开；突然发作vt.使爆炸；突然打开n.爆炸','/bɜːst/','/bɝst/','noun',["The bursts of the bombs could be heard miles away.","I blew the balloon up too much, and it burst.","I burst the balloon when I blew it up too much."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vigorous','adj.朝气蓬勃的；有力的，用力的','/ˈvɪɡəɹəs/','/ˈvɪɡəɹəs/','adjective',["a vigorous shrub"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('debt','n.债，债务，欠债','/dɛt/','/dɛt/','noun',["I am in your debt."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('refrigerator','n.冰箱，冷藏库','/ɹɪˈfɹɪd͡ʒəˌɹeɪtə/','/ɹəˈfɹɪd͡ʒəˌɹeɪɾɚ/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('necessity','n.必需品；必要性，需要','/nɪˈsɛsəti/','/nɪˈsɛsəti/','noun',["I bought a new table out of necessity. My old one was ruined.","A tent is a necessity if you plan on camping.","doctrine of necessity"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fog','n.雾，烟雾，尘雾','/fɒɡ/','/fɑɡ/','noun',["He did so many drugs, he was still in a fog three months after going through detox.","The mirror fogged every time he showered."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('frame','n.框架，框子，构架vt.给…镶框；陷害，诬告；制定；表达','/fɹeɪm/','/fɹeɪm/','noun',["Now that the frame is complete, we can start on the walls.","His starved flesh hung loosely on his once imposing frame.","The painting was housed in a beautifully carved frame."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lucky','adj.幸运的，侥幸的；吉利的','/ˈlʌki/','/ˈlʌki/','adjective',["The downed pilot is very lucky to be alive.","a lucky cast"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('origin','n.起源，起因；出身，血统','/ˈɒɹ.ə.dʒən/','/ˈɑɹ.ɪ.dʒɪn/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('industrialize','v.工业化','','','verb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clash','vi.发生冲突；不协调；砰地相撞，发出刺耳的撞击声n.冲突；不协调；刺耳的撞击声','/klaʃ/','/klæʃ/','noun',["I heard a clash from the kitchen, and rushed in to find the cat had knocked over some pots and pans.","a clash of beliefs","She was wearing a horrible clash of red and orange."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('compel','vt.强迫，迫使屈服','/kəmˈpɛl/','/kəmˈpɛl/','verb',["Logic compels the wise, while fools feel compelled by emotions."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('capable','adj.有能力的，有才能的','/ˈkeɪpəbl̩/','/ˈkeɪpəbl̩/','adjective',["As everyone knew, he was capable of violence when roused."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('depress','vt.使沮丧；使不景气；削弱，抑制','/dɪˈpɹɛs/','/dɪˈpɹɛs/','verb',["Depress the upper lever to start the machine.","Winter depresses me.","Lower productivity will eventually depress wages."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('parade','v.游行，列队前进；招摇而行n.游行；检阅','/pəˈɹeɪd/','/pəˈɹeɪd/','noun',["The floats and horses in the parade were impressive, but the marching bands were really amazing.","The dinner was a parade of courses, each featuring foods more elaborate than the last.","He was parked on Chester Parade."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('burden','n.重担，精神负担vt.加重压于，烦扰；负担，装载','/ˈbɜːdn/','/ˈbɝdn/','noun',["a ship of a hundred tons burden","A burden of gad steel is 120 pounds.","to burden a nation with taxes"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('precaution','n.预防；防备，警惕','/pɹiːˈkɔːʃən/','/pɹiːˈkɔːʃən/','noun',["his life was saved by precaution","to take precautions against risks of accident"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lemon','n.柠檬；柠檬树；柠檬黄，淡黄色','/ˈlɛmən/','/ˈlɛmən/','noun',["He didn’t realise until he’d paid for it that the car was a lemon.","A thousand quid for that motor? Do me a lemon, I could get it for half that.","You can start the vegetables cooking while you are lemoning the fish."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('personality','n.人格，个性；人物，名人','/-i/','/-i/','noun',["The president has a unique personality.","In his final act, the comedian takes on a child''s personality.","Johnny Carson was a respected television personality."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('plot','v.密谋，计划；绘制…的平面图，在图上标绘…的位置n.故事情节；计划，密谋；小块土地','/plɒt/','/plɑt/','noun',["The assassination of Lincoln was part of a larger plot.","They had plotted a robbery.","They plotted the number of edits per day."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sanction','vt.批准，认可n.批准，认可；约束因素，约束力；国际制裁','/ˈsæŋkʃən/','','noun',["The whalers had been operating in the contested waters off the island with sanction from the Japanese government.","The United States enacted a new round of sanctions against the apartheid regime of South Africa."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rate','vi.被评价；被列入特定级别n.速度，速率；比率；价格，费用；等级vt.评估；给…定级，把…列为；值得，应得','/ɹeɪt/','/ɹeɪt/','noun',["At the height of his powers, he was producing pictures at the rate of four a year.","The car was speeding down here at a hell of a rate.","The rate of production at the factory is skyrocketing."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('alert','adj.警觉的，留神的，注意的vt.使认识到，使意识到n.警戒，戒备；警报','/əˈlɜːt/','/əˈlɝt/','noun',["an airborne alert; ground alert"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('await','vt.等候；期待；将降临到…身上','/əˈwɛɪt/','','noun',["I await your reply to my letter.","Glorious rewards await the good in heaven; eternal suffering awaits mortal sinners in hell."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sin','vi.犯戒律，犯过失n.罪，罪孽','/sɪn/','/sɪn/','noun',["As a Christian, I think this is a sin against God.","No movie is without sin."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('client','n.委托人，当事人，顾客','/ˈklʌɪənt/','/ˈklaɪ.ənt/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prosperity','n.繁荣，兴旺','/pɹɒˈspɛɹ.ɪ.ti/','/pɹɑˈspɛɹ.ɪ.ti/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('divide','v.分，分开；分配，分享；除；产生分歧n.分歧；分界线，分水岭','/dɪˈvaɪd/','','noun',["Stay on your side of the divide, please.","The divide left most of the good land on my share of the property.","There is a great divide between us."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('contrary','adj.相反的n.相反','/ˈkɒntɹəɹi/','/ˈkɑntɹɛɹi/','noun',["contrary winds","What may be \"politically correct\" could be contrary to the teachings of Jesus.","a contrary disposition; a contrary child"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lump','v.结块；将…归并在一起n.块，肿块','/lʌmp/','/lʌmp/','noun',["Stir the gravy until there are no more lumps.","The money arrived all at once as one big lump sum payment.","Do you want one lump or two with your coffee?"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('digital','adj.数字的，数位的','/ˈdɪd͡ʒɪtəɫ/','/ˈdɪd͡ʒɪtəɫ/','noun',["He moved to digital for the first time, using a Sony camera.","digital computer;  digital clock","Digital payment systems are replacing cash transactions."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('brilliant','adj.光辉的；卓越的','/ˈbɹɪljənt/','/ˈbɹɪljənt/','noun',["the brilliant lights along the promenade","butterflies with brilliant blue wings","The actor''s performance in the play was simply brilliant."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('historic','adj.历史上著名的，具有重大历史意义的','/(h)ɪˈstɒɹɪk/','/(h)ɪˈstɔːɹɪk/','noun',["A historic opportunity","The historic tenses include the imperfect, the pluperfect, and the future perfect.","July 4, 1776, is a historic date. A great deal of historical research has been done on the events leading up to that day."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('oven','n.炉，烤箱','/ˈʌ.vn̩/','/ˈʌ.vn̩/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bound','vi.跳跃；弹回，反跃adj.一定的；有义务的vt.跳跃；弹回，反跃；成为…的界限，给…划界n.跳跃；界限，限制','/ˈbaʊnd/','/ˈbaʊnd/','verb',["Just to make the cheese more binding","I wish I knew why the sewing machine binds up after I use it for a while.","These are the ties that bind."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('counter','n.柜台；计数器；筹码','/ˈkaʊntə/','/ˈkaʊntə/','noun',["He''s only 16 months, but is already a good counter – he can count to 100.","He rolled a six on the dice, so moved his counter forward six spaces.","He put his money on the counter, and the shopkeeper put it in the till."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rhythm','n.韵律，节奏','/ˈɹɪ.ð(ə)m/','/ˈɹɪ.ð(ə)m/','noun',["Dance to the rhythm of the music.","Most dances have a rhythm as distinctive as the Iambic verse in poetry","Once you get the rhythm of it, the job will become easy."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stroke','n.中风；一举，一次努力；划桨，划水；击，敲；报时的钟声；笔画，一笔；抚摸vt.抚摸','/stɹəʊk/','/stɹoʊk/','noun',["She gave the cat a stroke.","a stroke on the chin","the stroke of a bird''s wing in flying, or of an oar in rowing"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('breed','v.繁殖；养育，培育；酿成，产生n.品种','/bɹiːd/','/bɹiːd/','noun',["a breed of animal","People who were taught classical Greek and Latin at school are a dying breed.","a pond breeds fish; a northern country breeds stout men"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('management','n.管理；处理；管理部门；管理人员','/ˈmænədʒmənt/','/ˈmænədʒmənt/','noun',["Excellent time management helped her succeed in all facets of her life."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('publish','vt.公布，发表；出版，刊印','/ˈpʌblɪʃ/','/ˈpʌblɪʃ/','verb',["Most of the sketches Faulkner published in 1925 appeared in the Sunday magazine section of the New Orleans Times-Picayune.","No newspaper published the victim''s name.","Grove Press published many avant-garde authors."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('realm','n.界，领域，范围；王国，国度','/ɹɛlm/','/ɹɛlm/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('correspondent','n.通讯员，记者','/ˌkɒɹɪˈspɒndənt/','/ˌkɔɹɪˈspɑndənt/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('avoid','vt.避免，躲开；撤销','/əˈvɔɪd/','/əˈvɔɪd/','verb',["I try to avoid the company of gamblers."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('renew','v.重新开始，继续；更新；恢复；延长有效期','/ɹɪˈnjuː/','','verb',["I''d like to renew these three books.  Did you know that you can renew online?"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bid','n.企图，努力；喊价，出价，投标vt.喊价，投标，出；祝，表示；命令','/bɪd/','/bɪd/','verb',["He bade me come in.","She was bidden to the wedding.","Have you ever bid in an auction?"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prompt','adj.敏捷的，及时的vt.促使，推动；提示n.提示台词，提示','/pɹɒmpt/','/pɹɒmpt/','noun',["I filled in my name where the prompt appeared on the computer screen but my account wasn''t recognized.","I prompted him to get a new job.","If he forgets his words I will prompt him."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('astonish','vt.使惊讶，使吃惊','/əˈstɒnɪʃ/','/əˈstɑnɪʃ/','verb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('comprehensive','adj.广泛的，综合的；理解的','/ˌkɒm.pɹɪˈhɛn.sɪv/','/ˌkɑːm.pɹəˈhɛn.sɪv/','noun',["When there are diametrically opposing views on a big issue that concerns millions of people, doing comprehensive research just makes sense."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tunnel','v.挖，开n.隧道，坑道，地道','/ˈtʌn(ə)l/','/ˈtʌn(ə)l/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('withdraw','v.收回，撤回；撤退','/wɪðˈdɹɔː/','/wɪðˈdɹɔː/','verb',["to withdraw false charges"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('assign','vt.指派，分配，布置；指定','/əˈsaɪn/','/əˈsaɪn/','noun',["to assign a day for trial","to assign counsel for a prisoner","We assign 100 to x."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('elaborate','adj.复杂的；精心制作的v.详述，详细制订','/ɪˈlæbəɹeɪt/','/ɪˈlæbəɹeɪt/','verb',["Could you elaborate on the plot for your novel for me?","After reading a long, elaborate description, I was impressed but no wiser.","I stared for hours at the elaborate pattern in the rug."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('feather','n.羽毛，翎毛','/ˈfɛð.ə(ɹ)/','/ˈfɛð.ɚ/','noun',["The stylist feathered my hair.","After striking the bird, the pilot feathered the left, damaged engine’s propeller."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('corridor','n.走廊，回廊，通路','/ˈkɒɹɪˌdɔː(ɹ)/','/ˈkɔɹəˌdɔɹ/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('decade','n.十年，十年期','/dəˈkeɪd/','/dəˈkeɪd/','noun',["a decade of soldiers","There are decades between 1.8 and 18, between 25 and 250 and between 0.03 and 0.003."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('expert','adj.熟练的n.专家','/ˈɛkspəːt/','/ˈɛkspɚt/','noun',["We called in several experts on the subject, but they couldn''t reach an agreement.","I am expert at making a simple situation complex.","This problem requires expert knowledge."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('select','adj.精选的，挑选出来的；优等的，第一流的vt.选择，挑选','/sɪˈlɛkt/','/sɪˈlɛkt/','verb',["He looked over the menu, and selected the roast beef.","Only a select few were allowed into the premiere.","This is a select cut of beef."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fulfill','vt.履行，实现，完成；满足，使满意','/fəˈfɪl/','/fəˈfɪl/','verb',["You made a promise, son, and now you must fulfill it.","This is the most fulfilling work I''ve ever done.","Unfortunately, you don''t fulfill the criteria for extra grants at the present time."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crowd','v.聚集；挤满；挤；推n.群，一批','/kɹaʊd/','/kɹaʊd/','noun',["After the movie let out, a crowd of people pushed through the exit doors.","There was a crowd of toys pushed beneath the couch where the children were playing.","That obscure author''s fans were a nerdy crowd which hardly ever interacted before the Internet age."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('congress','n.代表大会；[C-]国会，议会','/ˈkɒŋˌɡɹɛs/','/ˈkɑŋɡɹɛs/','noun',["The National Congress of American Indians"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('advanced','adj.先进的；高级的；年迈的；后阶段的','/ədˈvɑːnst/','/ədˈvænst/','verb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mechanical','adj.机械的，机械制造的；机械学的，力学的；呆板的','/mɪˈkanɪk(ə)l/','/mɪˈkanɪk(ə)l/','noun',["mechanical engineering","mechanical dictionary","mechanical task"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('recommendation','n.推荐，推荐信；建议；优点，可取之处','/ˌɹɛkəmənˈdeɪʃən/','/ˌɹɛkəmənˈdeɪʃən/','noun',["Your next employer may require a recommendation.","He made a recommendation about what food to order."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('welfare','n.幸福；福利，福利救济','/ˈwɛlˌfɛə/','/ˈwɛlˌfɛə/','noun',["welfaring the poor"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flourish','vi.繁荣，茂盛，兴旺vt.挥动','/ˈflʌ.ɹɪʃ/','/ˈflʌ.ɹɪʃ/','noun',["With many flourishes of the captured banner, they marched down the avenue.","His signature ended with a flourish.","The trumpets blew a flourish as they entered the church."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('output','n.产量；输出；输出功率vt.输出','/ˈaʊtpʊt/','/ˈaʊtpʊt/','noun',["The factory increased its output this year.","a six-page output; six pages of output","We output 1400 units last year."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fatigue','v.疲劳n.疲劳，劳累','/fəˈtiːɡ/','','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('striking','adj.显著的，突出的；惹人注目的，容貌出众的','/ˈstɹaɪkɪŋ/','/ˈstɹaɪkɪŋ/','verb',["Please strike the last sentence.","A tree strikes its roots deep.","They struck off along the river."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vessel','n.容器；船；飞船；管','/ˈvɛs.l̩/','/ˈvɛs.l̩/','noun',["Blood and lymph vessels are found in humans; xylem and phloem vessels are found in plants."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('majority','n.多数，大多数','/məˈd͡ʒɒɹɪti/','/məˈd͡ʒɑɹɪti/','noun',["The majority agreed that the new proposal was the best.","The winner with 53% had a 6% majority over the loser with 47%.","By the time I reached my majority, I had already been around the world twice."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('drag','v.拖，拉；迫使，硬拉；拖着脚步走n.累赘；一吸，一抽','/dɹæɡ/','','noun',["When designing cars, manufacturers have to take drag into consideration.","Travelling to work in the rush hour is a real drag.","to run a drag"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crown','n.王冠，冕','/kɹaʊn/','/kɹaʊn/','noun',["the martyr''s crown","Treasure recovered from shipwrecks automatically becomes property of the Crown.","The mother was in the second stage of labor and the fetus had just crowned, prompting a round of encouragement from the midwives."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('likely','adv.可能adj.可能的；适合的','/ˈlaɪkli/','/ˈlaɪkli/','noun',["Rain is likely later this afternoon.","He is likely to succeed at anything he tries.","Jones is a likely candidate for management."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inquire','v.打听，询问；调查','/ɪnˈkwaɪə/','/ɪnˈkwaɪɹ/','verb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gymnasium','n.体育馆，健身房','/dʒɪmˈneɪ.zi.əm/','/dʒɪmˈneɪ.zi.əm/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('issue','v.发行，分发，发出n.问题；发行，分发','/ˈɪsjuː/','/ˈɪʃ(j)u/','noun',["The issue of the directive from the treasury prompted the central bank''s most recent issue of currency.","Please stand by. We are having technical issues.","The rents issuing from the land permitted him to live as a man of independent means."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vain','adj.徒劳的；自负的','/veɪn/','/veɪn/','adjective',["vain toil;  a vain attempt"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lower','adj.较低的；下面的vt.放下，降低','/ˈləʊə/','/ˈloʊɚ/','adjective',["a low wall  a low shelf","a low bow","Now that was low even for you!"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('index','n.索引；指数，指标','/ˈɪndɛks/','/ˈɪndɛks/','noun',["The index of a book lists words or expressions and the pages of the book upon which they are to be found."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fry','vt.油煎，油炸，油炒','/fɹaɪ/','/fɹaɪ/','noun',["to be in a fry"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('youngster','n.青年，年轻人，孩子','/ˈjʌŋstə/','/ˈjʌŋstə/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('odd','adj.奇特的；临时的；奇数的；单只的；剩余的，挂零的','/ɒd/','/ɑd/','noun',["So let''s see. There are two evens here and three odds.","She slept in, which was very odd.","My cat Fluffy has odd eyes: one blue and one brown."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lung','n.肺','/ˈlʌŋ/','/ˈlʌŋ/','noun',["He hasn''t the lungs to play long rallies like he use to."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conservation','n.保存；保护；守恒','/ˌkɑnsə(ɹ)ˈveɪʃən/','/ˌkɑnsə(ɹ)ˈveɪʃən/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('distraction','n.分心的事；心烦意乱；精神错乱；娱乐，消遣','/dɪsˈtɹækʃən/','/dɪsˈtɹækʃən/','noun',["Poking one''s eye is a good distraction from a hurting toe.","We have to reduce distraction in class if we want students to achieve good results.","The incessant nightmares drove him to distraction."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('supplement','n.增补，补充；增刊，副刊vt.增补，补充','/ˈsʌpləmənt/','/ˈsʌpləmənt/','noun',["There is a £2 supplement if you choose the steak."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('contrast','vi.形成对比，对比之下显出区别n.对比，对照；反差vt.对比，对照','/ˈkɒntɹɑːst/','/ˈkɒntɹɑːst/','noun',["Israel is a country of many contrasts.","Foreground and background strongly contrast."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('paragraph','n.段，节','/ˈpæɹəɡɹɑːf/','/ˈpɛɹəɡɹæf/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('judgement','n.意见；审判；判断','/dʒʌdʒmənt/','/dʒʌdʒmənt/','noun',["a man of judgment"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('proportion','n.比例；部分，份儿；均衡，相称','/pɹəˈpɔːʃən/','/pɹəˈpɔɹʃən/','noun',["the proportion of the parts of a building, or of the body"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('widen','v.加宽，变宽','/ˈwaɪdən/','/ˈwaɪdən/','verb',["His eyes widened as her negligee fell to the floor.","She widened his trousers for him.","The police widened their enquiries."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crystal','n.水晶，结晶体，晶粒','/ˈkɹɪstəl/','/ˈkɹɪstəl/','noun',["\"Do I make myself clear?\" / \"Crystal.\""]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('occurrence','n.发生，出现；发生的事件','/əˈkɐɹən(t)s/','/əˈkɐɹən(t)s/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inflation','n.通货膨胀；膨胀','/ɪnˈfleɪʃən/','/ɪnˈfleɪʃən/','noun',["The inflation of the balloon took five hours."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thinking','adj.深思的，有理性的n.想法，意见，见解','/ˈθɪŋkɪŋ/','/ˈθɪŋkɪŋ/','noun',["What is your thinking on this subject?"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cycle','n.循环（周期）v.骑自行车','/ˈsaɪkəl/','/ˈsaɪkəl/','noun',["the cycle of the seasons, or of the year","electoral cycle","The interval cycle C4 consists of the pitch classes 0, 4 and 8; when starting on E, it is realised as the pitches E, G# and C."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disposal','n.丢掉，销毁；处理；排列，布置','[dɪsˈpəʊzəɫ]','[dɪsˈpəʊzəɫ]','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('settlement','n.解决；协议；居留地','/ˈset.l.mənt/','/ˈset.l.mənt/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('delegate','n.代表，代表团成员vt.委派…为代表；授，把…委托给','','','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('literature','n.文学，文学作品；文献，图书资料','/ˈlɪ.tə.ɹɪ.tʃə(ɹ)/','/ˈlɪ.tə.ɹɪ.tʃə(ɹ)/','noun',["However, even “literary” science fiction rarely qualifies as literature, because it treats characters as sets of traits rather than as fully realized human beings with unique life stories. —Adam Cadre, 2008"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sphere','n.球，球体；范围','/sfɪə/','/sfɪɹ/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inquiry','n.询问，打听；调查','/ɪnˈkwaɪəɹi/','/ɪnˈkwaɪ(ə)ɹi/','noun',["Scientific inquiry"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prejudice','n.偏见，成见vt.使有偏见；对…不利，损害','/ˈpɹɛd͡ʒədɪs/','/ˈpɹɛd͡ʒədɪs/','noun',["I am free of all prejudices. I hate everyone equally."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dissolve','v.溶解；解散；消失，减弱；结束','/dɪˈzɒlv/','/dɪˈzɒlv/','noun',["The ruling party or coalition sometimes dissolves parliament early when the polls are favorable, hoping to reconvene with a larger majority.","to dissolve an injunction"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('digest','vt.消化；领会n.文摘；摘要','/daɪˈdʒɛst/','/daɪˈdʒɛst/','verb',["to digest laws","I just ate an omelette and I''m waiting for it to digest."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('angle','n.角，角度；观点，立场','/ˈæŋ.ɡəl/','/ˈæŋ.ɡəl/','noun',["the angle between lines A and B","The angle between lines A and B is π/4 radians, or 45 degrees.","an angle of a building"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('immigrant','n.移民，侨民','/ˈɪmɪɡɹənt/','/ˈɪmɪɡɹənt/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tradition','n.传统，惯例','/tɹəˈdɪʃn̩/','/tɹəˈdɪʃn̩/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ability','n.能力，本领；才能，才智','/əˈ.bɪl.ɪ.ti/','/əˈ.bɪl.ɪ.ti/','noun',["This phone has the ability to have its software upgraded wirelessly.","She has an uncanny ability to defuse conflict."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('urgent','adj.紧急的，急迫的','/ˈɜːdʒənt/','/ˈɚdʒənt/','adjective',["An urgent appeal was sent out for assistance."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('belief','n.信任，相信；信念','/bəˈliːf/','/bəˈliːf/','noun',["It''s my belief that the thief is somebody known to us.","Based on this data, it is our belief that X does not occur.","The ancient people have a belief in many deities."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bundle','n.捆，包，束；包袱vt.收集，归拢；把…塞入','/ˈbʌnd(ə)l/','/ˈbʌnd(ə)l/','noun',["a bundle of straw or of paper; a bundle of old clothes","This software bundle includes a wordprocessor, a spreadsheet, and two games.","The inventor of that gizmo must have made a bundle."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('suggestion','n.建议，意见；细微的迹象；暗示','/səˈd͡ʒɛstjən/','/səɡˈd͡ʒɛstʃən/','noun',["I have a small suggestion for fixing this: try lifting the left side up a bit.","Suggestion often works better than explicit demand.","He''s somehow picked up the suggestion that I like peanuts."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('systematic','adj.有系统的，有计划的','/ˌsɪs.təˈmæt.ɪk/','/ˌsɪs.təˈmæt.ɪk/','adjective',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cupboard','n.柜橱；碗碟橱，食橱','/ˈkʌbəd/','/ˈkʌbɚd/','noun',["Put the cups back into the cupboard."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('generally','adv.一般地，通常地；普遍地','/d͡ʒɛn.əɹ.ə.li/','/d͡ʒɛn.əɹ.ə.li/','adverb',["It is generally known that the Earth is round.","I generally have a walk in the afternoon.","Generally speaking …"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bacon','n.咸肉','/ˈbeɪ.kən/','/ˈbeɪ.kən/','noun',["Run! It''s the bacon!"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('likewise','adv.同样地；也，又','/ˈlaɪkˌwaɪz/','/ˈlaɪkˌwaɪz/','adverb',["Public transportation is virtually inaccessible in this country; likewise, its hospitals are also not very user-friendly.","Margaret enjoys playing tennis on Saturdays, Jeremy likewise.","It was very nice meeting you, Samantha. ― Likewise, Mr Thompson."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('slender','adj.细长的，苗条的；微薄的，不足的','/ˈslɛndə/','/ˈslɛndɚ/','adjective',["A rod is a long slender pole used for angling.","Being a person of slender means, he was unable to afford any luxuries."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('troublesome','adj.令人烦恼的，麻烦的','/ˈtɹʌbl̩səm/','/ˈtɹʌbl̩səm/','adjective',["The computer has been very troublesome for me. It never works when I need to use it."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('instruction','n.命令，指示；用法说明；教学，教导','/ɪnˈstɹʌkʃən/','/ɪnˈstɹʌkʃən/','noun',["Instruction will be provided on how to handle difficult customers."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('oral','adj.口头的；口的','/ˈɒɹəl/','/ˈɒɹəl/','noun',["We''ve got our Spanish oral tomorrow.","I gave my boyfriend oral for the first time on his birthday.","oral hygiene"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('married','adj.已婚的；婚姻的','/ˈmæɹ.ɪd/','/ˈmæɹ.id/','noun',["married to one''s work.","Neither of her daughters showed any desire to marry.","His daughter was married some five years ago to a tailor''s apprentice."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('transaction','n.办理，处理；交易，业务；会报，学报','/tɹænˈzækʃən/','/tɹænˈzækʃən/','noun',["The transaction was made on Friday with the supplier.","I made the transaction with the vendor as soon as she showed me the pearls."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conscious','adj.意识到的，自觉的；神志清醒的；有意的，存心的','/ˈkɒn.ʃəs/','/ˈkɑn.ʃəs/','noun',["The noise woke me, but it was another few minutes before I was fully conscious.","Only highly intelligent beings can be fully conscious.","I was conscious of a noise behind me.   a very class-conscious analysis"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fur','n.软毛，毛皮，裘皮；毛皮衣服','/fɜː(ɹ)/','/fɝ/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('auto','n.汽车','/ˈɑtoʊ/','/ˈɑtoʊ/','noun',["My brother is an auto mechanic.","Put it on auto.","A body coloured centre pillar signalled the arrival of an electronic four-speed auto, slight suspension revisions and minor trim changes."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sigh','vi.叹气，叹息n.叹息','/saɪ/','/saɪ/','noun',["He sighed over the lost opportunity.","He silently sighed for his lost youth.","She sighed a sigh that was nearly a groan."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('constant','adj.经常的，不断的，连续发生的；永恒的；忠实的，忠诚的n.常数，恒量','/ˈkɒnstənt/','/ˈkɑnstənt/','noun',["constant time   constant space"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pants','n.长裤，便裤；内裤','/pænts/','/pænts/','noun',["The film was a load [or pile] of pants.","Your mobile is pants — why don’t you get one like mine?"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mislead','vt.给…错误印象，使误解；把…带错路；使误入歧途','/mɪsˈliːd/','/mɪsˈliːd/','verb',["The preacher elaborated Satan''s ways to mislead us into sin"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('split','v.分裂，分离；被撕裂，裂开；分担，分享n.裂口','/splɪt/','/splɪt/','noun',["He’s got a nasty split.","In the 3000 m race, his 800 m split was 1:45.32","He has split his lip."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('orchestra','n.管弦乐队','/ˈɔːkəstɹə/','/ˈɔɹkəstɹə/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('publication','n.出版，发行；公布，发表','/ˌpʌblɪˈkeɪʃən/','/ˌpʌblɪˈkeɪʃən/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sufficient','adj.足够的，充分的','/səˈfɪʃənt/','/səˈfɪʃənt/','adjective',["There is not sufficient access to the internet in many small rural villages.","A two-week training course is sufficient to get a job in the coach-driving profession."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('claim','vt.声称，主张；对…提出要求，索取；以…为其成果；需要，值得n.要求，认领，索赔；声称；断言','/kleɪm/','/kleɪm/','noun',["a claim of ownership","You don''t have any claim on my time, since I''m no longer your employee.","The company''s share price dropped amid claims of accounting fraud."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('antique','adj.古时的，过时的n.古物，古董','/ænˈtiːk/','/ænˈtiːk/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sow','v.播，播种','/saʊ/','/saʊ/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('widespread','adj.分布广的，普遍的','','','adjective',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('petroleum','n.石油','/pəˈtɹoʊliəm/','/pəˈtɹoʊliəm/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('communication','n.通讯，交流，交际；通信工具，交通联系','/kəˌmjuːnɪˈkeɪʃən/','/kəˌmjuːnɪˈkeɪʃən/','noun',["communication of a secret","Some say that communication is a necessary prerequisite for sentience; others say that it is a result thereof.","Surveillance was accomplished by means of intercepting the spies'' communications."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('directly','adv.直接地；正好地，截然；立即','/daɪˈɹɛk(t)li/','/daɪˈɹɛk(t)li/','adverb',["He drove directly to the office, and didn''t stop off at the petrol station.","I''m sick of asking you to fire him, I''ll just do it directly.","I''m going to tell Natalie directly that I love her."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tolerance','n.忍受，容忍，忍耐力；公差','/ˈtɒləɹəns/','','noun',["Our customers can generally accept ten times the tolerance which we can achieve in our machining operations."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('kneel','vi.跪，跪下，跪着','/niːl/','/niːl/','verb',["She knelt the doll to fit it into the box.","He knelt him down to pray."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('porter','n.搬运工人；看门人，大楼管理员','/ˈpɔːtə/','/ˈpɔːtə/','noun',["By the time I reached the train station I was exhausted, but fortunately there was a porter waiting."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fasten','v.扎牢，扣住','/ˈfɑːsn̩/','/ˈfæsn̩/','verb',["Can you fasten these boards together with some nails?","to fasten a blow"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('contest','n.竞赛，争夺vt.争夺，与…竞争；对…提出质疑，辩驳','/ˈkɒn.tɛst/','/ˈkɑn.tɛst/','noun',["no contest","The child entered the spelling contest.","I will contest for the open seat on the board."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('author','n.著作家，作者','/ˈɔː.θə/','/ˈɔ.θɚ/','noun',["Have you read any Corinthian authors?"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dirt','n.灰尘，土；污物，污垢','/dɜːt/','/dɝt/','noun',["The reporter uncovered the dirt on the businessman by going undercover."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('astrophysics','n.天体物理学','','','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('greenhouse','n.温室，暖房','/ˈɡɹiːnˌhaʊs/','/ˈɡɹiːnˌhaʊs/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('preserve','vt.保护，维持；保存；腌制','/pɹəˈzɜːv/','/pɹəˈzɝv/','noun',["Every people have the right to preserve its identity and culture.","to preserve peaches or grapes","to preserve appearances; to preserve silence"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('plus','adj.表示加的；正的prep.加，加上n.加号，正号','/plʌs/','/plʌs/','noun',["He is a real plus to the team.","−2 * −2 = +4 (\"minus 2 times minus 2 equals plus four\")","He is a plus factor."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('establish','vt.建立，设立；确立；证实','/ɪˈstæb.lɪʃ/','/ɪˈstæb.lɪʃ/','verb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('expansion','n.扩大，扩充，扩张，膨胀','/ɪkˈspænʃən/','/ɪkˈspænʃən/','noun',["The expansion of metals and plastics in response to heat is well understood.","My new office is in the expansion behind the main building.","This expansion requires the original game board."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('relevant','adj.有关的，切题的','/ˈɹɛləvənt/','/ˈɹɛləvənt/','adjective',["His mother provided some relevant background information concerning his medical condition."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('entry','n.入口处；登记；进入；参赛者名单；条目','/ˈɛntɹi/','/ˈɛntɹi/','noun',["Children are allowed entry only if accompanied by an adult.","What does the entry for 2 August 2005 say?","The entry in the second row and first column of this matrix is 6."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('license','n.许可，执照vt.准许','/ˈlaɪsəns/','/ˈlaɪsəns/','noun',["In order to enter the building, I need to show my license.","It was decided to license Wikipedia under the GFDL.","I am licensed to practice law in this state."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('synthetic','adj.综合的，合成的；虚假的','/sɪnˈθɛtɪk/','/sɪnˈθɛtɪk/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('headquarters','n.司令部，总部','/ˌhɛd.ˈkwɔː.təz/','/ˌhɛd.ˈkwɔː.təz/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('expand','vt.扩大，使膨胀','/ɛkˈspænd/','/ɛkˈspænd/','verb',["You can expand this compact umbrella to cover a large table.","A flower expands its leaves.","Use the binomial theorem to expand {(x+1)}^4."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gaze','n&vi.凝视，盯，注视','/ɡeɪz/','/ɡeɪz/','noun',["In fact, for Antonioni this gazing is probably the most fundamental of all cognitive activities ... (from Thinking in the Absence of Image)"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('essay','n.短文，散文，小品文','/ˈɛˌseɪ/','/ˈɛˌseɪ/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('survey','vt.俯瞰；检查；测量n.调查，勘察；测量，勘测；全面审视，概括论述','','','noun',["A survey of the stores of a ship; a survey of roads and bridges; a survey of buildings.","The owners of the adjoining plots had conflicting surveys.","The local council conducted a survey of its residents to help it decide whether to go ahead with the roadside waste collection service."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('plug','n.插头，插座；塞子，栓vt.把…塞住，用…塞住','/plʌɡ/','/plʌɡ/','noun',["I pushed the plug back into the electrical socket and the lamp began to glow again.","Pull the plug out of the tub so it can drain.","He preferred a plug of tobacco to loose chaw."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bunch','vi.集中，挤在一起；形成一束n.群，伙；束，串，捆vt.使成一束','/ˈbʌntʃ/','/ˈbʌntʃ/','noun',["a bunch of grapes;  a bunch of bananas;  a bunch of keys;  a bunch of yobs on a street corner","He still hangs out with the same bunch.","a bunch of trouble"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thermometer','n.温度计，寒暑表','/θəˈmɒmɪtə/','/θɚˈmɑmɪtɚ/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tense','adj.拉紧的；紧张的v.拉紧，绷紧n.时态','/tɛns/','/tɛns/','noun',["English only has a present tense and a past tense; it has no future tense.","Dyirbal verbs are not inflected for tense.","tensing a verb"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('postpone','vt.延迟，延期','/poʊstˈpoʊn/','/poʊstˈpoʊn/','verb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bride','n.新娘','/bɹaɪd/','/bɹaɪd/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('favourable','adj.有利的，赞成的；顺利的','/ˈfeɪv(ə)ɹəbəl/','/ˈfeɪv(ə)ɹəbəl/','adjective',["The candidate wearing the business suite made a favourable impression.","We made quick progress, due to favourable winds.","The rain stopped at a favourable time for our tennis match."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hammer','v.锤击n.锤，榔头','/ˈhæm.ə(ɹ)/','/ˈhæmɚ/','noun',["Bobby used a hammer and nails to fix the two planks together","The nail is too loose - give it a hammer.","The sound the piano makes comes from the hammers striking the strings"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('candy','n.糖果','/ˈkændi/','/ˈkændi/','noun',["Fruits preserved in sugar candy after a time."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('seal','n.封铅，封条；印，图章；海豹vt.封','/siːl/','/siːl/','noun',["The seals in the harbor looked better than they smelled.","They''re organizing a protest against sealing."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mental','adj.心理的，精神的，思想上的；精神病的；智力的','/ˈmɛntəl/','/ˈmɛntəl/','adjective',["He is the most mental freshman I''ve seen yet.","That was a mental party last night."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('decent','adj.像样的，过得去的，体面的；宽厚的，大方的；正派的；合乎礼仪的，得体的','/ˈdiːsənt/','','adjective',["Are you decent? May I come in?","He''s a decent saxophonist, but probably not good enough to make a career of it.","There are a decent number of references out there, if you can find them."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('storage','n.贮藏；贮藏量','/ˈstɔ.ɹɪd͡ʒ/','/ˈstɔ.ɹɪd͡ʒ/','noun',["There''s a lot of storage space in the loft.","I′d recommend backing up these files to storage before reinstalling the operating system."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('investigate','v.调查，研究','[ɪn.ˈves.tɪ.ɡeɪ̯t]','[ɪn.ˈves.tɪ.ɡeɪ̯t]','verb',["to investigate the causes of natural phenomena","to investigate an unsolved murder"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('racial','adj.种族的，人种的','/ˈɹeɪʃəl/','/ˈɹeɪʃəl/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('switch','v.转换，改变n.开关，电闸；转换，改变','/swɪtʃ/','/swɪtʃ/','noun',["Use the /b switch to specify black-and-white printing.","2004, \"Curt\", Can I use IF statements, and still use switches? (on newsgroup microsoft.public.word.mailmerge.fields)","I want to switch this red dress for a green one."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('niece','n.侄女，外甥女','/niːs/','/nis/','noun',["My niece just celebrated her 15th birthday."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('considerable','adj.相当大的；重要的','/kənˈsɪdəɹəbl̩/','/kənˈsɪdəɹəbl̩/','noun',["I''ve spent a considerable amount of time on this."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('auxiliary','adj.辅助的，附属的；后备的','/ɔːkˈsɪli.əɹi/','/ɔːkˈsɪli.əɹi/','noun',["auxiliary troops"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('heal','vi.愈合，痊愈，恢复健康vt.使愈合，治愈，使康复；调停，消除','/hiːl/','/hiːl/','noun',["This bandage will heal your cut.","Bandages allow cuts to heal.","to heal dissensions"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reserve','vt.保留，留存；预订n.储备；保留；拘谨，矜持；替补队员，后备部队；自然保护区','/ɹɪˈzɜːv/','/ɹɪˈzɝv/','noun',["We reserve the right to make modifications.","This cake is reserved for the guests!","I reserved a table for us at the best restaurant in town."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('somehow','adv.由于某种原因，不知怎么的；以某种方式','/ˈsʌmhaʊ/','/ˈsʌmhaʊ/','adverb',["This problem has to be tackled somehow."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dive','vi.跳水；潜水；俯冲','/ˈdaɪv/','/ˈdaɪv/','noun',["the dive of a hawk after prey","to dive into home plate","She dove right in and started making improvements."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('brick','n.砖，砖块，砖状物','/bɹɪk/','/bɹɪk/','noun',["This wall is made of bricks.","This house is made of brick.","a plastic explosive brick"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sympathy','n.同情；一致，支持，赞同','/ˈsɪmpəθi/','/ˈsɪmpəθi/','noun',["Many people in Hollywood were blacklisted merely because they were suspected of Communist sympathies."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('heap','n.堆，大量','/heːp/','/hiːp/','noun',["a heap of earth or stones","You should move these structures from the stack to the heap to avoid a potential stack overflow.","My first car was an old heap."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('consumer','n.消费者，用户，消耗者','/kənˈsjuːmə/','/kənˈsjuːmə/','noun',["This new system favours the consumer over the producer.","Our consumers are upwardly mobile and middle-class."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rescue','n&vt.营救，救援','/ˈɹɛs.kjuː/','/ˈɹɛs.kjuː/','noun',["The rescue of Jerusalem was the original motive of the Crusaders","The dog was a rescue with some behavior issues.","The well-trained team rescued everyone after the avalanche."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cripple','n.跛子；残疾人vt.使跛；使残疾','/ˈkɹɪpl/','/ˈkɹɪpl/','noun',["He returned from war a cripple.","The car bomb crippled five passers-by.","My ambitions were crippled by a lack of money."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('highly','adv.高度地，极，非常赞许地','/ˈhaɪli/','/ˈhaɪli/','adverb',["He spoke highly of you.","He is in a highly visible job."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('brief','adj.简短的，短暂的vt.向…介绍基本情况，做…的提要n.概要，摘要','/bɹiːf/','/bɹiːf/','noun',["We got a news brief.","I wear boxers under trousers but for sports I usually wear a brief.","The U.S. president was briefed on the military coup and its implications on African stability."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('keyboard','n.键盘','/ˈkiːbɔːd/','/ˈkibɔɹd/','noun',["Keyboarding is the part of this job I hate the most."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('initiative','n.主动性；首创精神；主动的行动，倡议；主动权','/ɪˈnɪʃətɪv/','/ɪˈnɪʃətɪv/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('recover','v.重新获得，挽回；恢复','/ɹɪˈkʌvə/','/ɹɪˈkʌvɚ/','noun',["After days of inquiries, he finally recovered his lost wallet.","They recovered three of the explorers very much alive, then another, wracked with severe hypothermia, who was taken to hospital.","At the top of the hill I asked to stop for a few minutes to recover my strength."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('determine','vi.决意vt.决定；查明；使下决心','/dɪˈtɜːmɪn/','/dɪˈtɝmɪn/','verb',["The news of his father''s illness determined him to depart immediately.","The court has determined the cause.","I determined to go home at once."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nature','n.大自然；本性；性质','/ˈneɪtʃə/','/ˈneɪtʃɚ/','noun',["Nature never lies (i.e. tells untruths)."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('social','adj.社会的；交际的，社交的','/ˈsəʊʃəl/','/ˈsoʊ.ʃəl/','noun',["They organized a social at the dance club to get people to know each other.","James is a very social guy; he knows lots of people.","Teresa feels uncomfortable in certain social situations."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('medication','n.药物治疗；药物','/mɛdɪˈkeɪʃən/','/mɛdɪˈkeɪʃən/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('drill','v.钻，打；训练n.钻头；操练，训练','/dɹɪl/','/dɹɪl/','noun',["Wear safety glasses when operating an electric drill.","Use a drill with a wire brush to remove any rust or buildup.","Regular fire drills can ensure that everyone knows how to exit safely in an emergency."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('intelligent','adj.聪明的，理智的','/ɪnˈtɛlɪd͡ʒənt/','/ɪnˈtɛlɪd͡ʒənt/','adjective',["The engineer had a very intelligent design proposal for the new car.","My girlfriend and I had an intelligent conversation.","The hunt for intelligent life."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('whilst','conj.当…的时候','/hwaɪlst/','/hwaɪlst/','conjunction',["Drivers must switch off engines whilst on stand."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clerk','n.店员，办事员，职员','/klɐːk/','/klɝk/','noun',["The law school graduate clerked for the supreme court judge for the summer."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lobby','v.向进行游说n.大厅；休息室；院外活动集团','/lɒbi/','/lɒbi/','noun',["I had to wait in the lobby for hours before seeing the doctor.","The influence of the tobacco lobby has decreased considerably in the US.","For years, pro-life groups have continued to lobby hard for restrictions on abortion."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('acknowledge','vt.承认，承认…的权威；告知收到，确认；对…表示感谢，报偿','/əkˈnɒ.lɪdʒ/','/ækˈnɑː.lɪdʒ/','verb',["to acknowledge the being of a god","to acknowledge a favor","This is to acknowledge your kind invitation to participate in the upcoming debate."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('equip','vt.装备，配备；使有准备','/ɪˈkwɪp/','/ɪˈkwɪp/','verb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('radiation','n.放射物，辐射能；辐射','/ɹaɪ.di.ˈaɪ.ʃən/','/ɹaɪ.di.ˈaɪ.ʃən/','noun',["heat radiation"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Christian','adj.基督教的n.基督教徒，信徒','','','',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pulse','vi.搏动，跳动n.脉搏；脉冲','/pʊls/','/pʌls/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('luxury','n.奢侈；奢侈品','/ˈlʌk.ʃə.ɹi/','/ˈlʌkʃəɹi/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spiritual','adj.精神的，心灵的；宗教的','/ˈspɪɹɪtjʊəl/','/ˈspɪɹɪtʃuəl/','noun',["He assigns supremacy to the pope in spirituals, and to the emperor in temporals. — Lowell.","Respect towards ancestors is an essential part of Thai spiritual practice.","a spiritual substance or being"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('worthwhile','adj.值得花时间的，值得做的','/wɜː(ɹ)θˈwaɪl/','/wɜː(ɹ)θˈwaɪl/','adjective',["Doing volunteer work to help others is truly worthwhile."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mould','n.霉，霉菌；模型，铸模；性格，气质vt.用模子做，浇铸；使形成，把…铸造成','/məʊld/','/moʊld/','noun',["the oval mold of her face","a leader in the mold of her predecessors","His method of scientific investigation broke the mold and led to a new discovery."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('increasingly','adv.日益，越来越多地','','','adverb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('elbow','n.肘，肘部vt.用肘部，用肘挤','/ˈɛl.bəʊ/','/ˈɛl.boʊ/','noun',["the sides of windows, where the jamb makes an elbow with the window back","He elbowed his way through the crowd."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('salad','n.色拉，凉拌菜','/ˈsæləd/','/ˈsæləd/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('strategic','adj.对全局有重要意义的，关键的；战略的','/stɹəˈtiː.dʒɪk/','/stɹəˈtiː.dʒɪk/','adjective',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vary','v.改变；多样化','/ˈvɛəɹi/','/ˈvæɹi/','noun',["He varies his magic tricks so as to minimize the possibility that any given audience member will see the same trick twice.","You should vary your diet. Eating just bread will do you harm in the end.","His mood varies by the hour."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('readily','adv.乐意地，欣然地；容易地；很快地，立即','/ˈɹɛdɪli/','/ˈɹɛdɪli/','adverb',["The suspect readily answered all questions the police officers asked him.","readily available;  readily achievable"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stoop','v.俯身，弯腰；堕落，自贬n.弯腰，曲背','/stuːp/','/stuːp/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('upper','adj.上面的，地位较高的','/ˈʌpə/','/ˈʌpɚ/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rocket','vi.迅速上升，猛涨n.火箭','/ˈɹɒkɪt/','/ˈɹɑkɪt/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('splendid','adj.壮丽的；极好的','/ˈsplɛndɪd/','/ˈsplɛndɪd/','adjective',["a splendid sun","a splendid pageant"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('county','n.郡，县','/ˈkaʊnti/','/ˈkaʊnti/','noun',["He can''t come; he''s up in the county for agg assault."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('respondent','n.回答者；响应者；被告','','','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('episode','n.一个事件；插曲，片段；连续剧的一集','/ˈɛpɪsəʊd/','/ˈɛpɪsoʊd/','noun',["It was a most embarrassing episode in my life.","I can''t wait till next week’s episode."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('convenience','n.方便；便利设施','/kənˈviːnɪəns/','/kənˈvinjəns/','noun',["Fast food is popular because of its cost and convenience.","We will come over and begin the work at your convenience.","These are equally viable times and I propose we alternate between the two times in order to convenience as many people as possible."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('determination','n.决心，决定；确定','/dɪˌtɜːmɪˈneɪʃən/','','noun',["Through sheer determination, we managed to escape from the tornado.","a determination of blood to the head","the determination of the level of salt in sea water"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('discipline','n.纪律；训练；惩罚；学科vt.训练；惩罚，处罚','/ˈdɪ.sə.plɪn/','/ˈdɪ.sə.plɪn/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('behalf','n.利益','','','',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('evidently','adv.明显地，显然','/ˈɛvɪdəntli/','','adverb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('objective','adj.客观的，无偏见的n.目标，目的','/ɒbˈd͡ʒɛk.tɪv/','/əbˈd͡ʒɛk.tɪv/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('injure','vt.伤害，损害，使遭受损伤','/ˈɪndʒə/','/ˈɪndʒɚ/','verb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('victimize','vt.使受害，使牺牲','/ˈvɪktɪmaɪz/','/ˈvɪktɪmaɪz/','verb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('exert','vt.尽；运用','/ɪɡˈzɜːt/','/ɪɡˈzɝt/','verb',["I exerted myself in today''s training.","He considered exerting his influence on John to gain an advantage for himself."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('province','n.省；领域，范围','/ˈpɹɒvɪns/','/ˈpɹɑvɪns/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scandal','n.丑事，丑闻；流言蜚语；反感，愤慨','/ˈskændəl/','/ˈskændəl/','noun',["Their affair was reported as a scandal by most tabloids.","The incident brought considerable scandal to his family.","When their behaviour was made public it caused a great scandal."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('horrible','adj.令人恐惧的，可怕的；骇人听闻的；极讨厌的，使人不愉快的；糟透的','/ˈhɑɹɪbəl/','/ˈhɑɹɪbəl/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('estimate','vt.估计；评价n.估计；评价，看法','/ˈɛstɨmɨt/','/ˈɛstɨmɨt/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('strengthen','vt.加强，巩固','/ˈstɹɛŋ(k)θən/','/ˈstɹɛŋ(k)θən/','verb',["strengthen a muscle"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('drip','vi.滴下，漏水n.水滴；滴水声','/dɹɪp/','/dɹɪp/','verb',["Listening to the tap next door drip all night drove me mad!","Does the sink drip, or have I just spilt water over the floor?","After putting oil on the side of the salad, the chef should drip a little vinegar in the oil."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('injury','n.损害，伤害；受伤处','/ˈɪn.dʒə.ɹi/','/ˈɪn.dʒə.ɹi/','noun',["The passenger sustained a severe injury in the car accident.","Slander is an injury to the character."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('exhibit','vt.显示；陈列，展览n.展览品','/ɛɡ-/','/ɛɡ-/','noun',["The museum''s new exhibit is drawing quite a crowd.","Exhibit A is this photograph of the corpse.","He wanted to exhibit his baseball cards."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('brand','n.品牌；烙印vt.铭刻，打烙印于；加污名于，谴责','/bɹand/','/bɹand/','noun',["To burn something to brands and ashes.","Some brands of breakfast cereal contain a lot of sugar.","I didn''t appreciate his particular brand of flattery."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mushroom','vi.迅速成长n.蘑菇','/ˈmʌʃˌɹuːm/','/ˈmʌʃˌɹuːm/','noun',["Some mushrooms are edible and taste good, while others are poisonous and taste foul.","The town’s population mushroomed from 10,000 to 110,000 in five years.","We used to go mushrooming in the forest every weekend."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('alcohol','n.酒精，乙醇','/ˈæl.kə.hɒl/','/ˈæl.kə.hɑl/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('choke','vt.使窒息；塞满，塞住','/t͡ʃəʊk/','/t͡ʃəʊk/','noun',["Ever since he choked on a bone, he has refused to eat fish.","The collar of this shirt is too tight; it’s choking me.","to choke a cave passage with boulders and mud"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('proposal','n.提议，建议；求婚','/pɹəˈpəʊzəl/','/pɹəˈpəʊzəl/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inevitable','adj.不可避免的，必然的','/ɪnˈɛvɪtəbəl/','/ɪnˈɛvɪtəbəl/','noun',["We were going so fast that the collision was inevitable.","My outburst met with the inevitable punishment."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deny','vt.否定，否认；拒绝…的要求','/dɪˈnaɪ/','/dɪˈnaɪ/','verb',["I wanted to go to the party, but I was denied.","Everyone knows he committed the crime, but he still denies it.","My father denied me a good education."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('miserable','adj.痛苦的；悲惨的；令人难受的','/ˈmɪz(ə)ɹəbəl/','/ˈmɪz(ə)ɹəbəl/','noun',["He''s good at some sports, like tennis, but he''s just miserable at football.","a miserable sinner"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('recreation','n.娱乐活动，消遣','/ɹɛkɹiˈeɪʃən/','/ɹɛkɹiˈeɪʃən/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('subtract','vt.减，减去，去掉','/səbˈtɹækt/','/səbˈtɹækt/','verb',["If you subtract the $100 for gas from the total cost, it was a fairly inexpensive trip."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('allowance','n.津贴，补贴；零用钱','/əˈlaʊəns/','/əˈlaʊəns/','noun',["her meagre allowance of food or drink","to make allowance for his naivety","Tare and tret are examples of allowance."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('portable','adj.便于携带的，手提式的','/ˈpɔː(ɹ)təbl̩/','/ˈpɔː(ɹ)təbl̩/','noun',["a portable pension plan"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ancient','adj.古代的，古老的；年老的，看上去很老的','/ˈeɪn.ʃənt/','/ˈeɪn.ʃənt/','noun',["an ancient city  an ancient forest","an ancient author  an ancient empire"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('glory','n.光荣，荣誉的事；美丽','/ˈɡlo(ː)ɹi/','/ˈɡlo(ː)ɹi/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('secondary','adj.次要的，第二的；中等的；辅助的，从属的','/ˈsɛkənd(ə)ɹɪ/','/ˈsɛkənˌdɛɹi/','noun',["the secondary, or undersheriff, of the city of London","There are four secondaries in this district, each with several thousand pupils.","the work of secondary hands"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mission','n.使命，任务；使团','/ˈmɪʃn̩/','/ˈmɪʃn̩/','noun',["Many cities across the Americas grew from Spanish missions."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('attorney','n.律师，代理人','/əˈtɜː(ɹ)ni/','/əˈtɜː(ɹ)ni/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wander','vi.漫游，闲逛，漫步；偏离正道；走神，恍惚','/ˈwɒndə/','/ˈwɑndɚ/','noun',["to go for a wander in the park","baseline wander in ECG signals","to wander over the fields"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adopt','vt.收养；采用，采取；正式通过，批准','/əˈdɒpt/','/əˈdɑpt/','verb',["He adopted a new look in order to fit in with his new workmates.","These resolutions were adopted."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('oppose','vt.反对；反抗','/əˈpəʊz/','/əˈpoʊz/','verb',["There is still time to oppose this plan.","Many religious leaders oppose cloning humans.","They are opposed to any form of hierarchy."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('singular','adj.单数的；非凡的，奇特的；独一无二的','/ˈsɪŋɡjʊlə/','/ˈsɪŋɡjəlɚ/','noun',["A singular experiment cannot be regarded as scientific proof of the existence of a phenomenon.","She has a singular personality.","a man of singular gravity or attainments"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('device','n.器械，装置，设备；手段，策略','/dəˈvaɪs/','/dəˈvaɪs/','noun',["There are a number of household devices in a kitchen such as a dishwasher, a garbage disposal, or an electric can opener."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mainframe','n.主机，大型机','','','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('motor','n.发动机，电动车','/ˈməʊtə/','/ˈmoʊtɚ/','noun',["Nice motor!","On Saturday we motored down to Plymouth.","Sales were slow at first, but now things are really motoring."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('minus','adj.负的prep.减n.负数；减号','/ˈmaɪnəs/','/ˈmaɪnəs/','noun',["a minus number","minus seven degrees","He got a grade of B minus for his essay."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conservative','adj.保守的，守旧的；不时兴的，传统的n.保守的人','/kənˈsɜːvətɪv/','/kənˈsɜːvətɪv/','noun',["The curriculum committee at this university is extremely conservative.","At a conservative estimate, growth may even be negative next year."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('access','n.接近；通道，入口；接近的机会vt.存取','/ˈæksɛs/','/ˈækˌsɛs/','noun',["an access of territory"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conference','n.会议，讨论会；讨论，商谈','/ˈkɒn.fə.ɹəns/','/ˈkɒn.fə.ɹəns/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('activity','n.活动；活力；行动','/ækˈtɪ.və.ti/','/ækˈtɪ.və.ti/','noun',["Pit row was abuzz with activity.","The activity for the morning was a walk to the store.","An increasing number of sports activities are on offer at the university."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('primitive','adj.原始的，早期的；简单的；粗糙的n.原人；原始事物','/ˈpɹɪmɪtɪv/','/ˈpɹɪmɪtɪv/','noun',["primitive innocence;   the primitive church","a primitive style of dress","primitive ideas"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('advisable','adj.明智的，可取的','','','adjective',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dormitory','n.集体寝室，宿舍','/ˈdɔɹmɪˌtɔɹi/','/ˈdɔɹmɪˌtɔɹi/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('overcome','vt.战胜，克服；压倒，使受不了','/ˌəʊvəˈkʌm/','/ˌoʊvəɹˈkʌm/','noun',["to overcome enemies in battle","We shall overcome.","I was overcome with anger."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cooperate','vi.合作，协作；配合','/koʊˈɒpəɹeɪt/','/koʊˈɒpəɹeɪt/','verb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cabin','n.小屋；船舱，机舱','/ˈkæbɪn/','/ˈkæbɪn/','noun',["Abraham Lincoln was born in a log cabin.","the captain''s cabin:  Passengers shall remain in their cabins."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sum','vi.共计n.总数；金额；算术','/sʌm/','/sʌm/','noun',["The sum of 3 and 4 is 7.","We''re learning about division, and the sums are tricky.","a tidy sum"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('current','adj.当前的，通用的；流行的，流传的','/ˈkʌɹənt/','/ˈkɝɹənt/','noun',["current events;  current leaders;  current negotiations","current affairs;  current bills and coins;  current fashions"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('heel','n.脚后跟，踵；后跟','/hiːl/','/hiːl/','noun',["He drove the heel of his hand into the man''s nose.","the heel of a mast","She called to her dog to heel."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('variety','n.多样化；种类；变种','/vəˈɹaɪ.ɪ.ti/','/vəˈɹaɪ.ɪ.ti/','noun',["Variety is the spice of life."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disturb','vt.打扰，扰乱；弄乱；使不安','/dɪsˈtɜːb/','','noun',["A school of fish disturbed the water.","A mudslide disturbed the course of the river.","A disturbing film that tries to explore the mind of a serial killer."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('copper','n.铜；铜币，铜制器','/ˈkɔp.ə/','/ˈkɑ.pɚ/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('persist','vi.坚持，持续','/pəˈsɪst/','/pɚˈsɪst/','verb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('audio','adj.听觉的，声音的','/ˈɔː.di.əʊ/','/ˈɔ.di.oʊ/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('civilian','n.平民，百姓','/sɪˈvɪljən/','/sɪˈvɪljən/','noun',["Three civilians were apprehended by the soldiers and taken away in a military vehicle.","The bathroom was for employees only, so no civilians were allowed to use it.","He worked as a civilian journalist for ten years before being employed by the public broadcaster."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pump','n.泵vt.抽，泵送，打气','/pʌmp/','/pʌmp/','noun',["This pump can deliver 100 gallons of water per minute.","It takes thirty pumps to get 10 litres; he did 50 pumps of the weights.","This pump is out of order, but you can gas up at the next one."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pierce','vt.刺穿，穿孔于','/pɪəs/','/pɪɹs/','verb',["The diver pierced the surface of the water with scarcely a splash.","Can you believe he pierced his tongue?","A scream pierced the silence."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('teenager','n.青少年','/ˈtiːnˌeɪ.dʒə(ɹ)/','/ˈtiːnˌeɪ.dʒə(ɹ)/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('apart','adv.成距离，相间隔；分开，除去adj.分离的，分隔的','/əˈpɑː(ɹ)t/','/əˈpɑɹt/','adjective',["a world apart","Consider the two propositions apart.","We took the computer apart and put it back together."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('calendar','n.日历，历书，历法','/ˈkæl.ən.də/','/ˈkæl.ən.dɚ/','noun',["The three principal calendars are the Gregorian, Jewish, and Islamic calendars.","Write his birthday on the calendar hanging on the wall.","The club has a busy calendar this year."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('offensive','adj.冒犯的，无礼的；进攻的，攻击性的n.进攻，攻势','/əˈfɛnsɪv/','/əˈfɛnsɪv/','noun',["The Marines today launched a major offensive.","He took the offensive in the press, accusing his opponent of corruption.","An offensive smell."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cartoon','n.卡通画，幽默画；动画片，卡通片','/kɑːˈtuːn/','/kɑɹˈtuːn/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('speculate','v.推测，推断；投机，做投机买卖','','','verb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('launch','vt.发射，投射，发动；使下水n.发射；下水','/lɔːnt͡ʃ/','/lɔnt͡ʃ/','noun',["book launch","The navy launched another ship.","NASA launched several unmanned rockets before launching any of the Mercury astronauts."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('amid','prep.在…中间，在…之中，被…围绕','/əˈmɪd/','/əˈmɪd/','preposition',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('beloved','adj.所钟爱的，所爱戴的','','','verb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('single','adj.单一的；独身的；单程的n.单程票；','/ˈsɪŋɡəl/','/ˈsɪŋɡəl/','noun',["The Offspring released four singles from their most recent album.","He went to the party, hoping to meet some friendly singles there.","I don''t have any singles, so you''ll have to make change."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('confirm','vt.证实，肯定；确认；批准','/kənˈfɜːm/','/kənˈfɝm/','verb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cement','n.水泥，胶泥vt.黏结；巩固，使团结','/səˈmɛnt/','/səˈmɛnt/','noun',["the cement of our love","to cement a cellar floor"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('subway','n.地道；地铁','/ˈsʌbˌweɪ/','/ˈsʌbˌweɪ/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gallon','n.加仑','/ˈɡælən/','/ˈɡælən/','noun',["The pipe burst and gallons of water flooded into the kitchen."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('acquaint','vt.使认识，使了解','/əˈkweɪnt/','/əˈkweɪnt/','verb',["I think you should acquaint him with the realities of the situation."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('appoint','vt.任命，委任；约定，指定','/əˈpɔɪnt/','/əˈpɔɪnt/','verb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('elastic','adj.有弹性的，灵活的n.松紧带','/iˈlæstɪk/','/iˈlæstɪk/','noun',["running shorts use elastic to eliminate the need for a belt","The rope is somewhat elastic, so expect it to give when you pull on it.","elastic band"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('assist','vt.援助，帮助，协助','/əˈsɪst/','/əˈsɪst/','noun',["The foundation gave a much needed assist to the shelter.","He had two assists in the game.","This book will assist you in getting your life in order."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vast','adj.巨大的，大量的；浩瀚的','/vɑːst/','/væst/','noun',["The Sahara desert is vast."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('intervene','vi.干涉，调停，干预；插入，介入；干扰，打扰','','','verb',["The police had to be called to intervene in the fight.","An instant intervened between the flash and the report.","Nothing intervened to prevent the undertaking."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('undergraduate','n.大学本科生','','','noun',["After completing my undergraduate studies, I embarked on a career in publishing."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('symbol','n.象征；符号，标志','/ˈsɪmbəl/','/ˈsɪmbəl/','noun',["$ is the symbol for dollars in the US and some other countries.","The lion is the symbol of courage; the lamb is the symbol of meekness or patience.","The Apostles, Nicene Creed and the confessional books of Protestantism, such as the Augsburg Confession of Lutheranism are considered symbols."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('commercial','adj.商业的，商务的；商品化的，商业性的','/kəˈmɜːʃəl/','/kəˈmɝʃəl/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('joint','adj.连接的；共同的n.接头，接缝；关节','/dʒɔɪnt/','/dʒɔɪnt/','noun',["This rod is free to swing at the joint with the platform.","The water is leaking out of the joint between the two pipes.","The dovetail joint, while more difficult to make, is also quite strong."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reasonable','adj.通情达理的，讲道理的；合理的；公道的；尚好的，过得去的','/ˈɹiː.zən.ə.bəl/','/ˈɹiː.zən.ə.bəl/','adjective',["a reasonable demand, amount, or price","$20 a bottle is very reasonable for a good wine at a restaurant.","The builders did a reasonable job, given the short notice."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('available','adj.现成可使用的，通用的；可取的；联系的；可得到的','/əˈveɪləb(ə)l/','/əˈveɪləb(ə)l/','adjective',["We have an available candidate.","The list shows the available products in the store.","This is an available plea."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('confine','vt.限制，使局限；使不外出，禁闭','/ˈkɒnfaɪn/','/ˈkɒnfaɪn/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('advocate','vt.拥护，提倡，主张n.拥护者，提倡者；辩护者，律师','/ˈæd.və.keɪt/','/ˈæd.və.keɪt/','noun',["Since she started working with her advocate, she has become much more confident.","I like trees, but I do not advocate living in them.","We have been advocating for changes in immigration law."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('frequency','n.屡次；次数，频率','/ˈfɹiːkwənsi/','/ˈfɹiːkwənsi/','noun',["The frequency of bus service has been improved from one every 15 to one every 12 minutes.","The FAQ addresses questions that come up with some frequency.","Broadcasting live at a frequency of 98.3 megahertz, we’re your rock alternative!"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('horizontal','adj.地平的，水平的','/ˌhɒɹɪˈzɒntəl/','/ˌhɔːɹəˈzɑːntəl/','noun',["1667: As when the Sun new ris''n / Looks through the Horizontal misty Air — John Milton, Paradise Lost, Book 1, ll. 594-5"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('luggage','n.行李','/ˈlʌɡɪd͡ʒ/','/ˈlʌɡɪd͡ʒ/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lick','vt.舔，舔吃；打败，克服；轻拍，吞卷n.舔；少量，少许','/lɪk/','/lɪk/','noun',["The cat gave its fur a lick.","Give me a lick of ice cream.","a lick of paint"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('missile','n.导弹，飞弹，投射物','/ˈmɪsaɪl/','/ˈmɪsaɪl/','noun',["The Rhodians, who used leaden bullets, were able to project their missiles twice as far as the Persian slingers, who used large stones.","That missile is explosive enough to kill hundreds."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dynamic','adj.有活力的；动力的；不断变化的n.动力；动力学','/daɪˈnæ.mɪk/','/daɪˈnæ.mɪk/','noun',["Watch the dynamic between the husband and wife when they disagree.","The study of fluid dynamics quantifies turbulent and laminar flows.","If you pay attention to the dynamics as you play, it''s a very moving piece."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('satisfactory','adj.令人满意的','/sætɪsˈfækt(ə)ɹi/','/sætɪsˈfækt(ə)ɹi/','adjective',["The satisfactory results of the survey led to his promotion."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('military','adj.军事的，军用的n.军队，武装力量','/ˈmɪl.ɪ.tɹi/','/ˈmɪl.ɪ.tɛɹ.i/','noun',["He spent six years in the military.","She was dishonorably discharged from all military duties.","If you join a military force, you may end up killing people."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reluctant','adj.不情愿的，勉强的','/ɹɪˈlʌktənt/','/ɹɪˈlʌktənt/','adjective',["She was reluctant to lend him the money"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('generate','vt.发生，引起；生殖','/ˈdʒɛn.əɹ.eɪt/','/ˈdʒɛn.ə.ɹeɪt/','verb',["The discussion generated an uproar.","Adding concentrated sulphuric acid to water generates heat.","They generated many offspring."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unusual','adj.不平常的，少有的；独特的，与众不同的','/ʌnˈjuːʒuəl/','/ʌnˈjuːʒuəl/','noun',["Every once in a while, though, Idol comes across an unusual talent who just blows everyone away."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sector','n.部门，部分；防御地段，防区；扇形','/ˈsɛk.təɹ/','/ˈsɛk.təɹ/','noun',["public sector;  private sector"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('passion','n.激情，热情；酷爱','[ˈpʰæʃən]','[ˈpʰæʃən]','noun',["We share a passion for books.","It started as a hobby, but now my motorbike collection has become my passion.","We shared a night of passion."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('extreme','adj.极度的；末端的n.极端，过分','/ɛkˈstɹiːm/','/ɪkˈstɹim/','noun',["extremes of temperature","Some people go to extremes for attention on social media.","At the extreme edges, the coating is very thin."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('coil','n.卷，圈；线圈vt.卷','/kɔɪl/','/kɔɪl/','noun',["the sinuous coils of a snake","A simple transformer can be made by coiling two pieces of insulated copper wire around an iron heart.","The sailor coiled the free end of the hawser on the pier."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ensure','vt.保证；保护','/ɪnˈʃɔː/','/ɪnˈʃɔː/','verb',["I use an alarm clock to ensure that I get up on time."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('coordinate','adj.同等的，并列的vt.协调，调节n.坐标','','','noun',["Give me your coordinates and we''ll come and rescue you.","I was playing tennis for the first time, and it was difficult to coordinate.","The outfit you''re wearing doesn''t coordinate."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('organism','n.生物，有机体；机体，有机组织','/ˈɔː.ɡən.ɪ.zəm/','/ˈɔɹ.ɡən.ɪ.zəm/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('athlete','n.运动员，体育家','/ˈæθ.lit/','/ˈæθ.lit/','noun',["She''s the first athlete in her sport to obtain a corporate sponsor."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('epidemic','adj.流行性的；传染的n.流行病；传播','/ˌɛpɪˈdɛmɪk/','/ˌɛpɪˈdɛmɪk/','noun',["Epidemic hysteria occurred upon the incumbent’s reelection."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('suppose','vt.猜想，假定，让；[常用于被动语态]期望，认为应该','/səˈpəʊz/','/səˈpoʊz/','verb',["Suppose that A implies B and B implies C. Then A implies C.","I suppose we all agree that this is the best solution.","Purpose supposes foresight."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('upright','adv.挺直着，竖立着adj.垂直的；正直的，诚实的','/ˈʌpɹaɪt/','/ˈʌpɹaɪt/','noun',["I was standing upright, waiting for my orders."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('remarkable','adj.值得注意的，引人注目的；异常的，非凡的','/ɹɪˈmɑːkəbl̩/','/ɹɪˈmɑɹkəbl̩/','adjective',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('brake','v.制动；刹住，用闸使放慢速度n.闸，刹车','/bɹeɪk/','/bɹeɪk/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tube','n.管，电子管，显像管','/tjuːb/','/tjuːb/','noun',["A tube of toothpaste.","I took the tube to Waterloo and walked the rest of the way.","Are you just going to sit around all day and watch the tube?"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('naval','adj.海军的','/ˈneɪvəl/','/ˈneɪvəl/','adjective',["naval architect"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('failure','n.失败，失败的人；失灵，故障；不履行','/ˈfeɪl.jɚ/','/ˈfeɪl.jɚ/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accountancy','n.会计工作；会计学','/ə.ˈkaʊnt.ən.si/','/ə.ˈkaʊnt.ən.si/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('forge','vt.打制，锻造；伪造','/fɔːd͡ʒ/','/fɔːd͡ʒ/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('carpet','n.地毯','/ˈkɑː(ɹ)pɪt/','/ˈkɑɹpət/','noun',["After the fire, they carpeted over the blackened hardwood flooring.","Popcorn and candy wrappers carpeted the floor of the cinema."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('solve','vt.解答；解释；解决','/sɒlv/','/sɒlv/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hint','v.暗示，示意n.暗示，示意；细微的迹象；建议','/hɪnt/','/hɪnt/','noun',["I needed a hint to complete the crossword.","He gave me a hint that my breath smelt.","I could taste a hint of lemon in the wine."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('knot','vi.打结n.结；节疤；节vt.把…打成结','/nɒt/','/nɑt/','noun',["Climbers must make sure that all knots are both secure and of types that will not weaken the rope.","The nurse was brushing knots from the protesting child''s hair.","A knot can be defined as a non-self-intersecting broken line whose endpoints coincide: when such a knot is constrained to lie in a plane, then it is simply a polygon."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('demonstrate','vt.说明；论证；表露','/ˈdɛmənstɹeɪt/','/ˈdɛmənstɹeɪt/','verb',["Can you demonstrate the new tools for us?","Those people outside are demonstrating against the election results."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('region','n.地区，地带，区域；范围，幅度','/ˈɹiːd͡ʒn̩/','/ˈɹiːd͡ʒn̩/','noun',["the equatorial regions","the abdominal regions"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('support','vt.支撑；支持；供养；证实n.支持，支撑物，支持者','/səˈpɔːt/','/səˈpɔɹt/','noun',["Don''t move that beam! It''s a support for the whole platform.","The government provides support to the arts in several ways.","Sure they sell the product, but do they provide support?"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('yearly','adv.一年一度地adj.每年的','/ˈjɪəli/','/ˈjɪɹli/','noun',["Christmas is a yearly celebration."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deceive','vt.欺骗，蒙蔽，行骗','/dɪˈsiːv/','/dɪˈsiːv/','verb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('saucer','n.茶托，碟子','/ˈsɔː.sə/','/ˈsɔː.sə/','noun',["The saucer-shaped object could have been a UFO."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hire','n&vt.租用；雇用','/haɪə/','/haɪɹ/','noun',["The sign offered pedalos on hire.","When my grandfather retired, he had over twenty mechanics in his hire.","We pair up each of our new hires with one of our original hires."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('kid','v.戏弄，开玩笑n.小孩；年轻人','/kɪd/','/kɪd/','noun',["He treated the oxen like they didn''t exist, but he treated the goat kid like a puppy.","She''s a kid. It''s normal for her to have imaginary friends.","He''s been living in Los Angeles for years now, but he''s a Florida kid."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('donkey','n.驴；笨蛋','/ˈdɒŋki/','/ˈdɑŋki/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('destination','n.目的地，终点，目标','/dɛstɪˈneɪʃən/','/dɛstɪˈneɪʃən/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vertical','adj.垂直的，竖式的','/ˈvɜːtɪkəl/','/ˈvɝtɪkəl/','noun',["We offer specialised accounting software targeting various verticals."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('learning','n.学习；学问，知识','/ˈlɜːnɪŋ/','/ˈlɝnɪŋ/','verb',["learn from one''s mistakes","I learn medicine.","He just learned that he will be sacked."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('monument','n.纪念碑，纪念馆；历史遗迹','/ˈmɒnjʊmənt/','/ˈmɑnjəmənt/','noun',["There is a monument on the town green to the soldiers who died in World War I."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('misconception','n.误解','/ˌmɪskənˈsɛp.ʃən/','/ˌmɪskənˈsɛp.ʃən/','noun',["He had the misconception that the word \"misconception\" meant becoming pregnant with a girl."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('damp','adj.潮湿的，微湿的n.潮湿，湿气vt.使潮湿；使沮丧；抑制','/dæmp/','/dæmp/','noun',["to damp cloth","The lawn was still damp so we decided not to sit down."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vivid','adj.鲜艳的；生动的，栩栩如生的','/ˈvɪvɪd/','/ˈvɪvɪd/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('honey','n.蜜，蜂蜜；甜，甜蜜；[常用于称呼]宝贝儿','/ˈhʌni/','/ˈhʌni/','noun',["Honey, I''m home.","Man, there are some fine honeys here tonight!"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('screw','n.螺丝vt.固定，拧紧','/skɹuː/','/skɹuː/','noun',["the skeleton screw (Caprella);  the sand screw"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gap','n.缺口；间隔；差距；缺陷','/ɡæp/','/ɡæp/','noun',["He made a gap in the fence by kicking at a weak spot.","We can slip through that gap between the buildings.","There is a gap between the roof and the gutter."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('missing','adj.缺掉的，失踪的','/ˈmɪsɪŋ/','/ˈmɪsɪŋ/','verb',["I missed the target.","to miss an opportunity","The car just missed hitting a passer-by."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('emphasize','vt.强调，着重','/ˈɛm.fə.saɪz/','/ˈɛm.fə.saɪz/','verb',["His two-fingered gesture emphasized what he had told his boss to do with his job."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('virtue','n.善，美德；优点，长处','/-tjuː/','/ˈvɝtʃu/','noun',["Without virtue, there is no freedom."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('normal','adj.正常的，平常的；正规的，规范的','/ˈnɔːməl/','/ˈnɔɹməl/','noun',["Heavy workload is the new normal.","Organize the data into third normal form.","John is feeling normal again."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('socialist','n.社会主义者','/ˈsəʊʃəlɪst/','/ˈsoʊ.ʃə.lɪst/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gradual','adj.逐渐的，渐进的；坡度平缓的','/ˈɡɹɛdʒɘl/','/ˈɡɹædʒuəl/','noun',["a gradual increase of knowledge; a gradual decline"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('figure','v.出现；合乎情理；计算；认为，猜想n.数字；人物；算术；体形，体态；轮廓；画像，塑像；图，图形','/ˈfɪɡjɚ/','/ˈfɪɡjɚ/','noun',["a figure in bronze; a figure cut in marble","He cut a sorry figure standing there in the rain.","The muslin was of a pretty figure."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ore','n.矿，矿石','/ɔː/','/ɔɹ/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('slight','adj.轻微的，微小的v.侮慢；轻视，冷落','[sl̥l͡ɐɪʔ̚]','[sl̥l͡ɐɪʔ̚]','noun',["a slight but graceful woman","A slight stone","The sea was slight and calm"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('previous','adj.先的，前的；以前的','/ˈpɹiːvɪəs/','/ˈpɹivi.əs/','noun',["It turned out the shoplifter had a lot of previous.","He is no better than the previous Prime Minister."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('transmit','vt.传送，传递；传染；播送，发射','/tɹænsˈmɪt/','/tɹænsˈmɪt/','verb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('socialism','n.社会主义','/ˈsəʊʃəlɪzəm/','/ˈsəʊʃəlɪzəm/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('consumption','n.消耗，消费','/kənˈsʌmp.ʃən/','/kənˈsʌmp.ʃən/','noun',["The consumption of snails as food is more common in France than in England.","gross national consumption","The fire''s consumption of the forest caused ecological changes."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('argue','vi.争辩，争论vt.争论，争辩，辩论；主张；说服','/ˈɑː.ɡjuː/','/ˈɑɹ.ɡju/','verb',["He also argued for stronger methods to be used against China.","He argued his point."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('technology','n.工艺学；工艺，技术','/tɛkˈnɒlədʒi/','/tɛkˈnɒlədʒi/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('weaken','v.削弱，变弱','/ˈwikən/','/ˈwikən/','verb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('voltage','n.电压','/voʊltɪdʒ/','/voʊltɪdʒ/','noun',["Be careful when opening high-voltage equipment."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('damn','interjection.该死，见鬼〔表示很生气或失望〕adv.非常，很adj.该死的〔表示对某人或某事物生气〕','/dæm/','/dæm/','noun',["He said a few damns and left.","The new hires aren''t worth a damn.","I don''t give a damn."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('superior','adj.上级的，较高的；优越的；有优越感的，高傲的n.上级，长官','/suːˈpɪəɹi.ə(ɹ)/','/suːˈpɪɹiɚ/','noun',["Rebecca had always thought shorts were far superior to pants, as they didn''t constantly make her legs itch.","A genus is superior to a species.","the superior jaw; the superior part of an image"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('location','n.位置，场所；外景拍摄地','/ləʊˈkeɪʃən/','/loʊˈkeɪʃən/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('compensation','n.补偿，赔偿','/ˌkɒmpɛnˈseɪʃən/','/ˌkɒmpɛnˈseɪʃən/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bankrupt','adj.破产的','/ˈbæŋ.kɹəpt/','/ˈbæŋ.kɹəpt/','noun',["a bankrupt merchant","a morally bankrupt politician"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('punctual','adj.严守时刻的，准时的','/ˈpʌŋktjʊəl/','/ˈpʌŋktʃuəl/','adjective',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('advertise','vt.为…做广告，宣传；公告；登广告','/ˈadvə(ɹ)taɪz/','/ˈadvə(ɹ)taɪz/','verb',["For personal needs, advertise on the internet or in a local newspaper.","Over the air, they advertise their product on drive-time radio talk shows and TV news shows."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('compromise','v.妥协；危及；放弃n.妥协，和解，折中办法','/ˈkɒmpɹəˌmaɪz/','/ˈkɑmpɹəˌmaɪz/','noun',["a compromise of character or right","He tried to compromise the security in the computer by guessing the password."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sack','n.麻袋，包；解雇；洗劫，劫掠vt.解雇；洗劫，劫掠','/sæk/','/sæk/','noun',["The American sack of salt is 215 pounds; the sack of wheat, two bushels. — McElrath.","The sack of Rome.","He twisted his ankle sliding into the sack at second."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('software','n.软件','/ˈsɑftˌwɛɹ/','/ˈsɔftˌwɛɹ/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('seminar','n.研究班，研讨会','','','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('comparative','adj.比较的，相对的','/kəmˈpæɹ.ə.tɪv/','/kəmˈpɛɹ.ə.tɪv/','noun',["comparative anatomy"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('competition','n.竞争，比赛','/ˌkɒmpəˈtɪʃən/','/ˌkɑːmpəˈtɪʃən/','noun',["The competition for this job is strong.","The newspaper is featuring a competition to win a car.","The new stain remover was ten times more effective than the competition."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fruitful','adj.多产的，肥沃的','/ˈfɹuːtfəl/','/ˈfɹuːtfəl/','adjective',["The extra work in the office turned out to be fruitful after all—I got promoted"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('react','vi.反应，作出反应','/ɹiːˈækt/','/ɹiːˈækt/','noun',["Sad reacts only","Every body reacts on the body that impels it from its natural state."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dragon','n.龙','/ˈdɹæɡən/','/ˈdɹæɡən/','noun',["She’s a bit of a dragon.","Napoleon already warned of the awakening of the Dragon."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hesitant','adj.犹豫的；吞吞吐吐的','/ˈhɛzɪtənt/','/ˈhɛzɪtənt/','adjective',["I am hesitant to recommend him as a manager because he has a short temper."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('beyond','adv.在更远处，再往后prep.在…的那边，远于；迟于；越出','/biˈjɒnd/','/biˈjɑnd/','noun',["2017 July 13, Joseph Gamp \"Marvel release stirring new set images of Black Panther and we are BEYOND excited\" Metro (UK)","She had no reason for the conviction beyond the very inadequate one that she had seen him around London.","No swimming beyond this point."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hell','n.地狱；极大的痛苦','','','',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('feedback','n.回授，反馈，反应','/ˈfiːdˌbæk/','/ˈfiːdˌbæk/','noun',["After you hand in your essays, I will give both grades and feedback.","The show ended with a riot of feedbacking guitars.","His employees feedbacked him a lot more than he wanted."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hazard','n.危险；公害vt.尝试着做；冒…风险','/ˈhazəd/','/ˈhæzɚd/','noun',["He encountered the enemy at the hazard of his reputation and life.","The video game involves guiding a character on a skateboard past all kinds of hazards.","I''ll hazard a guess."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('justify','vt.证明…是正当的','/ˈdʒʌstɪfaɪ/','/ˈdʒʌstɪfaɪ/','verb',["How can you justify spending so much money on clothes?","Nothing can justify your rude behaviour last night.","The text will look better justified."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('voluntary','adj.自愿的，志愿的','/ˈvɒ.lən.tɹi/','/ˈvɑ.lənˌtɛ.ɹi/','noun',["If a man accidentally kills another by lopping a tree, it is not voluntary manslaughter.","a voluntary church, in distinction from an established or state church"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('connection','n.联系，关系；连接，衔接；连贯性；熟人，关系','/kəˈnɛkʃən/','/kəˈnɛkʃən/','noun',["My headache has no connection with me going out last night.","As we were the only people in the room to laugh at the joke, I felt a connection between us.","I was talking to him, but there was lightning and we lost the connection."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('proof','adj.耐…的，能防…的n.证据，证明；校样，样张','/pɹʉːf/','/pɹuf/','noun',["a proof load; a proof charge","proof against harm"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('timber','n.木材，原木；大木料，栋木','/ˈtɪmbə/','/ˈtɪmbə/','noun',["the timbers of a ship","timbering a roof"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('roar','v.吼叫，怒号，咆哮；轰鸣；大声喊出，大声表示n.呐喊声，咆哮声，吼叫声；轰鸣','/ɹɔː/','/ɹɔɹ/','noun',["the roar of a motorbike","The audience roared at his jokes.","The lioness roared to scare off the hyenas."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('presence','n.出席，到场；存在；仪表，仪态','/ˈpɹɛzəns/','/ˈpɹɛzəns/','noun',["Any painter can benefit from the presence of a live model from which to draw.","Bob never said anything about it in my presence.","Despite being less than five foot, she filled up the theatre with her stage presence."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('phase','n.阶段；方面；相，相位','','','',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('surrounding','adj.附近的；四周的','/səˈɹaʊndɪŋ/','/səˈɹaʊndɪŋ/','verb',["to surround the world"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('efficiency','n.效率；功效，效能','/ɪˈfɪʃn̩si/','/ɪˈfɪʃn̩si/','noun',["The efficiency of the planning department is deplorable.","The efficiency of this loudspeaker is 40%.","I have an efficiency available June through July."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('overhead','adv.在头顶上adj.在头顶上的，架空的n.经常费用，管理费用','/ˈəʊvəˌhɛd/','/ˈoʊvɚˌhɛd/','noun',["Network overhead is the header data that is required to route and transport data over network, whereas fork overhead is the additional time and memory cost of creating and managing new processes within operating system.","Place your luggage in the overhead lockers.","birds flying overhead"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('contract','v.缩小；订合同；感染，染上n.契约，合同','/ˈkɒntɹækt/','/ˈkɑntɹækt/','noun',["Marriage is a contract.","The mafia boss put a contract out on the man who betrayed him."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conclude','v.推断出，推论出；结束，终了；缔结，议定','/kən.ˈkluːd/','/kən.ˈkluːd/','verb',["The story concluded with a moral.","to conclude a bargain","From the evidence, I conclude that this man was murdered."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('comprehension','n.理解，理解力，领悟；理解力测验','/kɒmpɹɪˈhɛnʃn̩/','/kɒmpɹɪˈhɛnʃn̩/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('beggar','n.乞丐vt.使贫穷','/ˈbɛɡə/','/ˈbɛɡɚ/','noun',["What does that silly beggar think he''s doing?"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('leather','n.皮革，皮革制品','/ˈlɛðə/','/ˈlɛðɚ/','noun',["He leathered the ball all the way down the street."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('comb','n.梳子；鸡冠，冠状物vt.梳理；在…搜寻；彻底搜查','/kəʊm/','/koʊm/','noun',["I need to comb my hair before we leave the house","Police combed the field for evidence after the assault"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('innovative','adj.创新的，革新的','/ɪnˈnɒ.və.tɪv/','/ˈɪn.oʊˌveɪɾɪv/','adjective',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('insight','n.洞察力；洞悉；深刻见解','/ˈɪnsaɪt/','/ˈɪnsaɪt/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fabric','n.织物，纺织品；结构','/ˈfæb.ɹɪk/','/ˈfæb.ɹɪk/','noun',["cloth of a beautiful fabric","the fabric of our lives","cotton fabric"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('revolutionary','adj.革命的，革新的n.革命者','/-ˈljuː-/','/ˌɹɛvəˈluʃənɛɹi/','noun',["revolutionary agitators","a revolutionary new tool"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('following','adj.接着的，下列的n.一批追随者','/ˈfɒləʊɪŋ/','/ˈfɑloʊɪŋ/','verb',["Follow that car!","B follows A in the alphabet.","Follow these instructions to the letter."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('exact','adj.确切的，精确的vt.强求，索取','/ɪɡˈzækt/','/ɪɡˈzækt/','verb',["to exact tribute, fees, or obedience from someone","to exact revenge on someone","He paid the exact debt."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('indoor','adv.在室内，在户内adj.室内的','/ˈɪndɔː/','/ˈɪndɔː/','adjective',["These fireworks are not for indoor use!"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('force','vt.强迫；用力推动，用力打开n.军队，兵力；暴力，武力；力，力气；影响力，效力','/fɔːs/','/fɔɹs/','noun',["the force of an appeal, an argument, or a contract","police force","show of force"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('centigrade','adj.百分度的；摄氏的','','','noun',["a temperature of 34 centigrades"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sexual','adj.性的，两性的；性别的','/ˈsɛksjuəl/','/ˈsɛkʃuəl/','noun',["Women face sexual discrimination in the workplace.","Giving oral sex is my favorite sexual act.","She''s a very sexual woman"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sympathetic','adj.同情的；和谐的；赞同的，支持的；合意的','/ˌsɪmpəˈθɛtɪk/','/ˌsɪmpəˈθɛtɪk/','adjective',["John looked very upset. I gave him a sympathetic look.","Sympathetic magic is based on imitation or correspondence.","Sympathetic innervation involves epinephrine."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('freight','n.货运；货物；运费vt.运送','/fɹeɪt/','/fɹeɪt/','noun',["The freight was more expensive for cars than for coal.","The freight shifted and the trailer turned over on the highway.","They shipped it ordinary freight to spare the expense."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('range','v.变动；漫游，四处搜索；使排列成行n.一系列；范围；射程，距离；脉；射击场','/ɹeɪndʒ/','/ɹeɪndʒ/','noun',["We sell a wide range of cars.","One can use the speed of sound to estimate the range of a lightning flash.","This missile''s range is 500 kilometres."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('distribution','n.分发，分配；分布','/ˌdɪstɹəˈbjuːʃən/','/ˌdɪstɹəˈbjuːʃən/','noun',["The distribution of my little rock magazine is about 3,000.","The wealth distribution became extremely skewed in the kleptocracy.","The declarer had 3-6-2-2 distribution."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tyre','n.轮胎，车胎','/taɪə(ɹ)/','/taɪə(ɹ)/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('derive','v.取得；起源','/dəˈɹaɪv/','/dəˈɹaɪv/','verb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('capacity','n.容量；能力，才能；能量；身份，地位','/kəˈpæsɪti/','/kəˈpæsɪti/','noun',["It was hauling a capacity load.","Its capacity rating was 150 tons per hour, but its actual maximum capacity was 200 tons per hour.","There will be a capacity crowd at Busch stadium for the sixth game."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cope','vi.应付，处理','/kəʊp/','/kəʊp/','verb',["I thought I would never be able to cope with life after the amputation, but I have learned how to be happy again."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('overseas','adv.在海外adj.在海外的','/ˌəʊvəˈsiːz/','/ˌəʊvəˈsiːz/','adjective',["Overseas branches of the company are doing well.","Overseas Chinese communities exist in North and South America.","Her overseas trip went well."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('impress','vi.给人印象，引人注目vt.给…深刻印象；印，压印n.印记；特征','/ˈɪmpɹɛs/','/ˈɪmpɹɛs/','noun',["You impressed me with your command of Urdu.","Henderson impressed in his first game as captain.","That first view of the Eiger impressed itself on my mind."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('confess','vt.供认，坦白；承认','/kənˈfɛs/','/kənˈfɛs/','verb',["I confess to spray-painting all over that mural!"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('leak','v.漏；泄露n.漏洞','/liːk/','/liːk/','noun',["a leak in a boat","The babies'' diapers had big leaks.","The leaks by Chelsea Manning showed the secrets of the US military."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ghost','n.鬼，灵魂，鬼魂','/ɡəʊst/','/ɡoʊst/','noun',["Everyone believed that the ghost of an old lady haunted the crypt.","not a ghost of a chance; the ghost of an idea","ghost slug; ghostberry; ghostflower; ghost crab; ghost bat"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('feature','vi.起重要作用n.特征，特色；面貌；特写，专题节目；故事片vt.突出；由…主演','/ˈfiːtʃə/','/ˈfitʃɚ/','noun',["one of the features of the landscape"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lean','v.倾斜；屈身；靠adj.瘦的；贫瘠的','/liːn/','/liːn/','noun',["The trees had various leans toward gaps in the canopy.","She leaned out of the window.","I’m leaning towards voting Conservative in the next election.  The Hispanic vote leans Democratic."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flat','adv.平直地；直截了当地adj.平的；固定的；漏气的；平淡的；沉闷的；浅的n.一套房间，单元住宅','/flæt/','/flæt/','noun',["She liked to walk in her flats more than in her high heels.","a flat of strawberries","The land around here is flat."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('recall','v.回忆；召回，叫回；收回，撤销','','','noun',["He was recalled to service after his retirement."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('leap','v.跳，跃n.跳跃；骤变','/liːp/','/liːp/','noun',["It''s quite a leap to claim that those cloud formations are evidence of UFOs.","to leap a wall or a ditch","to leap a horse across a ditch"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('waterproof','adj.不透水的，防水的','','','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('barber','n.理发师','/ˈbɑː.bə/','/ˈbɑɹ.bɚ/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('precise','adj.精确的，准确的；严谨的','/pɹɪˈsaɪs/','/pɹɪˈsaɪs/','verb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sensible','adj.明智的；合情理的；有知觉的','/ˈsen.sə.bl̩/','/ˈsɛn.sɪ.bl̩/','noun',["a sensible thermometer"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('objection','n.反对，异议；反对的理由','/əbˈdʒɛkʃən/','/əbˈdʒɛkʃən/','noun',["I have no objection to any person''s religion."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dispute','v.争论，争执；对…表示异议n.争论','/ˈdɪs.pjuːt/','/dɪsˈpjuːt/','noun',["Some residents disputed the proposal, saying it was based more on emotion than fact.","to dispute assertions or arguments"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('precious','adj.珍贵的，宝贵的','/ˈpɹɛʃəs/','/ˈpɹɛʃəs/','noun',["The crown had many precious gemstones.   This building work needs site access, and tell the city council that I don''t care about a few lorry tyre ruts across their precious grass verge.","My precious daughter is to marry.","He spent hours painting the eyes of the portrait, which his fellow artists regarded as a bit precious."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('observation','n.注意，观察；言论，评论；观察资料','/ˌɒbzəˈveɪʃ(ə)n/','/-ˈveɪʃn̩/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tremble','vi.发抖，哆嗦；摇动n.颤抖；摇晃，摇动','/ˈtɹɛmbl̩/','/ˈtɹɛmbl̩/','noun',["Her lip started to tremble as she burst into tears"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('suspect','adj.可疑的，不信任的vt.疑有；推测；对…表示怀疑n.嫌疑犯，可疑分子','/ˈsʌs.pɛkt/','/ˈsʌs.pɛkt/','noun',["to suspect the presence of disease","to suspect the truth of a story","I suspect him of being the thief."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('apologize','vi.道歉，谢罪，认错','/əˈpɒləd͡ʒaɪz/','/əˈpɑləd͡ʒaɪz/','verb',["My correspondent apologized for not answering my letter."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inhabitant','n.居民，住户','/ɪnˈhæ.bɪ.tənt/','/ɪnˈhæ.bɪ.tənt/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fraction','n.小部分；片断；分数','/ˈfɹæk.ʃən/','/ˈfɹæk.ʃən/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('filter','v.过滤，透；走漏n.滤纸，过滤嘴','/ˈfɪltə/','/ˈfɪltɚ/','noun',["He runs an email filter to catch the junk mail.","He''s got no filter, and he''s always offending people as a result.","If (1) the universal set (here, the set of natural numbers) were called a \"large\" set, (2) the superset of any \"large\" set were also a \"large\" set, and (3) the intersection of a pair of \"large\" sets were also a \"large\" set, then the set of all \"large\" sets would form a filter."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sunlight','n.日光，阳光','/ˈsʌnˌlaɪt/','/ˈsʌnˌlaɪt/','noun',["Sunlight on the skin gives you vitamin D.","I''ll meet you at the docks at sunrise.","Did you see the beautiful sunrise this morning?"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('site','n.地点，场所vt.使坐落在；设置','/saɪt/','/saɪt/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('emotion','n.情感，感情；激动','/iˈmoʊʃən/','/iˈmoʊʃən/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('massive','adj.大的，大而重的；大块的；大量的，大规模的','/ˈmæs.ɪv/','','noun',["karst massives in western Georgia","Big up to the Croydon massive!","Compared to its counterparts from World War II, the Abrams main battle tank is truly massive."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cease','v.停止，终止','/siːs/','/siːs/','noun',["And with that, his twitching ceased.","And with that, he ceased twitching."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('assess','vt.对估价；评价，评论','/əˈsɛs/','/əˈsɛs/','verb',["He assessed the situation.","A $10.00 late fee will be assessed on all overdue accounts.","Once you''ve submitted a tax return, the Tax Department will assess the amount of tax you still owe."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('asset','n.资产，财产；有价值的特性或技能，优点','/ˈæsɪt/','/ˈæsɪt/','noun',["These shares are a valuable asset."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('owe','vt.欠；应把…归功于；感激，感恩','/əʊ/','/oʊ/','verb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scarce','adj.缺乏的，不足的；稀少的，罕见的','/ˈskɛəs/','/ˈskɛɚs/','adjective',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('minimum','adj.最低的，最小的n.最低限度；最小量','/ˈmɪn.ɪ.məm/','/ˈmɪn.ə.məm/','noun',["We need a minimum of three staff members on duty at all time.","He always tries to get away with doing the minimum.","The Maunder minimum of the Sun reportedly corresponded to a period of great cold on Earth."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('queue','vi.排队等候n.长队，行列','/kjuː/','/kjuː/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mathematical','adj.数学的','/ˌmæθəˈmætɪkəl/','/ˌmæθəˈmætɪkəl/','adjective',["a mathematical problem","The team has a mathematical chance of being promoted, but they need to win the next seven matches."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('apology','n.道歉，认错，谢罪','/əˈpɒl.ə.dʒi/','/əˈpɒl.ə.dʒi/','noun',["The CEO made a public apology for the scandal, and promised full cooperation with the authorities.","The Apology of Socrates.","a poor apology for a hotel room"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('magic','adj.有魔力的；魔术的n.魔法，魅力','/ˈmadʒɪk/','/ˈmædʒɪk/','noun',["a magic moment","a magic show; a magic trick","— I cleaned up the flat while you were out. — Really? Magic!"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('argument','n.争论，辩论；理由；说理，论证','/ˈɑːɡjʊmənt/','/ˈɑɹɡjumənt/','noun',["Parameters are like labeled fillable blanks used to define a function whereas arguments are passed to a function when calling it, filling in those blanks.","The altitude is the argument of the refraction."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reveal','vt.揭露，泄露；展现，显示','/ɹəˈviːl/','/ɹəˈviːl/','noun',["The comedian had been telling us about his sleep being disturbed by noise. Then came the reveal: he was sleeping on a bed in a department store."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('data','n.资料，数据','/ˈdeɪtə/','/ˈdætə/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('theoretical','adj.理论的','/ˌθi.əˈɹɛtɪkəl/','/ˌθi.əˈɹɛtɪkəl/','adjective',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adequate','adj.足够的；可以胜任的','','','verb',["an adequate definition"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('utter','adj.完全的，彻底的vt.发出，说，讲','/ˈʌtə/','/ˈʌtɚ/','adjective',["utter ruin; utter darkness"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('onion','n.洋葱；洋葱类植物','/ˈʌnjən/','/ˈʌnjən/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vibrate','v.颤动','/vaɪˈbɹeɪt/','/ˈvaɪ.bɹeɪt/','noun',["Please put your cellphones on vibrate for the duration of the meeting.","Her mind was vibrating with excitement.","to vibrate a sword or a staff"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('drum','v.有节奏地敲击n.鼓，鼓状物；圆桶','/ˈdɹʌm/','/ˈdɹʌm/','noun',["Replace the drum unit of your printer.","The restaurant ordered ketchup in 50-gallon drums."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sausage','n.香肠，腊肠','/ˈsɑsɪd͡ʒ/','/ˈsɔsɪd͡ʒ/','noun',["my little sausage"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hopeful','adj.有希望的','/ˈhəʊpfəl/','/ˈhəʊpfəl/','noun',["Several presidential hopefuls are campaigning in New Hampshire this week.","I am hopeful that I will recover from the disease."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tremendous','adj.极大的，非常的；精彩的，了不起的','/tɹəˈmɛndəs/','/tɹəˈmɛndəs/','adjective',["Van Beethoven''s ninth symphony is a tremendous piece of music.","There was a tremendous outpouring of support."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('condense','v.冷凝，凝结；浓缩，压缩，简缩','/kənˈdɛns/','/kənˈdɛns/','verb',["An abridged dictionary can be further condensed to pocket size.","Water condenses on the window on cold days because of the warm air inside."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('barrier','n.栅栏；检票口；屏障；障碍，隔阂','/ˈbæɹi.ə(ɹ)/','/ˈbæɹi.əɹ/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('realistic','adj.现实的；实际可行的；现实主义的；逼真的','/ˌɹiːjəˈlɪstɪk/','/ˌɹiːjəˈlɪstɪk/','adjective',["A realistic appraisal of the situation.","A realistic novel about the Victorian poor."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('justice','n.正义，公正；司法','/ˈdʒʌs.tɪs/','/ˈdʒʌs.tɪs/','noun',["the justice of a description","Justice was served.","to demand justice"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('create','vt.创造；引起，产生','/kɹiːˈeɪt/','/kɹiːˈeɪt/','verb',["You can create the color orange by mixing yellow and red.","A sudden chemical spill on the highway created a chain‐collision which created a record traffic jam.","Henry VIII created him a Duke.   Last month, the queen created two barons."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('criminal','adj.犯罪的，刑事的n.犯人，罪犯，刑事犯','/ˈkɹɪmənəl/','/ˈkɹɪmənəl/','noun',["His long criminal record suggests that he is a dangerous man.","Printing such asinine opinions is criminal!"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tag','vi.尾随n.附加语；标签vt.给…加上标签','/teɪɡ/','/teɪɡ/','noun',["The subwoofer in the trunk was so loud, it vibrated the tag like an aluminum can.","The tag was applied at second for the final out.","The  tag conveys sarcasm in Internet slang."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('notebook','n.笔记本','/ˈnəʊtˌbʊk/','/ˈnəʊtˌbʊk/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('curious','adj.好奇的；奇怪的','/ˈkjɔː-/','/ˈkjɝ.i.əs/','adjective',["Young children are naturally curious about the world and everything in it.","The platypus is a curious creature, with fur like a mammal and a beak like a bird."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('indirect','adj.间接的，婉转的','/ˌɪndaɪˈɹɛkt/','/ˌɪndaɪˈɹɛkt/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('individual','adj.个别的；独特的n.个人，个体','/ˌɘndɘˈvɘd͡ʒɘl/','/ˌɪndəˈ-/','noun',["He is an unusual individual.","As we can''t print them all together, the individual pages will have to be printed one by one.","individual personal pension; individual cream cakes"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('resource','n.资源；财力；应付办法，谋略','/ɹɪˈsɔːs/','/ɹɪˈsɔɹs/','noun',["a man/woman of resource"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ugly','adj.丑陋的；可怕的','/ˈʌɡli/','/ˈʌɡli/','noun',["He played an ugly trick on us.","an ugly temper; to feel ugly","With all this competition, expect things to get ugly."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nuisance','n.讨厌的东西','/ˈnjuːsəns/','/ˈn(j)uːsəns/','noun',["a public nuisance"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tax','n.税，税款；负担vt.对…征税；使负担重，使费尽力气','/tæks/','/tæks/','noun',["a heavy tax on time or health"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('earthquake','n.地震，大震荡','/ˈɜːθkweɪk/','/ˈɝθkweɪk/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('excitement','n.刺激，激动，兴奋；令人兴奋的事，刺激的因素','/ɪkˈsaɪtmənt/','/ɪkˈsaɪtmənt/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nightmare','n.噩梦；可怕的事物，无法摆脱的恐惧','/ˈnaɪt.mɛə/','/naɪt.mɛəɹ/','noun',["I had a nightmare that I tried to run but could neither move nor breathe.","Cleaning up after identity theft can be a nightmare of phone calls and letters."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cord','n.细绳，粗线，索；灯芯绒裤','/kɔːd/','/kɔɹd/','noun',["He looped some cord around his fingers.","spermatic cord; spinal cord; umbilical cord; vocal cords"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ending','n.结尾，结局；死亡','/ˈɛndɪŋ/','/ˈɛndɪŋ/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('core','n.果实的心；核心，要点','/kɔː/','/kɔɹ/','noun',["the core of an apple or quince","the core of a square","the core of a subject"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('council','n.理事会，委员会','/ˈkaʊn.səl/','/ˈkaʊn.səl/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('enforce','vt.实施，执行；强制，强迫，迫使','/ɪnˈfɔːs/','/ɪnˈfɔːs/','verb',["The police are there to enforce the law.","The victim was able to enforce his evidence against the alleged perpetrator.","to enforce a passage"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('embassy','n.大使馆；大使馆全体成员','/ˈɛmbəsi/','/ˈɛmbəsi/','noun',["The American embassy to France is located in Paris."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('departure','n.离开，起程，出发；背离，违背','/dɪˈpɑː(ɹ)tjə(ɹ)/','','noun',["The departure was scheduled for noon.","There are several significant departures, however, from current practice.","The area is computed by latitudes and departures."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dash','vi.猛冲，击碎vt.使猛撞，飞奔；溅n.猛冲；破折号','/dæʃ/','/dæʃ/','noun',["Add a dash of vinegar.","There is a dash of craziness in his personality.","Aren''t we full of dash this morning?"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('concrete','adj.实在的，具体的n.混凝土；具体物','/kɵnˈkɹiːt/','/ˈkɑnkɹiːt/','noun',["The road was made of concrete that had been poured in large slabs.","I hate grass, so I concreted over my lawn.","Fuzzy videotapes and distorted sound recordings are not concrete evidence that bigfoot exists."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('penalty','n.处罚，惩罚；罚金','/ˈpɛnəlti/','/ˈpɛnəlti/','noun',["The penalty for his crime was to do hard labor.","A penalty was called when he tripped up his opponent."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sociology','n.社会学','/ˌsəʊsiːˈɒlədʒiː/','/ˌsəʊsiːˈɒlədʒiː/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('link','v.连接，联系n.环节，联系，纽带','/lɪŋk/','/lɪŋk/','noun',["Click the hyperlink to go to the next page.","Copy the hyperlink and paste it into an email.","The mayor’s assistant serves as the link to the media."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flee','v.逃走，逃掉，逃离；避开，逃避','/fliː/','/fliː/','verb',["The prisoner tried to flee, but was caught by the guards.","Many people fled the country as war loomed.","Ethereal products flee once freely exposed to air."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('distinct','adj.与其他不同的；清楚的，明显的','/dɪsˈtɪŋkt/','/dɪsˈtɪŋkt/','adjective',["Her voice was distinct despite the heavy traffic.","Horses are distinct from zebras.","Olga''s voice is quite distinct because of her accent."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scale','n.大小，规模；等级，级别；天平，磅秤；比例；刻度，标度；鳞vt.攀登，爬越','/skeɪl/','/skeɪl/','noun',["Please rate your experience on a scale from 1 to 10.","The Holocaust was insanity on an enormous scale.","This map uses a scale of 1:10."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('recovery','n.恢复，痊愈；追回，寻回，收复','/ɹəˈkʌvəɹi/','/ɹəˈkʌvəɹi/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hedge','v.用篱笆围；避免直接回答n.篱笆，树篱；障碍物','/hɛdʒ/','/hɛdʒ/','noun',["He trims the hedge once a week.","A hedge is an investment position intended to offset potential losses/gains that may be incurred by a companion investment. In simple language, a hedge is used to reduce any substantial losses/gains suffered by an individual or an organization."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tune','n.调子；和谐vt.调整，调节；为调音','/tjuːn/','/t(j)un/','noun',["Your engine needs a good tune.","This piano is not in tune.","to tune a piano or a violin"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('weep','v.哭泣，流泪；渗出','/wiːp/','/wiːp/','noun',["Sometimes you just have to have a good weep.","a weeping spring, which discharges water slowly"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('aware','adj.知道的，意识到的','/əˈweːɹ/','/əˈwɛɚ/','adjective',["Stay aware! Don''t let your guard down.","Are you aware of what is being said about you?"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('drama','n.戏剧，剧本；戏剧性事件','/ˈdɹæmə/','/ˈdɹɑmə/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('security','n.安全，保障；抵押品；证券','/sɪˈkjɔːɹəti/','/səˈkjɔɹ.ɪˌti/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('limp','adj.软的；不强壮的v.〔因一腿受伤而〕跛行，一瘸一拐地走n.跛行','/lɪmp/','/lɪmp/','noun',["She walks with a limp.","The bomber limped home on one engine.","The business limped through the recession"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('award','n.奖，奖品；判定vt.授予，给予；判给，裁定','/əˈwɔːd/','/əˈwɔɹd/','noun',["the arbitrators awarded damages to the complainant","Four or five of these medals are awarded every year.","He was awarded the Nobel Prize for Literature."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('organize','vt.组织，把…编组；使有条理','/ˈɔːɡənaɪz/','/ˈɔːɡənaɪz/','verb',["an organized being","to organize an anthem","the workers decided to organize; their next task was to organize the workers at the steel mill"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('marriage','n.结婚，婚姻；婚礼','/ˈmæɹɪdʒ/','/ˈmæɹɪdʒ/','noun',["You should enter marriage for love.","You are cordially invited to the marriage of James Smith and Jane Doe."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stove','n.炉，火炉，电炉','/stəʊv/','/stoʊv/','noun',["to stove feathers","to stove orange trees"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('alarm','n.惊恐；忧虑；警报vt.使惊恐；使担心','/əˈlɑːm/','/əˈlɑɹm/','noun',["The clock radio is a friendlier version of the cold alarm by the bedside.","You should set the alarm on your watch to go off at seven o''clock."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('weed','v.除草n.杂草，野草','/wiːd/','/wiːd/','noun',["If it isn''t in a straight line or marked with a label, it''s a weed."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('continual','adj.连续的；频频的','/kənˈtɪnjuəl/','/kənˈtɪnjuəl/','adjective',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('herd','n.兽群，牧群vt.放牧','/hɜːd/','/hɝd/','noun',["a herd of cattle","Sheep herd on many hills.","He is employed to herd the goats."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('limb','n.肢，臂，腿；树枝','/lɪm/','/lɪm/','noun',["They limbed the felled trees before cutting them into logs."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('balloon','n.气球，玩具气球','/bəˈluːn/','/bəˈlun/','noun',["the balloon of St. Paul''s Cathedral in London","His stomach ballooned from eating such a large meal."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('motion','v.打手势，示意n.运动；手势，眼色，动作；提议','/ˈməʊʃən/','/ˈmoʊʃən/','noun',["The motion to amend is now open for discussion.","He motioned for me to come closer."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('limited','adj.有限的','/ˈlɪmɪtɪd/','/ˈlɪmɪtɪd/','verb',["I''m limiting myself to two drinks tonight.","The sequence limits on the point a.","a limiting friar"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('idle','adj.空闲的，懒散的；无用的v.虚度，无所事事','/ˈaɪd(ə)l/','/ˈaɪd(ə)l/','noun',["My computer hibernates after it has been idle for 30 minutes.","idle workmen","an idle fellow"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('confidence','n.信任，信赖；信心，自信','/ˈkɒnfɪdəns/','/ˈkɒnfɪdəns/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('arbitrary','adj.随心所欲的，专断的','/ˈɑɹ.bɪ.tɹɛ(ə).ɹi/','/ˈɑɹ.bɪ.tɹɛ(ə).ɹi/','noun',["Benjamin Franklin''s designation of \"positive\" and \"negative\" to different charges was arbitrary.","The equation is true for an arbitrary value of x."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fearful','adj.害怕的，可怕的；不安的，忧虑的','/ˈfɪəfəl/','/ˈfɪɹfəl/','adjective',["a fearful boy"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accent','n.口音，腔调；重音','/ˈak.sənt/','/ˈak.sənt/','noun',["In the word \"careful\", the accent is placed on the first syllable.","At this hotel, the accent is on luxury.","The name Cézanne is written with an acute accent."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('passive','adj.被动的，消极的','/ˈpæs.ɪv/','/ˈpæs.ɪv/','noun',["He remained passive during the protest.","a passive balloon; a passive aeroplane; passive flight, such as gliding and soaring"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fertilizer','n.肥料','/ˈfɜːtəlaɪzə/','/ˈfɜːtəlaɪzə/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lorry','n.运货汽车，卡车','/ˈlɒɹi/','/ˈlɒɹi/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('carrier','n.运输工具，运载工具；带菌者；载重架，置物架','/ˈkæ.ɹɪ.ə/','/ˈkæ.ɹɪ.ə/','noun',["aircraft carrier","inert carrier gas, which transports a chemical reactant"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fragment','v.成碎片n.碎片，破片，碎块','/ˈfɹæɡmənt/','/ˈfɹæɡmənt/','noun',["I heard a small fragment of the conversation."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('corresponding','adj.相应的，符合的','/ˌkɒɹəˈspɒndɪŋ/','/ˌkɑɹəˈspɑndɪŋ/','verb',["I''ve been corresponding with my German pen pal for three years."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('response','n.回答，答复；反应，响应','/ɹɪˈspɒns/','','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('treaty','n.条约，协议，协定','/ˈtɹiːti/','/ˈtɹiːti/','noun',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('responsive','adj.响应的；敏感的，易受影响的','/ɹɪˈspɒnsɪv/','/ɹɪˈspɒnsɪv/','adjective',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ounce','n.盎司','/aʊns/','/aʊns/','noun',["He didn''t feel even an ounce of regret for his actions."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('challenge','n.挑战；邀请比赛；艰巨的任务；怀疑，质问vt.反对，公然反抗；向…挑战；对…质疑','/ˈtʃæl.əndʒ/','/ˈtʃæl.əndʒ/','noun',["We challenged the boys next door to a game of football.","to challenge the accuracy of a statement or of a quotation","The sentinel challenged us with \"Who goes there?\""]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('emit','vt.散发；发射；发表','/iˈmɪt/','/iˈmɪt/','verb',[]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('category','n.种类，类，类别','/ˈkætəˌɡɔɹi/','/ˈkætəˌɡɔɹi/','noun',["I wouldn''t put this book in the same category as the author''s first novel.","Just as a monoid consists of an underlying set with a binary operation \"on top of it\" which is closed, associative and with an identity, a category consists of an underlying digraph with an arrow composition operation \"on top of it\" which is transitively closed, associative, and with an identity at each object. In fact, a category''s composition operation, when restricted to a single one of its objects, turns that object''s set of arrows (which would all be loops) into a monoid."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rival','adj.竞争的，对抗的n.竞争对手，敌手；可与匹敌的人vt.与…竞争；与…匹敌，比得上','/ˈɹaɪvəl/','/ˈɹaɪvəl/','noun',["Chris is my biggest rival in the 400-metre race.","As a social historian, he has no rival.","to rival somebody in love"]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('intend','vt.想要，打算；意思是；打算使','/ɪnˈtɛnd/','/ɪnˈtɛnd/','verb',["He intends to go to university."]);
INSERT INTO CET4 (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('snap','v.咔嚓折断，啪地绷断；吧嗒一声；猛咬；厉声说话，怒声责骂adj.仓促的，突然的n.吧嗒声；快照','/snæp/','/snæp/','noun',["We took a few snaps of the old church before moving on.","a ginger snap","I can fix most vacuum cleaners in a snap."]);
